:[]},{\"value\":\"印\",\"font\":\"仿宋\",\"size\":21,\"bold\":true,\"italic\":false,\"underline\":false,\"strikeout\":false,\"rowFlex\":\"right\",\"dashArray\":[]},{\"value\":\" \",\"font\":\"仿宋\",\"size\":21,\"bold\":true,\"italic\":false,\"underline\":false,\"strikeout\":false,\"rowFlex\":\"right\",\"dashArray\":[]},{\"value\":\"份\",\"font\":\"仿宋\",\"size\":21,\"bold\":true,\"italic\":false,\"underline\":false,\"strikeout\":false,\"rowFlex\":\"right\",\"dashArray\":[]},{\"value\":\"（\",\"font\":\"仿宋\",\"size\":21,\"bold\":true,\"italic\":false,\"underline\":false,\"strikeout\":false,\"rowFlex\":\"right\",\"dashArray\":[]},{\"value\":\"群\",\"font\":\"仿宋\",\"size\":21,\"bold\":true,\"italic\":false,\"underline\":false,\"strikeout\":false,\"rowFlex\":\"right\",\"dashArray\":[]},{\"value\":\"发\",\"font\":\"仿宋\",\"size\":21,\"bold\":true,\"italic\":false,\"underline\":false,\"strikeout\":false,\"rowFlex\":\"right\",\"dashArray\":[]},{\"value\":\"）\",\"font\":\"仿宋\",\"size\":21,\"bold\":true,\"italic\":false,\"underline\":false,\"strikeout\":false,\"rowFlex\":\"right\",\"dashArray\":[]},{\"value\":\" \",\"font\":\"仿宋\",\"size\":21,\"bold\":true,\"italic\":false,\"underline\":false,\"strikeout\":false,\"rowFlex\":\"right\",\"dashArray\":[]},{\"value\":\" \",\"font\":\"仿宋\",\"size\":21,\"bold\":true,\"italic\":false,\"underline\":false,\"strikeout\":false,\"rowFlex\":\"right\",\"dashArray\":[]},{\"value\":\" \",\"font\":\"仿宋\",\"size\":21,\"bold\":true,\"italic\":false,\"underline\":false,\"strikeout\":false,\"rowFlex\":\"right\",\"dashArray\":[]},{\"value\":\" \",\"font\":\"仿宋\",\"size\":21,\"bold\":true,\"italic\":false,\"underline\":false,\"strikeout\":false,\"rowFlex\":\"right\",\"dashArray\":[]},{\"value\":\" \",\"font\":\"仿宋\",\"size\":21,\"bold\":true,\"italic\":false,\"underline\":false,\"strikeout\":false,\"rowFlex\":\"right\",\"dashArray\":[]},{\"value\":\" \",\"font\":\"仿宋\",\"size\":21,\"bold\":true,\"italic\":false,\"underline\":false,\"strikeout\":false,\"rowFl