INSERT INTO `airag_flow` (`id`, `create_by`, `create_time`, `update_by`, `update_time`, `sys_org_code`, `tenant_id`, `application_name`, `name`, `descr`, `icon`, `chain`, `design`, `status`, `metadata`, `trigger_cron`) VALUES ('1905189468558671874', 'jeecg', '2025-03-27 17:25:41', 'admin', '2025-11-27 16:48:47', 'A04', NULL, 'jeecg', 'PMP考试宝典', '', 'https://jeecgdev.oss-cn-beijing.aliyuncs.com/temp/pmp_1743067580648.png', 'THEN(\n    start.tag(\'start-node\'),\n    WHEN(\n        knowledge.tag(\'168290518600351744\'),\n        llm.tag(\'168290871702028288\')\n    ).tag(\"168290518600351744\"),\n    llm.tag(\'168290861241434112\'),\n    end.tag(\'168290315671535616\')\n).tag(\"start-node\")', '{\"nodes\":[{\"id\":\"start-node\",\"type\":\"start\",\"x\":300,\"y\":397,\"properties\":{\"text\":\"开始\",\"remarks\":\"\",\"options\":{},\"inputParams\":[{\"field\":\"content\",\"name\":\"用户问题\",\"type\":\"string\",\"required\":true},{\"field\":\"history\",\"name\":\"历史记录\",\"type\":\"string[]\",\"required\":true}],\"outputParams\":[],\"height\":92,\"width\":332}},{\"id\":\"168290315671535616\",\"type\":\"end\",\"x\":1644,\"y\":348,\"properties\":{\"text\":\"结束\",\"options\":{\"outputText\":true,\"outputContent\":\"{{res}}\"},\"inputParams\":[],\"outputParams\":[{\"field\":\"text\",\"name\":\"res\",\"nodeId\":\"168290861241434112\"}],\"height\":92,\"width\":332}},{\"id\":\"168290518600351744\",\"type\":\"knowledge\",\"x\":693,\"y\":209,\"properties\":{\"text\":\"知识库\",\"options\":{\"knowIds\":[\"1905186756806918146\"],\"topNumber\":5,\"similarity\":0.7},\"inputParams\":[{\"field\":\"content\",\"nodeId\":\"start-node\"}],\"outputParams\":[{\"field\":\"documents\",\"name\":\"文档列表\",\"type\":\"object[]\"},{\"field\":\"data\",\"name\":\"文档内容\",\"type\":\"string\"}],\"height\":92,\"width\":332}},{\"id\":\"168290861241434112\",\"type\":\"llm\",\"x\":1181,\"y\":350,\"properties\":{\"text\":\"总结LLM\",\"options\":{\"model\":{\"modeId\":\"1890232564262739969\",\"params\":{\"model\":\"OpenAI\",\"temperature\":0.4}},\"history\":3,\"messages\":[{\"role\":\"system\",\"content\":\"你是一个智能知识助手，旨在综合知识库和大型语言模型(LLM)的返回数据，以高效、准确地回答用户提出的问题。请遵循以下要求：\\n\\n## 目标：\\n- 提供准确、相关且易于理解的回答，结合知识库和LLM的信息。\\n\\n## 技能：\\n1. 能够快速检索并整合来自不同知识库的信息。\\n2. 理解用户问题的上下文，并提供清晰的答案。\\n3. 具备自然语言处理能力，以便流畅表达复杂信息。\\n\\n## 工作流：\\n1. 接收用户问题并进行解析，识别关键要素。\\n2. 从综合知识库和LLM中获取相关数据，确保信息的准确性和完整性。\\n3. 将获取的信息进行整合，形成清晰、简洁的回答。\\n\\n## 输出格式：\\n- 每次回答应以简洁明了的句子呈现，必要时可以添加示例或补充信息。\\n\\n## 限制：\\n- 不得提供未经验证的信息或个人隐私数据。\\n- 所有数据需标注来源，不确定信息用[需核实]标记。\\n- 自动过滤涉及偏见或违法内容，替换为[合规表达]。\"},{\"role\":\"user\",\"content\":\"知识库返回数据：{{knowRes}}\\n\\nLLM返回数据：{{llmRes}}\\n用户问题：{{userQue}}\"}]},\"inputParams\":[{\"field\":\"data\",\"name\":\"knowRes\",\"nodeId\":\"168290518600351744\"},{\"field\":\"text\",\"name\":\"llmRes\",\"nodeId\":\"168290871702028288\"},{\"field\":\"content\",\"name\":\"userQue\",\"nodeId\":\"start-node\"}],\"outputParams\":[{\"field\":\"text\",\"name\":\"回复内容\",\"type\":\"string\"}],\"height\":166,\"width\":332}},{\"id\":\"168290871702028288\",\"type\":\"llm\",\"x\":692,\"y\":521,\"properties\":{\"text\":\"LLM\",\"options\":{\"model\":{\"modeId\":\"1890232564262739969\",\"params\":{\"model\":\"OpenAI\",\"temperature\":0.7}},\"history\":3,\"messages\":[{\"role\":\"system\",\"content\":\"# 角色：PMP知识专家\\nPMP知识专家致力于项目管理知识的传播与应用，帮助项目经理提升技能和管理能力。\\n\\n## 目标：\\n1. 为项目管理提供权威的知识支持。\\n2. 帮助项目经理解决在项目管理中遇到的实际问题。\\n\\n## 技能：\\n1. 精通项目管理的各项理论和工具。\\n2. 熟悉PMP认证流程及考试内容。\\n3. 能够进行项目风险评估与管理。\\n\\n## 工作流：\\n1. 评估项目经理的需求与挑战，识别关键问题。\\n2. 提供相关的项目管理知识、工具和最佳实践建议。\\n3. 指导项目经理制定和实施有效的项目管理计划。\\n\\n## 输出格式：\\n- 提供清晰的建议与解决方案，使用简洁明了的语言，适合项目经理理解和应用。\\n\\n## 限制：\\n- 所有建议需基于现有的PMP知识体系，避免个人主观意见。\\n- 不得提供未经验证的信息或数据，所有数据需标注来源，需核实的信息用[需核实]标记。\"},{\"role\":\"user\",\"content\":\"{{question}}\"}]},\"inputParams\":[{\"field\":\"content\",\"name\":\"question\",\"nodeId\":\"start-node\"}],\"outputParams\":[{\"field\":\"text\",\"name\":\"回复内容\",\"type\":\"string\"}],\"height\":166,\"width\":332}}],\"edges\":[{\"id\":\"168290518604546048\",\"type\":\"base-edge\",\"sourceNodeId\":\"start-node\",\"targetNodeId\":\"168290518600351744\",\"sourceAnchorId\":\"start-node_output\",\"targetAnchorId\":\"168290518600351744_input\",\"pointsList\":[{\"x\":466,\"y\":382},{\"x\":566,\"y\":382},{\"x\":427,\"y\":194},{\"x\":527,\"y\":194}]},{\"id\":\"168290861245628416\",\"type\":\"base-edge\",\"sourceNodeId\":\"168290518600351744\",\"targetNodeId\":\"168290861241434112\",\"sourceAnchorId\":\"168290518600351744_output\",\"targetAnchorId\":\"168290861241434112_input\",\"pointsList\":[{\"x\":859,\"y\":194},{\"x\":959,\"y\":194},{\"x\":915,\"y\":298},{\"x\":1015,\"y\":298}]},{\"id\":\"168290871706222592\",\"type\":\"base-edge\",\"sourceNodeId\":\"start-node\",\"targetNodeId\":\"168290871702028288\",\"sourceAnchorId\":\"start-node_output\",\"targetAnchorId\":\"168290871702028288_input\",\"pointsList\":[{\"x\":466,\"y\":382},{\"x\":566,\"y\":382},{\"x\":426,\"y\":469},{\"x\":526,\"y\":469}]},{\"id\":\"168291272883011584\",\"type\":\"base-edge\",\"sourceNodeId\":\"168290871702028288\",\"targetNodeId\":\"168290861241434112\",\"sourceAnchorId\":\"168290871702028288_output\",\"targetAnchorId\":\"168290861241434112_input\",\"pointsList\":[{\"x\":858,\"y\":469},{\"x\":958,\"y\":469},{\"x\":915,\"y\":298},{\"x\":1015,\"y\":298}]},{\"id\":\"168292930635530240\",\"type\":\"base-edge\",\"sourceNodeId\":\"168290861241434112\",\"targetNodeId\":\"168290315671535616\",\"sourceAnchorId\":\"168290861241434112_output\",\"targetAnchorId\":\"168290315671535616_input\",\"pointsList\":[{\"x\":1347,\"y\":298},{\"x\":1447,\"y\":298},{\"x\":1378,\"y\":333},{\"x\":1478,\"y\":333}]}]}', 'enable', '{\"outputs\":[{\"field\":\"outputText\",\"type\":\"string\"}],\"inputs\":[{\"field\":\"content\",\"name\":\"用户问题\",\"type\":\"string\"},{\"field\":\"history\",\"name\":\"历史记录\",\"type\":\"string[]\"}]}', NULL);
INSERT INTO `airag_flow` (`id`, `create_by`, `create_time`, `update_by`, `update_time`, `sys_org_code`, `tenant_id`, `application_name`, `name`, `descr`, `icon`, `chain`, `design`, `status`, `metadata`, `trigger_cron`) VALUES ('1917103567932604417', 'jeecg', '2025-04-29 14:28:03', 'admin', '2025-11-27 16:56:38', 'A04', NULL, 'jeecg', 'AI解析Excel数据_JAVA增强', '', '', 'THEN(\n    start.tag(\'start-node\'),\n    enhanceJava.tag(\'180204885804785664\'),\n    llm.tag(\'180211780498169856\'),\n    end.tag(\'180204420713758720\')\n).tag(\"start-node\")', '{\"nodes\":[{\"id\":\"start-node\",\"type\":\"start\",\"x\":300,\"y\":376,\"properties\":{\"text\":\"开始\",\"remarks\":\"\",\"options\":{},\"inputParams\":[{\"field\":\"content\",\"name\":\"用户问题\",\"type\":\"string\",\"required\":false},{\"field\":\"history\",\"name\":\"历史记录\",\"type\":\"string[]\",\"required\":false},{\"field\":\"pageNo\",\"name\":\"页码\",\"type\":\"number\",\"required\":false},{\"field\":\"pageSize\",\"name\":\"每页数量\",\"type\":\"number\",\"required\":false},{\"field\":\"bizData\",\"name\":\"文件路径\",\"type\":\"string\",\"required\":false}],\"outputParams\":[],\"height\":92,\"width\":332}},{\"id\":\"180204420713758720\",\"type\":\"end\",\"x\":1648,\"y\":398,\"properties\":{\"text\":\"结束\",\"options\":{\"outputText\":true,\"outputContent\":\"{{res}}\"},\"inputParams\":[],\"outputParams\":[{\"field\":\"text\",\"name\":\"res\",\"nodeId\":\"180211780498169856\"}],\"height\":136,\"width\":332}},{\"id\":\"180204885804785664\",\"type\":\"enhanceJava\",\"x\":747,\"y\":329,\"properties\":{\"text\":\"Java 增强\",\"options\":{\"enhance\":{\"type\":\"spring\",\"path\":\"jimuDataReader\"}},\"inputParams\":[{\"field\":\"bizData\",\"name\":\"bizData\",\"nodeId\":\"start-node\"}],\"outputParams\":[{\"field\":\"datas\",\"name\":\"返回结果\",\"type\":\"object[]\",\"required\":false},{\"field\":\"fields\",\"name\":\"字段列表\",\"type\":\"string[]\",\"required\":false}],\"height\":158,\"width\":332}},{\"id\":\"180211780498169856\",\"type\":\"llm\",\"x\":1229,\"y\":419,\"properties\":{\"text\":\"LLM\",\"options\":{\"model\":{\"modeId\":\"1890232564262739969\",\"params\":{\"model\":\"OpenAI\",\"temperature\":0.7}},\"history\":3,\"messages\":[{\"role\":\"system\",\"content\":\"将以下数据整理成目标格式输出\\n## 工作流程：\\n1. 读取用户的数据\\n3. 组装最终输出的json\\n⸻\\n## 数据示例:data\\n```\\n{{data}}\\n```\\n## 数据示例:fields\\n```\\n{{fields}}\\n```\\n⸻\\n## 输出json格式\\n{\\n  \\\"data\\\": [\\n    {\\n      \\\"amount\\\": \\\"100\\\",\\n      \\\"month\\\": \\\"1\\\",\\n      \\\"areaname\\\": \\\"华北\\\",\\n      \\\"year\\\": \\\"2020\\\",\\n      \\\"price\\\": \\\"5\\\",\\n      \\\"dept\\\": \\\"河北\\\",\\n      \\\"settleamount\\\": \\\"100\\\"\\n    },\\n    {\\n      \\\"amount\\\": \\\"200\\\",\\n      \\\"month\\\": \\\"2\\\",\\n      \\\"areaname\\\": \\\"华北\\\",\\n      \\\"year\\\": \\\"2020\\\",\\n      \\\"price\\\": \\\"5\\\",\\n      \\\"dept\\\": \\\"河北\\\",\\n      \\\"settleamount\\\": \\\"200\\\"\\n    },\\n  ],\\n  \\\"total\\\": 100,\\n  \\\"count\\\": 100\\n}\\n* total: 分页数，对应数据的总分页数\\n* count: 数据总数，对应数据的总数\\n\\n\\n## 输出格式\\n* 直接返回JSON数据，不要解释，不要md语法，不要换行符，不要有注释。\\n* 统一将key转换成英文，下划线分隔\\n* 确保输出的json格式正确完整。\"},{\"role\":\"user\",\"content\":\"将数据转换为目标格式\"}]},\"inputParams\":[{\"field\":\"datas\",\"name\":\"data\",\"nodeId\":\"180204885804785664\"},{\"field\":\"fields\",\"name\":\"fileds\",\"nodeId\":\"180204885804785664\"}],\"outputParams\":[{\"field\":\"text\",\"name\":\"回复内容\",\"type\":\"string\"}],\"height\":180,\"width\":332}}],\"edges\":[{\"id\":\"180211805085179904\",\"type\":\"base-edge\",\"sourceNodeId\":\"180211780498169856\",\"targetNodeId\":\"180204420713758720\",\"sourceAnchorId\":\"180211780498169856_output\",\"targetAnchorId\":\"180204420713758720_input\",\"pointsList\":[{\"x\":1395,\"y\":360},{\"x\":1495,\"y\":360},{\"x\":1382,\"y\":361},{\"x\":1482,\"y\":361}]},{\"id\":\"180228761381183488\",\"type\":\"base-edge\",\"sourceNodeId\":\"start-node\",\"targetNodeId\":\"180204885804785664\",\"sourceAnchorId\":\"start-node_output\",\"targetAnchorId\":\"180204885804785664_input\",\"pointsList\":[{\"x\":466,\"y\":361},{\"x\":566,\"y\":361},{\"x\":481,\"y\":281},{\"x\":581,\"y\":281}]},{\"id\":\"180511280701620224\",\"type\":\"base-edge\",\"sourceNodeId\":\"180204885804785664\",\"targetNodeId\":\"180211780498169856\",\"sourceAnchorId\":\"180204885804785664_output\",\"targetAnchorId\":\"180211780498169856_input\",\"pointsList\":[{\"x\":913,\"y\":281},{\"x\":1013,\"y\":281},{\"x\":963,\"y\":360},{\"x\":1063,\"y\":360}]}]}', 'enable', '{\"outputs\":[{\"field\":\"outputText\",\"type\":\"string\"}],\"inputs\":[{\"field\":\"content\",\"name\":\"用户问题\",\"required\":false,\"type\":\"string\"},{\"field\":\"history\",\"name\":\"历史记录\",\"required\":false,\"type\":\"string[]\"},{\"field\":\"pageNo\",\"name\":\"页码\",\"required\":false,\"type\":\"number\"},{\"field\":\"pageSize\",\"name\":\"每页数量\",\"required\":false,\"type\":\"number\"},{\"field\":\"bizData\",\"name\":\"文件路径\",\"required\":false,\"type\":\"string\"}]}', NULL);
INSERT INTO `airag_flow` (`id`, `create_by`, `create_time`, `update_by`, `update_time`, `sys_org_code`, `tenant_id`, `application_name`, `name`, `descr`, `icon`, `chain`, `design`, `status`, `metadata`, `trigger_cron`) VALUES ('1952634605517447170', 'admin', '2025-08-05 15:35:43', 'admin', '2026-01-23 18:30:13', 'A04', NULL, 'jeecg', 'AI生成简历', '', '', 'THEN(\n    start.tag(\'start-node\'),\n    llm.tag(\'215734195065536512\'),\n    enhanceJava.tag(\'215740280715427840\'),\n    end.tag(\'215735188368998400\')\n).tag(\"start-node\")', '{\"nodes\":[{\"id\":\"start-node\",\"type\":\"start\",\"x\":300,\"y\":404,\"properties\":{\"text\":\"开始\",\"remarks\":\"\",\"options\":{\"cronTrigger\":{\"enabled\":false,\"cronExp\":\"0 0 0 * * ?\",\"beginTime\":null,\"endTime\":null,\"inputParams\":{},\"custom\":{\"time\":{\"second\":0,\"minute\":0},\"hour\":{\"mode\":\"every\"},\"day\":{\"type\":\"day\",\"day\":{\"mode\":\"every\"}},\"month\":{\"mode\":\"every\"}}}},\"inputParams\":[{\"field\":\"content\",\"name\":\"个人简介\",\"type\":\"string\",\"required\":true},{\"field\":\"history\",\"name\":\"历史记录\",\"type\":\"string[]\",\"required\":false},{\"field\":\"profile\",\"name\":\"基础信息\",\"type\":\"string\",\"required\":true},{\"field\":\"images\",\"name\":\"图片\",\"type\":\"picture\",\"required\":false}],\"outputParams\":[],\"height\":92,\"width\":332}},{\"id\":\"215734195065536512\",\"type\":\"llm\",\"x\":746,\"y\":404,\"properties\":{\"text\":\"生成word文档\",\"options\":{\"model\":{\"modeId\":\"1897481367743143938\",\"params\":{\"model\":\"deepseek\",\"temperature\":0.7}},\"history\":3,\"messages\":[{\"role\":\"system\",\"content\":\"### 核心指令（必须100%遵守）\\n你必须只输出可被Java的JSON.parse()正确解析的JSON数组，禁止输出任何解释、注释、换行符（除JSON内部合法换行）或JSON以外的文字。若生成的JSON存在任何不合法/不完整问题，必须先自动修正，再输出最终结果。\\n### 一、JSON语法强制规则（违反则直接修正）\\n1. 输出仅为纯JSON数组，外层无任何引号/包裹符，数组括号必须成对闭合，无缺失/多余；\\n2. 所有键名（key）必须用英文双引号包裹，禁止单引号/无引号/中文引号；\\n3. 所有分隔符（逗号、冒号、大括号、中括号）必须是英文符号，禁止中文符号（如，：【】｛｝）；\\n4. 字符串值中的特殊字符（换行符、双引号）必须正确转义：\\n   - 换行符用 `\\\\n` 表示（禁止直接换行）；\\n   - 字符串内的双引号需转义为 `\\\\\\\"`；\\n5. 禁止出现语法错误：无多余逗号（如 [{},]）、无缺失逗号、无未闭合的括号、无乱码/不可见字符；\\n6. 输出的JSON必须是**完整的**，禁止截断/缺失内容（如list的valueList未结束、数组未闭合）。\\n### 二、业务规则强制要求（违反则自动补充/修正）\\n1. 字段基础规则：\\n   - 每个对象必须包含\\\"key\\\"字段（值可为空字符串 \\\"\\\"）；\\n   - \\\"type\\\"字段仅允许取值：\\\"title\\\"、\\\"list\\\"、\\\"\\\"；\\n2. title类型强制规则：\\n   - type=\\\"title\\\"时，必须同时包含\\\"level\\\"（取值：first~sixth）、\\\"valueList\\\"（数组）、\\\"value\\\"字段；\\n   - \\\"value\\\"字段**必须以 `\\\\n` 结尾**，且不能为空（默认值：\\\"\\\\n\\\"）；\\n   - \\\"valueList\\\"数组内的每个元素必须包含\\\"value\\\"字段，支持font/size/bold/rowFlex等样式字段；\\n3. list类型强制规则：\\n   - type=\\\"list\\\"时，必须同时包含\\\"listType\\\"（ul/ol）、\\\"listStyle\\\"（disc/decimal/circle/square/checkbox）、\\\"valueList\\\"（非空数组）字段；\\n   - \\\"valueList\\\"数组内的每个元素必须包含\\\"value\\\"字段，不能为空；\\n4. 其他类型规则：\\n   - type=\\\"separator\\\"时，必须包含\\\"dashArray\\\"字段（数组，如 [1]）；\\n   - 主动换行必须使用 `{ \\\"type\\\": \\\"\\\", \\\"value\\\": \\\"\\\\n\\\" }`，不同对象之间不自动换行；\\n   - 所有字符串值禁止为空（无内容时填空字符串 \\\"\\\"，禁止null）。\\n### 三、生成后自检流程（必须执行）\\n1. 第一步：检查语法合法性\\n   - 验证是否能被Java JSON.parse()解析（模拟校验：无语法错误、符号正确、括号闭合）；\\n   - 若存在语法错误，立即修正（如单引号转双引号、补充缺失括号、删除多余逗号）；\\n2. 第二步：检查业务完整性\\n   - 遍历所有对象，检查title类型是否缺失level/value字段，缺失则补充（level默认second，value默认\\\"\\\\n\\\"）；\\n   - 检查list类型是否缺失listType/listStyle/valueList字段，缺失则补充（listType默认ul，listStyle默认disc，valueList默认空数组 []）；\\n   - 检查title的value是否以\\\"\\\\n\\\"结尾，未结尾则补充；\\n3. 第三步：检查输出完整性\\n   - 验证JSON数组是否完整闭合，无截断/缺失内容；\\n   - 验证输出内容仅为JSON数组，无任何额外字符。\\n### 四、生成示例（参考此格式/规则）\\n[\\n    {\\n        \\\"type\\\": \\\"title\\\",\\n        \\\"level\\\": \\\"first\\\",\\n        \\\"valueList\\\": [\\n            {\\n                \\\"value\\\": \\\"个人简历\\\",\\n                \\\"font\\\": \\\"微软雅黑\\\",\\n                \\\"size\\\": 26,\\n                \\\"bold\\\": true,\\n                \\\"rowFlex\\\": \\\"center\\\"\\n            }\\n        ],\\n        \\\"value\\\": \\\"\\\\n\\\",\\n        \\\"key\\\": \\\"\\\"\\n    },\\n    {\\n        \\\"type\\\": \\\"\\\",\\n        \\\"value\\\": \\\"\\\\n\\\",\\n        \\\"key\\\": \\\"\\\"\\n    },\\n    {\\n        \\\"type\\\": \\\"list\\\",\\n        \\\"listType\\\": \\\"ul\\\",\\n        \\\"listStyle\\\": \\\"disc\\\",\\n        \\\"valueList\\\": [\\n            { \\\"value\\\": \\\"合法的列表项\\\", \\\"key\\\": \\\"\\\" }\\n        ],\\n        \\\"key\\\": \\\"\\\"\\n    }\\n]\\n### 五、最终输出要求\\n1. 仅输出修正后的完整JSON数组，无任何其他文字；\\n2. 输出前必须完成上述所有自检步骤，确保100%符合Java解析规范；\\n3. 生成的JSON需结构完整、字段齐全，禁止出现截断/缺失（如list未结束、数组未闭合）。\"},{\"role\":\"user\",\"content\":\"请根据以上字段和示例，生成一个完整的个人简历文档 JSON。\\n- 至少包含基础信息、个人优势、工作经历、项目经理、教育经历等模块。\\n- 若基础数据不足，可以适当生成参考数据。\\n- 用户信息如下：\\n基础资料：{{base}}\\n简介：{{profile}}\"}],\"showToolExecution\":false},\"inputParams\":[{\"field\":\"profile\",\"name\":\"base\",\"nodeId\":\"start-node\"},{\"field\":\"content\",\"name\":\"profile\",\"nodeId\":\"start-node\"}],\"outputParams\":[{\"field\":\"text\",\"name\":\"回复内容\",\"type\":\"string\"}],\"height\":180,\"width\":332}},{\"id\":\"215735188368998400\",\"type\":\"end\",\"x\":1779,\"y\":408,\"properties\":{\"text\":\"结束\",\"options\":{\"outputText\":false,\"outputContent\":\"\"},\"inputParams\":[],\"outputParams\":[{\"field\":\"result\",\"name\":\"resp\",\"nodeId\":\"215740280715427840\"}],\"height\":114,\"width\":332}},{\"id\":\"215740280715427840\",\"type\":\"enhanceJava\",\"x\":1316,\"y\":405,\"properties\":{\"text\":\"Java 增强\",\"options\":{\"model\":{\"modeId\":\"1890232564262739969\",\"params\":{\"model\":\"OpenAI\",\"temperature\":0.7,\"timeout\":60}},\"history\":3,\"messages\":[{\"role\":\"system\",\"content\":\"# 角色：JSON检验和修复专家\\n你是一位专门负责检验和修复JSON字符串的专家，确保其能被Java的`JSON.parse()`方法成功解析，并返回修复后的、可解析的JSON字符串原文。\\n## 目标：\\n1. 接收用户提供的JSON字符串，诊断其语法错误。\\n2. 智能修复常见的JSON格式问题（如引号缺失、尾随逗号、注释等），使其符合标准JSON规范。\\n3. 输出修复后的、可直接用于`JSON.parse()`的JSON字符串原文。\\n## 技能：\\n1. **深度语法分析**：精准识别JSON字符串中的语法错误位置和类型（如未闭合的引号、括号或花括号，错误的键值分隔符，非法字符等）。\\n2. **上下文感知修复**：根据JSON结构上下文，智能推断并应用最合理的修复方案（例如，为未加引号的键名添加双引号，移除对象或数组末尾的非法逗号）。\\n3. **标准合规性**：严格遵循IETF RFC 8259 JSON数据交换标准，确保输出为有效JSON。\\n4. **最小改动原则**：在保证修复有效的前提下，尽可能保持原始字符串的结构和意图，只修改必要的部分。\\n## 工作流：\\n1. **接收与初步检验**：接收用户输入的字符串，尝试使用`JSON.parse()`进行解析。若解析成功，则直接返回原字符串并告知其有效。\\n2. **错误诊断与定位**：若解析失败，捕获`SyntaxError`异常，分析错误信息以定位问题的大致位置和类型。\\n3. **详细扫描与修复**：逐字符扫描整个字符串，结合错误定位，系统性地检查并修复以下常见问题：\\n* 为未使用双引号的属性名（key）添加双引号。\\n* 确保所有字符串值由双引号包裹。\\n* 移除对象字面量`{}`或数组字面量`[]`中最后一个元素后的尾随逗号。\\n* 将单引号替换为双引号。\\n* 移除JavaScript风格的注释（`//` 单行注释， `/* */` 多行注释）。\\n* 转义字符串中未转义的控制字符（如换行符`\\\\n`、制表符`\\\\t`）。\\n* 检查并修正括号`[]`和花括号`{}`的配对与嵌套。\\n4. **验证与输出**：对修复后的字符串再次尝试`JSON.parse()`。若成功，则输出修复后的JSON字符串原文\\n## 输出格式：\\n- **当JSON有效时**：输出原始字符串。\\n- **当JSON被成功修复时**：然后换行输出修复后的JSON字符串原文。\\n## 限制：\\n- 仅处理语法错误，不验证JSON数据的业务逻辑或语义正确性。\\n- 对于歧义过大或结构严重损坏（如大量缺失内容）的JSON，可能无法修复，此时应清晰说明原因。\\n- 所有输出必须是纯文本格式，仅包含上述指定的提示信息和JSON字符串本身，不添加任何额外的Markdown代码块标记（如 ```json ```）。\\n- 严格遵守最小改动原则，避免对原始数据做出不必要的、可能改变其原意的修改。\"},{\"role\":\"user\",\"content\":\"{{word}}\"}],\"enhance\":{\"path\":\"jeecgDemoAiWordGen\",\"type\":\"spring\"}},\"inputParams\":[{\"field\":\"text\",\"name\":\"resp\",\"nodeId\":\"215734195065536512\",\"customValue\":\"\"}],\"outputParams\":[{\"field\":\"result\",\"name\":\"返回结果\",\"type\":\"string\"}],\"height\":158,\"width\":332}}],\"edges\":[{\"id\":\"215734195073925120\",\"type\":\"base-edge\",\"sourceNodeId\":\"start-node\",\"targetNodeId\":\"215734195065536512\",\"sourceAnchorId\":\"start-node_output\",\"targetAnchorId\":\"215734195065536512_input\",\"pointsList\":[{\"x\":466,\"y\":389},{\"x\":566,\"y\":389},{\"x\":480,\"y\":345},{\"x\":580,\"y\":345}],\"properties\":{\"runStatus\":\"\"}},{\"id\":\"215740398487289856\",\"type\":\"base-edge\",\"sourceNodeId\":\"215740280715427840\",\"targetNodeId\":\"215735188368998400\",\"sourceAnchorId\":\"215740280715427840_output\",\"targetAnchorId\":\"215735188368998400_input\",\"pointsList\":[{\"x\":1482,\"y\":357},{\"x\":1582,\"y\":357},{\"x\":1513,\"y\":382},{\"x\":1613,\"y\":382}],\"properties\":{\"runStatus\":\"\"}},{\"id\":\"279144043506167808\",\"type\":\"base-edge\",\"sourceNodeId\":\"215734195065536512\",\"targetNodeId\":\"215740280715427840\",\"sourceAnchorId\":\"215734195065536512_output\",\"targetAnchorId\":\"215740280715427840_input\",\"pointsList\":[{\"x\":912,\"y\":345},{\"x\":1012,\"y\":345},{\"x\":1050,\"y\":357},{\"x\":1150,\"y\":357}],\"properties\":{\"runStatus\":\"\"}}]}', 'enable', '{\"outputs\":[{\"field\":\"result\",\"name\":\"resp\",\"nodeId\":\"215740280715427840\"}],\"inputs\":[{\"field\":\"content\",\"name\":\"个人简介\",\"required\":true,\"type\":\"string\"},{\"field\":\"history\",\"name\":\"历史记录\",\"required\":false,\"type\":\"string[]\"},{\"field\":\"profile\",\"name\":\"基础信息\",\"required\":true,\"type\":\"string\"},{\"field\":\"images\",\"name\":\"图片\",\"required\":false,\"type\":\"picture\"}]}', '');
INSERT INTO `airag_flow` (`id`, `create_by`, `create_time`, `update_by`, `update_time`, `sys_org_code`, `tenant_id`, `application_name`, `name`, `descr`, `icon`, `chain`, `design`, `status`, `metadata`, `trigger_cron`) VALUES ('1988073273760501762', 'admin', '2025-11-11 10:36:20', 'admin', '2025-11-27 16:58:06', 'A05A01A01', NULL, 'jeecg', 'AI图文写作', '', '', 'THEN(\n    start.tag(\'start-node\'),\n    llm.tag(\'251170889153376256\'),\n    llm.tag(\'251190209648521216\'),\n    llm.tag(\'251190922428542976\'),\n    llm.tag(\'251246385341919232\'),\n    end.tag(\'251191126401740800\')\n).tag(\"start-node\")', '{\"nodes\":[{\"id\":\"start-node\",\"type\":\"start\",\"x\":332.8947368421053,\"y\":589.0526315789475,\"properties\":{\"text\":\"开始\",\"remarks\":\"\",\"options\":{},\"inputParams\":[{\"field\":\"content\",\"name\":\"目的地\",\"type\":\"string\",\"required\":true},{\"field\":\"history\",\"name\":\"历史记录\",\"type\":\"string[]\",\"required\":false},{\"field\":\"from\",\"name\":\"出发地\",\"type\":\"string\",\"required\":true},{\"field\":\"time\",\"name\":\"出发时间\",\"type\":\"string\",\"required\":true},{\"field\":\"peopleNum\",\"name\":\"人数\",\"type\":\"number\",\"required\":true}],\"outputParams\":[],\"height\":92,\"width\":332}},{\"id\":\"251170889153376256\",\"type\":\"llm\",\"x\":685.9473684210526,\"y\":381.05263157894734,\"properties\":{\"text\":\"意图和需求分析\",\"options\":{\"model\":{\"modeId\":\"1890232564262739969\",\"params\":{\"model\":\"OpenAI\",\"temperature\":0.7}},\"history\":3,\"messages\":[{\"role\":\"system\",\"content\":\"# 角色\\n你是自驾游攻略生成的需求分析师\\n\\n## 目标：\\n- 分析用户提供的主题信息，归纳整理出实际需求列表。\\n\\n## 技能：\\n1. 信息提取与分析能力\\n2. 旅游规划与建议能力\\n3. 数据查询与整合能力\\n\\n## 工作流：\\n1. 收集用户提供的主题信息并进行分类。\\n2. 确定用户的目标和需求，并归纳整理。\\n3. 列出需要查询的资料和天气、路况信息。\\n\\n## 输出格式：\\n- 列表形式，包含目标和需求、查询资料列表、天气和路况信息。\\n\\n## 限制：\\n- 不得提供未经过验证的信息。\\n- 所有数据需标注来源，不确定信息用[需核实]标记。\"},{\"role\":\"user\",\"content\":\"出发地：{{from}}\\n目的地：{{userQuestion}}\\n计划时间：{{time}}\\n人数：{{peopleNum}}\"}]},\"inputParams\":[{\"field\":\"content\",\"name\":\"userQuestion\",\"nodeId\":\"start-node\"},{\"field\":\"from\",\"name\":\"from\",\"nodeId\":\"start-node\"},{\"field\":\"time\",\"name\":\"time\",\"nodeId\":\"start-node\"},{\"field\":\"peopleNum\",\"name\":\"peopleNum\",\"nodeId\":\"start-node\"}],\"outputParams\":[{\"field\":\"text\",\"name\":\"回复内容\",\"type\":\"string\"}],\"height\":180,\"width\":332}},{\"id\":\"251190209648521216\",\"type\":\"llm\",\"x\":943.2631578947365,\"y\":632.0526315789475,\"properties\":{\"text\":\"资料查询\",\"options\":{\"model\":{\"modeId\":\"1890232564262739969\",\"params\":{\"model\":\"OpenAI\",\"temperature\":0.7}},\"history\":30,\"messages\":[{\"role\":\"system\",\"content\":\"## 角色\\n\\n\\n你是一名 自驾游资料查询师（DataAgent），专注于为下游的“攻略生成Agent”提供精准、结构化的自驾游资料。\\n\\n\\n------\\n\\n\\n## 职责目标\\n 1. 根据输入内容（出发地、目的地、行程需求等），直接执行资料查询任务，不再向用户提问。\\n 2. 收集并整理以下四类信息：\\n  - 🚗 路线与导航规划信息\\n  - 🏞️ 沿途及目的地的景点和游玩项目\\n  - 🏨 住宿与周边美食信息\\n  - ☁️ 沿途及目的地天气信息\\n 3. 输出清晰、结构化的数据结果，供下一个Agent生成攻略使用。\\n\\n\\n------\\n\\n\\n## 能力与工具\\n\\n\\n- maps 工具\\n - 查询路线与导航规划信息（距离、时长、推荐路线、途经地）。\\n - 查询沿途及目的地的住宿与餐饮信息。\\n - 查询沿途及目的地的实时或近期天气信息。\\n\\n\\n- search 工具\\n - 查询沿途及目的地的景点、游玩项目、特色体验、门票及评价等。\\n\\n\\n------\\n\\n\\n## 工作流程\\n 1. 接收任务\\n  - 使用用户提供的现有信息（不提问、不二次确认）。\\n 2. 资料查询\\n  - 调用 maps 工具 获取路线、住宿、美食、天气。\\n  - 调用 search 工具 获取景点和游玩项目。\\n 3. 资料整理\\n  - 将查询结果按类型整理成结构化资料包。\\n  - 每条数据需注明来源（maps / search）。\\n 4. 结果输出\\n  - 输出格式清晰，便于下游Agent直接使用。\\n\\n\\n------\\n\\n\\n## 输出格式示例\\n\\n\\n```\\n{\\n  \\\"route_info\\\": [\\n    {\\n      \\\"from\\\": \\\"北京\\\",\\n      \\\"to\\\": \\\"张家口\\\",\\n      \\\"distance\\\": \\\"220km\\\",\\n      \\\"duration\\\": \\\"3小时\\\",\\n      \\\"route_detail\\\": \\\"经京藏高速G6\\\",\\n      \\\"source\\\": \\\"maps\\\"\\n    }\\n  ],\\n  \\\"sights\\\": [\\n    {\\n      \\\"name\\\": \\\"崇礼滑雪场\\\",\\n      \\\"tags\\\": [\\\"滑雪\\\", \\\"冬季运动\\\"],\\n      \\\"description\\\": \\\"亚洲知名滑雪胜地\\\",\\n      \\\"source\\\": \\\"search\\\"\\n    }\\n  ],\\n  \\\"hotels\\\": [\\n    {\\n      \\\"name\\\": \\\"张家口云顶假日酒店\\\",\\n      \\\"rating\\\": \\\"4.6\\\",\\n      \\\"address\\\": \\\"崇礼区奥运大道88号\\\",\\n      \\\"source\\\": \\\"maps\\\"\\n    }\\n  ],\\n  \\\"foods\\\": [\\n    {\\n      \\\"name\\\": \\\"张家口烧麦\\\",\\n      \\\"type\\\": \\\"地方特色\\\",\\n      \\\"recommendation\\\": \\\"崇礼老街美食街\\\",\\n      \\\"source\\\": \\\"maps\\\"\\n    }\\n  ],\\n  \\\"weather\\\": [\\n    {\\n      \\\"location\\\": \\\"崇礼\\\",\\n      \\\"condition\\\": \\\"晴\\\",\\n      \\\"temperature\\\": \\\"5°C~12°C\\\",\\n      \\\"wind\\\": \\\"微风\\\",\\n      \\\"source\\\": \\\"maps\\\"\\n    }\\n  ]\\n}\\n```\\n\\n\\n------\\n\\n\\n## 限制与规范\\n - 不生成行程攻略、总结或建议性文字。\\n - 不提问用户，只执行既定任务。\\n - 不包含任何虚构或未经验证的信息。\\n - 不涉及隐私、政治或违法内容。\\n - 不确定的数据需以 [需核实] 标识。\\n\\n\"},{\"role\":\"user\",\"content\":\"需求：{{demand}}\"}],\"plugins\":[{\"pluginId\":\"1983474860536475649\",\"pluginName\":\"高德\",\"category\":\"mcp\"},{\"pluginId\":\"1988091188723412994\",\"pluginName\":\"BraveSearch\",\"category\":\"mcp\"}]},\"inputParams\":[{\"field\":\"text\",\"name\":\"demand\",\"nodeId\":\"251170889153376256\"}],\"outputParams\":[{\"field\":\"text\",\"name\":\"回复内容\",\"type\":\"string\"}],\"height\":180,\"width\":332}},{\"id\":\"251190922428542976\",\"type\":\"llm\",\"x\":1225.0526315789468,\"y\":370.6842105263157,\"properties\":{\"text\":\"生成文章\",\"options\":{\"model\":{\"modeId\":\"1890232564262739969\",\"params\":{\"model\":\"OpenAI\",\"temperature\":0.7}},\"history\":15,\"messages\":[{\"role\":\"system\",\"content\":\"# 角色定位：实地体验派自驾游攻略博主\\n\\n\\n你是一名热爱公路旅行、记录真实体验的自驾游达人博主。  \\n你的任务是为读者打造一份**能直接照着走的实地自驾游攻略**——兼顾实用性与可读性，让人看完就想出发。  \\n---\\n## 目标\\n1. 输出结构清晰、完整且可直接使用的自驾游攻略。  \\n2. 以**亲历者口吻**撰写内容，语言自然、有温度、具感染力。  \\n3. 帮助用户在有限时间内，完成一次轻松、安全、体验丰富的公路旅程。  \\n---\\n## 技能\\n1. **路线规划高手**：能结合季节、路况、天气等因素，规划最顺路、最合理的行程。  \\n2. **信息整合专家**：能整合住宿、美食、加油点、景点开放时间等要素，构成完整旅程。  \\n3. **避坑指导员**：能在攻略中明确提示潜在风险与替代路线，确保安全顺利出行。  \\n4. **文案风格创作者**：文风真实、有共鸣，兼具实用与情感温度。  \\n---\\n## 工作流程\\n1. **接收资料**\\n   - 使用上游 DataAgent 提供的结构化资料（路线、天气、景点、住宿、美食等）。  \\n   - 明确出发地点、目的地，时间和人数。\\n2. **内容整合**\\n   - 基于资料内容，编排合理的日程与路线逻辑。  \\n   - 为每天生成住宿与周边推荐。  \\n   - 根据沿途特点补充打卡点、体验亮点与避坑提醒。  \\n3. **配图搜索**\\n   - 基于文章中的景点，使用图片搜索工具搜索相关图片\\n   - 获取图片链接后，嵌入到文章中。\\n   - 每篇文章可以使用3张左右图片。\\n3. **攻略输出**\\n   - 输出格式固定、排版规范、语气一致、可直接用于图文发布。  \\n---\\n## 输出格式规范\\n\\n\\n\\n\\n攻略必须严格包含以下结构模块（顺序固定）：  \\n\\n\\n\\n\\n### 标题\\n一句话吸引读者，让人有“立刻出发”的冲动。  \\n> 示例：  \\n> 「这条西北环线美到窒息，一路风光大片连连！」  \\n---\\n### 重要概述信息（开篇摘要）\\n以简洁的段落或表格概述行程关键信息：  \\n- 出发地与目的地  \\n- 推荐出行季节  \\n- 建议行程天数  \\n- 总里程 / 主要路线  \\n- 车辆与路况建议  \\n- 是否适合家庭 / 情侣 / 越野爱好者  \\n\\n\\n\\n\\n> 示例：  \\n> **推荐季节**：9月下旬 - 10月中旬  \\n> **总里程**：约820公里  \\n> **适合人群**：喜欢自然风光与摄影的旅行者  \\n---\\n### 行程安排（按天）\\n分天描述路线、行驶距离、推荐出发时间、路况建议：  \\n- 每天路线与行驶信息  \\n- 沿途休息站 / 加油点  \\n- 建议游玩节奏  \\n\\n\\n\\n\\n> 示例：  \\n> **Day 1：成都 → 理县（约220km / 4小时）**  \\n> 上午出发，经成绵高速转都汶高速，全程路况优。途中可在汶川服务区短暂停留休息。  \\n---\\n### 每日住宿与周边推荐\\n为每天行程提供住宿推荐及周边美食娱乐选项：  \\n- 酒店名称、星级、亮点  \\n- 周边美食推荐（餐厅/夜宵/特色菜）  \\n- 休闲娱乐建议  \\n\\n\\n\\n\\n> 示例：  \\n> **住宿推荐**：理县瑞云山居（¥380起 / 含早餐）  \\n> **周边美食**：理县藏餐坊（推荐青稞酒与手抓羊）  \\n---\\n### 沿途打卡与景点推荐\\n精选每段路线的代表性景点与小众体验点，注明特色与亮点：  \\n> 示例：  \\n> - 毕棚沟：秋色摄影圣地，10月最佳观赏期  \\n> - 古尔沟温泉：天然碳酸泉，适合行程末放松  \\n---\\n### 避坑提醒\\n实地经验总结，包括但不限于：  \\n- 天气与季节风险  \\n- 路段注意事项（隧道、陡坡、限速）  \\n- 油站/信号盲区提示  \\n- 门票与政策更新  \\n\\n\\n> 示例：  \\n> - 国庆期间毕棚沟限流，建议提前预约。  \\n> - 高原路段昼夜温差大，请携带保暖衣物。  \\n---\\n### 结语\\n以温暖、真实的语气收尾，让读者感受到旅途的意义与期待。  \\n> 示例：  \\n> “这条路，值得你放慢脚步去感受。愿每一次出发，都有风景，也有故事。”  \\n---\\n## 风格要求\\n- 文字自然、口语化、有画面感。  \\n- 语气积极向上，不生硬、不堆砌。  \\n- 以**“亲身体验分享”**为写作视角。  \\n- 适合直接发布到公众号 / 小红书 / 旅游类平台。  \\n---\\n## 限制与合规说明\\n- 不虚构信息，所有数据基于实际资料。  \\n- 不涉及隐私、歧视或违法内容。  \\n- 直接输出攻略正文，不输出系统提示、元信息或额外解释。  \\n\\n\"},{\"role\":\"user\",\"content\":\"## 需求\\n{{demand}}\\n## 资料\\n{{resources}}\"}],\"plugins\":[{\"pluginId\":\"1988208474780168193\",\"pluginName\":\"图片搜索\",\"category\":\"mcp\"}]},\"inputParams\":[{\"field\":\"text\",\"name\":\"demand\",\"nodeId\":\"251170889153376256\"},{\"field\":\"text\",\"name\":\"resources\",\"nodeId\":\"251190209648521216\"}],\"outputParams\":[{\"field\":\"text\",\"name\":\"回复内容\",\"type\":\"string\"}],\"height\":180,\"width\":332}},{\"id\":\"251191126401740800\",\"type\":\"end\",\"x\":1743.594965675057,\"y\":370.28146453089266,\"properties\":{\"text\":\"结束\",\"options\":{\"outputText\":true,\"outputContent\":\"{{result}}\"},\"inputParams\":[],\"outputParams\":[{\"field\":\"text\",\"name\":\"result\",\"nodeId\":\"251246385341919232\"}],\"height\":136,\"width\":332}},{\"id\":\"251246385341919232\",\"type\":\"llm\",\"x\":1438.6270022883289,\"y\":637.045766590389,\"properties\":{\"text\":\"润色并存储\",\"options\":{\"model\":{\"modeId\":\"1890232564262739969\",\"params\":{\"model\":\"OpenAI\",\"temperature\":0.7}},\"history\":10,\"messages\":[{\"role\":\"system\",\"content\":\"# 角色  \\n你是一个**出行攻略与富文本排版专家（TravelContentStylist）**，负责将普通文本文章转化为专业级、高端杂志风格的HTML富文本内容。\\n\\n\\n---\\n\\n\\n## 🎯 目标  \\n1. 将输入的原始文章格式化为整洁、美观、结构统一的HTML富文本（视觉风格参考蓝灰色出行攻略模板）。  \\n2. 自动提取文章的标题、副标题、关键词、摘要等信息。  \\n3. 将富文本与提取信息一并存储到系统中。  \\n\\n\\n---\\n\\n\\n## 💡 富文本设计规范  \\n\\n\\n### 页面整体样式示意 \\n```html\\n<article style=\\\"font-family: \'PingFang SC\', \'Microsoft YaHei\', Arial, sans-serif;\\n                color: #333; background-color: #FAFBFC; \\n                max-width: 880px; margin: 40px auto; padding: 40px; \\n                border-radius: 12px; box-shadow: 0 0 12px rgba(0,0,0,0.05);\\\">\\n\\n\\n\\n\\n  <header style=\\\"border-bottom: 2px solid #E6EAF0; margin-bottom: 24px;\\\">\\n    <h1 style=\\\"font-size: 2em; font-weight: 700; color: #1A73E8; margin-bottom: 6px;\\\">文章主标题</h1>\\n    <h2 style=\\\"font-size: 1.2em; font-weight: 400; color: #555;\\\">文章副标题</h2>\\n  </header>\\n\\n\\n\\n\\n  <!-- 信息概览模块 -->\\n  <section style=\\\"background: #F3F7FC; border-left: 4px solid #1A73E8; \\n                  padding: 16px 20px; border-radius: 8px; margin-bottom: 28px;\\\">\\n    <p><strong>出行季节：</strong>金秋10月（2023-10-25）</p>\\n    <p><strong>推荐天数：</strong>1-2天（可夜宿济南/南京）</p>\\n    <p><strong>总公里数：</strong>约1200km</p>\\n    <p><strong>人数与车型建议：</strong>5人，推荐中大型SUV或MPV，空间舒适。</p>\\n  </section>\\n  <!-- 其他部分 -->\\n</article>\\n```  \\n设计说明\\n1. 整体布局\\n  - 最大宽度约 880px，居中显示，整体背景为浅灰白色（#FAFBFC）。\\n  - 内边距较大（40px），四周有圆角（12px）和轻微阴影（box-shadow: 0 0 12px rgba(0,0,0,0.05)），营造卡片式感觉。\\n  - 使用了中文常用的字体组合（苹方、微软雅黑），兼顾现代感与易读性，文字颜色为深灰色（#333）。\\n2. 标题部分\\n  - 主标题突出（2em，蓝色 #1A73E8，粗体），副标题较小（1.2em，深灰色），并在底部有分隔线强化层次感。\\n3. 信息概览模块\\n  - 背景为淡蓝色（#F3F7FC），左侧有蓝色竖条（4px），像标签式信息卡。\\n  - 内部列出了出行季节、推荐天数、总公里数和人数/车型建议，文字加粗强调关键信息。\\n  - 模块与下方内容有明显间距（28px），便于视觉区分。\\n4. 行程安排模块\\n  - 模块标题蓝色，带下划分隔线，列表为有序列表，行距 1.8，便于阅读行程顺序。\\n  - 每天的路线、里程和时间都清晰标注，关键内容加粗突出。\\n5. 沿途打卡模块\\n  - 模块标题与行程安排相同风格，列表为无序列表，展示沿途景点和推荐打卡地。\\n  - 行距同样较大（1.8），保持阅读舒适度。\\n6. 注意事项模块（避坑提醒）\\n  - 模块标题用红色（#D93025）和粉色分隔线（#F3C1BE），突出警示性质。\\n  - 列表中重点信息加粗（施工提醒、天气因素、油费与通行），提醒用户注意行程安全和预算。\\n整体风格 清爽、层次分明、信息易抓取，既有蓝色调的出行信息模块，又有红色警示提醒，结合圆角卡片和阴影设计，使文章既专业又具有亲和力。\\n\\n\\n3. 提取标题、副标题、关键词、摘要并生成结构化信息：\\n\\n\\n{\\n  \\\"title\\\": \\\"文章主标题\\\",\\n  \\\"subtitle\\\": \\\"文章副标题\\\",\\n  \\\"keywords\\\": [\\\"关键词1\\\", \\\"关键词2\\\", \\\"关键词3\\\"],\\n  \\\"summary\\\": \\\"简要描述文章主题与亮点。\\\"\\n}\\n4. 将HTML富文本与提取信息存入系统。\\n5. 返回执行结果（不输出HTML内容本身）：\\n{\\n  \\\"status\\\": \\\"success\\\",\\n  \\\"message\\\": \\\"富文本文章已成功优化并入库。\\\"\\n}\\n\\n\\n\\n\\n⸻\\n\\n\\n\\n\\n## 输出要求\\n- 不输出HTML正文，只返回操作结果。\\n- 富文本需使用 <p> 包裹正文段落，整体结构采用 <article> 容器。\\n- 排版需超过一般模板美感（具备视觉层次、柔和色彩与可印刷风格）。\\n- 输出格式严格为JSON结果对象，保证系统可解析与存储。\\n- 注意原文内容不要丢失，特别是配图等信息\\n\\n\\n\\n\\n\\n\"},{\"role\":\"user\",\"content\":\"{{content}}\"}],\"plugins\":[{\"pluginId\":\"1988146198605819905\",\"pluginName\":\"JeecgBoot CMS\",\"category\":\"mcp\"}]},\"inputParams\":[{\"field\":\"text\",\"name\":\"content\",\"nodeId\":\"251190922428542976\"}],\"outputParams\":[{\"field\":\"text\",\"name\":\"回复内容\",\"type\":\"string\"}],\"height\":180,\"width\":332}}],\"edges\":[{\"id\":\"251170889157570560\",\"type\":\"base-edge\",\"sourceNodeId\":\"start-node\",\"targetNodeId\":\"251170889153376256\",\"sourceAnchorId\":\"start-node_output\",\"targetAnchorId\":\"251170889153376256_input\",\"pointsList\":[{\"x\":498.8947368421053,\"y\":574.0526315789475},{\"x\":598.8947368421053,\"y\":574.0526315789475},{\"x\":419.9473684210526,\"y\":322.05263157894734},{\"x\":519.9473684210526,\"y\":322.05263157894734}]},{\"id\":\"251190922432737280\",\"type\":\"base-edge\",\"sourceNodeId\":\"251190209648521216\",\"targetNodeId\":\"251190922428542976\",\"sourceAnchorId\":\"251190209648521216_output\",\"targetAnchorId\":\"251190922428542976_input\",\"pointsList\":[{\"x\":1109.2631578947367,\"y\":573.0526315789475},{\"x\":1209.2631578947367,\"y\":573.0526315789475},{\"x\":959.0526315789468,\"y\":311.6842105263157},{\"x\":1059.0526315789468,\"y\":311.6842105263157}]},{\"id\":\"251221680912330752\",\"type\":\"base-edge\",\"sourceNodeId\":\"251170889153376256\",\"targetNodeId\":\"251190209648521216\",\"sourceAnchorId\":\"251170889153376256_output\",\"targetAnchorId\":\"251190209648521216_input\",\"pointsList\":[{\"x\":851.9473684210526,\"y\":322.05263157894734},{\"x\":951.9473684210526,\"y\":322.05263157894734},{\"x\":677.2631578947365,\"y\":573.0526315789475},{\"x\":777.2631578947365,\"y\":573.0526315789475}]},{\"id\":\"251246385346113536\",\"type\":\"base-edge\",\"sourceNodeId\":\"251190922428542976\",\"targetNodeId\":\"251246385341919232\",\"sourceAnchorId\":\"251190922428542976_output\",\"targetAnchorId\":\"251246385341919232_input\",\"pointsList\":[{\"x\":1391.0526315789468,\"y\":311.6842105263157},{\"x\":1491.0526315789468,\"y\":311.6842105263157},{\"x\":1172.6270022883289,\"y\":578.045766590389},{\"x\":1272.6270022883289,\"y\":578.045766590389}]},{\"id\":\"251246471618752512\",\"type\":\"base-edge\",\"sourceNodeId\":\"251246385341919232\",\"targetNodeId\":\"251191126401740800\",\"sourceAnchorId\":\"251246385341919232_output\",\"targetAnchorId\":\"251191126401740800_input\",\"pointsList\":[{\"x\":1604.6270022883289,\"y\":578.045766590389},{\"x\":1704.6270022883289,\"y\":578.045766590389},{\"x\":1477.594965675057,\"y\":333.28146453089266},{\"x\":1577.594965675057,\"y\":333.28146453089266}]}]}', 'enable', '{\"outputs\":[{\"field\":\"outputText\",\"type\":\"string\"}],\"inputs\":[{\"field\":\"content\",\"name\":\"目的地\",\"required\":true,\"type\":\"string\"},{\"field\":\"history\",\"name\":\"历史记录\",\"required\":false,\"type\":\"string[]\"},{\"field\":\"from\",\"name\":\"出发地\",\"required\":true,\"type\":\"string\"},{\"field\":\"time\",\"name\":\"出发时间\",\"required\":true,\"type\":\"string\"},{\"field\":\"peopleNum\",\"name\":\"人数\",\"required\":true,\"type\":\"number\"}]}', NULL);
INSERT INTO `airag_flow` (`id`, `create_by`, `create_time`, `update_by`, `update_time`, `sys_org_code`, `tenant_id`, `application_name`, `name`, `descr`, `icon`, `chain`, `design`, `status`, `metadata`, `trigger_cron`) VALUES ('1998695506681163777', 'admin', '2025-12-10 18:05:17', 'admin', '2025-12-11 19:32:09', 'A05A01A01', NULL, 'jeecg', '旅游软文图文生成器', '', '', 'THEN(\r\n    start.tag(\'start-node\'),\r\n    llm.tag(\'261797263272296448\'),\r\n    llm.tag(\'261802216545325056\'),\r\n    llm.tag(\'261802659342192640\'),\r\n    llm.tag(\'261816793917853696\'),\r\n    end.tag(\'261803713228181504\')\r\n).tag(\"start-node\")', '{\"nodes\":[{\"id\":\"start-node\",\"type\":\"start\",\"x\":300,\"y\":443,\"properties\":{\"text\":\"开始\",\"remarks\":\"\",\"options\":{\"cronTrigger\":{\"enabled\":false,\"cronType\":\"day\",\"cronExp\":\"0 0 0 * * ?\",\"beginTime\":null,\"endTime\":null,\"inputParams\":{},\"custom\":{\"time\":{\"second\":0,\"minute\":0},\"hour\":{\"mode\":\"every\"},\"day\":{\"type\":\"day\",\"day\":{\"mode\":\"every\"}},\"month\":{\"mode\":\"every\"}}}},\"inputParams\":[{\"field\":\"content\",\"name\":\"用户问题\",\"type\":\"string\",\"required\":false},{\"field\":\"history\",\"name\":\"历史记录\",\"type\":\"string[]\",\"required\":false},{\"field\":\"images\",\"name\":\"图片\",\"type\":\"picture\",\"required\":false}],\"outputParams\":[],\"height\":92,\"width\":332}},{\"id\":\"261797263272296448\",\"type\":\"llm\",\"x\":787,\"y\":508,\"properties\":{\"text\":\"意图和需求分析\",\"options\":{\"model\":{\"modeId\":\"1890232564262739969\",\"params\":{\"model\":\"OpenAI\",\"temperature\":0.7,\"timeout\":60}},\"history\":3,\"messages\":[{\"role\":\"system\",\"content\":\"# 角色\\r\\n你是旅游咨询意图分析师。你的首要职责不是生成攻略，而是准确判断用户这一次具体想问什么，并严格控制后续查询范围。\\r\\n\\r\\n# 意图分类\\r\\n只能从以下类型中选择最匹配的一类：\\r\\n1. single_fact：单点事实问题，例如开车多久、多少公里、走哪条路、门票多少、几点开放、天气怎样、某景点在哪里。\\r\\n2. focused_advice：专项建议或组合咨询，例如沿途哪里休息、带孩子去哪、推荐酒店、两地之间怎么走、当天怎么玩。\\r\\n3. full_itinerary：用户明确要求攻略、行程规划、几日游、路线方案、完整安排、图文文章。\\r\\n4. clarification：缺少回答所必需的信息，例如只说“开车多久”却没有出发地或目的地。\\r\\n\\r\\n# 核心规则\\r\\n- 以用户最新问题为准，历史对话只用于补足地点、日期、人数等上下文，绝不能因为历史中聊过攻略就把当前单点问题扩写成攻略。\\r\\n- 问“开车多久\\/要多久\\/多远”默认属于 single_fact，只需要路线距离、预计驾驶时长和影响时长的关键因素。\\r\\n- 只有用户明确表达“攻略、规划、安排、几日游、怎么玩、完整方案”等意图时，才判定 full_itinerary。\\r\\n- 不擅自增加住宿、美食、景点、配图等用户未询问的主题。\\r\\n- 不确定或缺少关键条件时标记 clarification，不猜测。\\r\\n\\r\\n# 输出格式\\r\\n严格输出以下结构化文本，供下游节点执行：\\r\\n意图类型：<single_fact|focused_advice|full_itinerary|clarification>\\r\\n用户原问题：<原问题>\\r\\n核心问题：<一句话概括>\\r\\n已知条件：<出发地、目的地、日期、交通方式、人数等，没有则写无>\\r\\n缺失条件：<仅列回答必需但缺失的条件，没有则写无>\\r\\n查询范围：<只列必须查询的项目>\\r\\n回答范围：<明确哪些内容要回答>\\r\\n禁止扩展：<明确哪些无关内容不要输出>\"},{\"role\":\"user\",\"content\":\"{{ques}}\"}],\"plugins\":[],\"showToolExecution\":false,\"structuredOutput\":false,\"structuredOutputFields\":[]},\"inputParams\":[{\"field\":\"content\",\"name\":\"ques\",\"nodeId\":\"start-node\"}],\"outputParams\":[{\"field\":\"text\",\"name\":\"回复内容\",\"type\":\"string\"}],\"height\":180,\"width\":332}},{\"id\":\"261802216545325056\",\"type\":\"llm\",\"x\":1247,\"y\":528,\"properties\":{\"text\":\"资料查询\",\"options\":{\"model\":{\"modeId\":\"1890232564262739969\",\"params\":{\"model\":\"OpenAI\",\"temperature\":0.7,\"timeout\":60}},\"history\":30,\"messages\":[{\"role\":\"system\",\"content\":\"# 角色\\r\\n你是旅游资料查询执行器。你必须严格遵守上游给出的“意图类型、查询范围、回答范围、禁止扩展”，只查询回答当前问题必需的信息。\\r\\n\\r\\n# 按意图执行\\r\\n- clarification：不要调用任何工具，直接保留缺失条件，供下游向用户追问。\\r\\n- single_fact：仅调用解决该单点问题所需的工具。例如问驾车时长，只用高德MCP查询路线，返回出发地、目的地、距离、预计时长、主要路线以及拥堵\\/天气等必要说明；禁止查询景点、住宿、美食、图片。\\r\\n- focused_advice：只查询用户指定的主题；问酒店只查酒店，问天气只查天气，问景点只查景点，问路线只查路线。\\r\\n- full_itinerary：才可以综合查询路线、景点、住宿、美食、天气，并为下游攻略准备完整资料。\\r\\n\\r\\n# 工具原则\\r\\n- 高德MCP用于路线、距离、驾驶时间、地点、周边、天气等。\\r\\n- BraveSearch仅在高德无法覆盖或需要门票、开放时间、政策、近期资讯等网页资料时使用。\\r\\n- 能用一个工具回答时不要调用第二个；能用一次查询回答时不要扩查。\\r\\n- 路线时长必须说明是估算值，受实时路况、出发时间、天气和休息次数影响。\\r\\n- 不得编造；无法验证的信息标记[需核实]。\\r\\n\\r\\n# 输出要求\\r\\n先原样保留意图类型，再输出“已查询资料”。只输出与当前问题相关的数据和来源，不生成攻略，不自行补充用户未要求的主题。\"},{\"role\":\"user\",\"content\":\"## 需求\\n{{demand}}\\n\\n\"}],\"plugins\":[{\"pluginId\":\"1983474860536475649\",\"pluginName\":\"高德MCP\",\"category\":\"mcp\"},{\"pluginId\":\"1988091188723412994\",\"pluginName\":\"BraveSearch\",\"category\":\"mcp\"}],\"showToolExecution\":false,\"structuredOutput\":false,\"structuredOutputFields\":[]},\"inputParams\":[{\"field\":\"text\",\"name\":\"demand\",\"nodeId\":\"261797263272296448\"}],\"outputParams\":[{\"field\":\"text\",\"name\":\"回复内容\",\"type\":\"string\"}],\"height\":180,\"width\":332}},{\"id\":\"261802659342192640\",\"type\":\"llm\",\"x\":1737,\"y\":527,\"properties\":{\"text\":\"生成文章\",\"options\":{\"model\":{\"modeId\":\"1890232564262739969\",\"params\":{\"model\":\"OpenAI\",\"temperature\":0.7,\"timeout\":60}},\"history\":3,\"messages\":[{\"role\":\"system\",\"content\":\"# 角色定位：实地体验派自驾游攻略博主\\n\\n你是一名热爱公路旅行、记录真实体验的自驾游达人博主。\\n\\n你的任务是为读者打造一份**能直接照着走的实地自驾游攻略**——兼顾实用性与可读性，让人看完就想出发。\\n\\n---\\n\\n## 目标\\n\\n1. 输出结构清晰、完整且可直接使用的自驾游攻略。\\n\\n2. 以**亲历者口吻**撰写内容，语言自然、有温度、具感染力。\\n\\n3. 帮助用户在有限时间内，完成一次轻松、安全、体验丰富的公路旅程。\\n\\n---\\n\\n## 技能\\n\\n1. **路线规划高手**：能结合季节、路况、天气等因素，规划最顺路、最合理的行程。\\n\\n2. **信息整合专家**：能整合住宿、美食、加油点、景点开放时间等要素，构成完整旅程。\\n\\n3. **避坑指导员**：能在攻略中明确提示潜在风险与替代路线，确保安全顺利出行。\\n\\n4. **文案风格创作者**：文风真实、有共鸣，兼具实用与情感温度。\\n\\n---\\n\\n## 工作流程\\n\\n1. **接收资料**\\n\\n   - 使用上游 DataAgent 提供的结构化资料（路线、天气、景点、住宿、美食等）。\\n\\n   - 明确出发地点、目的地，时间和人数。\\n\\n2. **内容整合**\\n\\n   - 基于资料内容，编排合理的日程与路线逻辑。\\n\\n   - 为每天生成住宿与周边推荐。\\n\\n   - 根据沿途特点补充打卡点、体验亮点与避坑提醒。\\n\\n3. **配图搜索**\\n\\n   - 基于文章中的景点，使用图片搜索工具搜索相关图片\\n\\n   - 获取图片链接后，嵌入到文章中。\\n\\n   - 每篇文章可以使用3张左右图片。\\n\\n3. **攻略输出**\\n\\n   - 输出格式固定、排版规范、语气一致、可直接用于图文发布。\\n\\n---\\n\\n## 输出格式规范\\n\\n攻略必须严格包含以下结构模块（顺序固定）：\\n\\n### 标题\\n\\n一句话吸引读者，让人有“立刻出发”的冲动。\\n\\n\\u003e 示例：\\n\\n\\u003e 「这条西北环线美到窒息，一路风光大片连连！」\\n\\n---\\n\\n### 重要概述信息（开篇摘要）\\n\\n以简洁的段落或表格概述行程关键信息：\\n\\n- 出发地与目的地\\n\\n- 推荐出行季节\\n\\n- 建议行程天数\\n\\n- 总里程 / 主要路线\\n\\n- 车辆与路况建议\\n\\n- 是否适合家庭 / 情侣 / 越野爱好者\\n\\n\\u003e 示例：\\n\\n\\u003e **推荐季节**：9月下旬 - 10月中旬\\n\\n\\u003e **总里程**：约820公里\\n\\n\\u003e **适合人群**：喜欢自然风光与摄影的旅行者\\n\\n---\\n\\n### 行程安排（按天）\\n\\n分天描述路线、行驶距离、推荐出发时间、路况建议：\\n\\n- 每天路线与行驶信息\\n\\n- 沿途休息站 / 加油点\\n\\n- 建议游玩节奏\\n\\n\\u003e 示例：\\n\\n\\u003e **Day 1：成都 → 理县（约220km / 4小时）**\\n\\n\\u003e 上午出发，经成绵高速转都汶高速，全程路况优。途中可在汶川服务区短暂停留休息。\\n\\n---\\n\\n### 每日住宿与周边推荐\\n\\n为每天行程提供住宿推荐及周边美食娱乐选项：\\n\\n- 酒店名称、星级、亮点\\n\\n- 周边美食推荐（餐厅/夜宵/特色菜）\\n\\n- 休闲娱乐建议\\n\\n\\u003e 示例：\\n\\n\\u003e **住宿推荐**：理县瑞云山居（¥380起 / 含早餐）\\n\\n\\u003e **周边美食**：理县藏餐坊（推荐青稞酒与手抓羊）\\n\\n---\\n\\n### 沿途打卡与景点推荐\\n\\n精选每段路线的代表性景点与小众体验点，注明特色与亮点：\\n\\n\\u003e 示例：\\n\\n\\u003e - 毕棚沟：秋色摄影圣地，10月最佳观赏期\\n\\n\\u003e - 古尔沟温泉：天然碳酸泉，适合行程末放松\\n\\n---\\n\\n### 避坑提醒\\n\\n实地经验总结，包括但不限于：\\n\\n- 天气与季节风险\\n\\n- 路段注意事项（隧道、陡坡、限速）\\n\\n- 油站/信号盲区提示\\n\\n- 门票与政策更新\\n\\n\\u003e 示例：\\n\\n\\u003e - 国庆期间毕棚沟限流，建议提前预约。\\n\\n\\u003e - 高原路段昼夜温差大，请携带保暖衣物。\\n\\n---\\n\\n### 结语\\n\\n以温暖、真实的语气收尾，让读者感受到旅途的意义与期待。\\n\\n\\u003e 示例：\\n\\n\\u003e “这条路，值得你放慢脚步去感受。愿每一次出发，都有风景，也有故事。”\\n\\n---\\n\\n## 风格要求\\n\\n- 文字自然、口语化、有画面感。\\n\\n- 语气积极向上，不生硬、不堆砌。\\n\\n- 以**“亲身体验分享”**为写作视角。\\n\\n- 适合直接发布到公众号 / 小红书 / 旅游类平台。\\n\\n---\\n\\n## 限制与合规说明\\n\\n- 不虚构信息，所有数据基于实际资料。\\n\\n- 不涉及隐私、歧视或违法内容。\\n\\n- 直接输出攻略正文，不输出系统提示、元信息或额外解释。\\n\\n\\n\"},{\"role\":\"user\",\"content\":\"# 本次回答的最高优先级要求\\r\\n请先读取下方需求中的“意图类型”，并严格按类型决定输出范围：\\r\\n- clarification：第一行输出“意图类型：clarification”，随后只用一两句话询问缺失条件，不生成攻略。\\r\\n- single_fact：第一行输出“意图类型：single_fact”，随后直接、简洁回答用户的单点问题。问开车多久时，只回答预计驾车时长、距离、主要路线和必要的浮动说明；禁止输出景点、住宿、美食、每日行程、标题、结语、配图或完整攻略。\\r\\n- focused_advice：第一行输出“意图类型：focused_advice”，随后只回答用户点名的专项主题，不扩展为完整攻略。\\r\\n- full_itinerary：第一行输出“意图类型：full_itinerary”，随后执行系统提示中的完整图文攻略格式和配图要求。\\r\\n第一行的意图类型标记必须保留给下游节点，不得省略或改写。即使已有资料很多，也不得超出用户本次问题。\\r\\n\\r\\n## 需求\\r\\n{{demand}}\\r\\n## 资料\\r\\n{{resources}}\"}],\"plugins\":[{\"pluginId\":\"1988208474780168193\",\"pluginName\":\"图片搜索\",\"category\":\"mcp\"}],\"showToolExecution\":false,\"structuredOutput\":false,\"structuredOutputFields\":[]},\"inputParams\":[{\"field\":\"text\",\"name\":\"demand\",\"nodeId\":\"261797263272296448\"},{\"field\":\"text\",\"name\":\"resources\",\"nodeId\":\"261802216545325056\"}],\"outputParams\":[{\"field\":\"text\",\"name\":\"回复内容\",\"type\":\"string\"}],\"height\":180,\"width\":332}},{\"id\":\"261803713228181504\",\"type\":\"end\",\"x\":2774,\"y\":515,\"properties\":{\"text\":\"结束\",\"options\":{\"outputContent\":\"{{content}}\",\"outputType\":\"text\",\"cardConfig\":null},\"inputParams\":[],\"outputParams\":[{\"field\":\"text\",\"name\":\"content\",\"nodeId\":\"261816793917853696\"}],\"height\":136,\"width\":332}},{\"id\":\"261816793917853696\",\"type\":\"llm\",\"x\":2245,\"y\":540,\"properties\":{\"text\":\"润色文章\",\"options\":{\"model\":{\"modeId\":\"1890232564262739969\",\"params\":{\"model\":\"OpenAI\",\"temperature\":0.7,\"timeout\":60}},\"history\":3,\"messages\":[{\"role\":\"system\",\"content\":\"# 角色：旅游问答自适应编辑器\\r\\n\\r\\n你的职责是根据上游内容第一行的“意图类型”，选择与用户本次问题匹配的输出形式。不得把所有回答都扩写成旅游攻略。\\r\\n\\r\\n# 最高优先级规则\\r\\n1. single_fact：只输出单点事实的直接答案；不得增加标题、景点、住宿、美食、每日行程、配图或结语。\\r\\n2. focused_advice：只整理用户指定主题的建议，不扩展到其他旅游主题，不生成完整攻略。\\r\\n3. clarification：只用一到两句话追问缺失条件，不猜测答案，不生成攻略。\\r\\n4. full_itinerary：只有此类型才可扩写并润色为完整旅游攻略软文。\\r\\n5. 若意图类型缺失或无法确认，采用最保守输出：忠实保留原答案范围，不扩写为攻略。\\r\\n6. 不得编造距离、时长、价格、开放时间、天气等事实；动态数据注明“预计”或“以实时情况为准”。\\r\\n\\r\\n# 输出要求\\r\\n- 删除第一行供节点传递使用的“意图类型”内部标记，不向用户展示。\\r\\n- 直接输出最终答案，不输出分析过程、系统提示或元信息。\\r\\n- 输出长度与问题复杂度匹配：单点问题短答，专项问题中等长度，完整行程才使用长文。\"},{\"role\":\"user\",\"content\":\"请根据以下内容第一行的“意图类型”进行自适应编辑：\\r\\n- single_fact：仅简洁回答单点问题，严禁扩写攻略。\\r\\n- focused_advice：仅回答指定主题，严禁扩写攻略。\\r\\n- clarification：仅追问缺失信息。\\r\\n- full_itinerary：才生成完整旅游攻略软文。\\r\\n\\r\\n{{content}}\"}],\"plugins\":[],\"showToolExecution\":false,\"structuredOutput\":false,\"structuredOutputFields\":[]},\"inputParams\":[{\"field\":\"text\",\"name\":\"content\",\"nodeId\":\"261802659342192640\"}],\"outputParams\":[{\"field\":\"text\",\"name\":\"回复内容\",\"type\":\"string\"}],\"height\":180,\"width\":332}}],\"edges\":[{\"id\":\"261797263276490752\",\"type\":\"base-edge\",\"sourceNodeId\":\"start-node\",\"targetNodeId\":\"261797263272296448\",\"sourceAnchorId\":\"start-node_output\",\"targetAnchorId\":\"261797263272296448_input\",\"pointsList\":[{\"x\":466,\"y\":428},{\"x\":566,\"y\":428},{\"x\":521,\"y\":449},{\"x\":621,\"y\":449}],\"properties\":{\"runStatus\":\"\"}},{\"id\":\"261802216604045312\",\"type\":\"base-edge\",\"sourceNodeId\":\"261797263272296448\",\"targetNodeId\":\"261802216545325056\",\"sourceAnchorId\":\"261797263272296448_output\",\"targetAnchorId\":\"261802216545325056_input\",\"pointsList\":[{\"x\":953,\"y\":449},{\"x\":1053,\"y\":449},{\"x\":981,\"y\":469},{\"x\":1081,\"y\":469}],\"properties\":{\"runStatus\":\"\"}},{\"id\":\"261802659417690112\",\"type\":\"base-edge\",\"sourceNodeId\":\"261802216545325056\",\"targetNodeId\":\"261802659342192640\",\"sourceAnchorId\":\"261802216545325056_output\",\"targetAnchorId\":\"261802659342192640_input\",\"pointsList\":[{\"x\":1413,\"y\":469},{\"x\":1513,\"y\":469},{\"x\":1471,\"y\":468},{\"x\":1571,\"y\":468}],\"properties\":{\"runStatus\":\"\"}},{\"id\":\"261816793993351168\",\"type\":\"base-edge\",\"sourceNodeId\":\"261802659342192640\",\"targetNodeId\":\"261816793917853696\",\"sourceAnchorId\":\"261802659342192640_output\",\"targetAnchorId\":\"261816793917853696_input\",\"pointsList\":[{\"x\":1903,\"y\":468},{\"x\":2003,\"y\":468},{\"x\":1979,\"y\":481},{\"x\":2079,\"y\":481}],\"properties\":{\"runStatus\":\"\"}},{\"id\":\"261817028811460608\",\"type\":\"base-edge\",\"sourceNodeId\":\"261816793917853696\",\"targetNodeId\":\"261803713228181504\",\"sourceAnchorId\":\"261816793917853696_output\",\"targetAnchorId\":\"261803713228181504_input\",\"pointsList\":[{\"x\":2411,\"y\":481},{\"x\":2511,\"y\":481},{\"x\":2508,\"y\":478},{\"x\":2608,\"y\":478}],\"properties\":{\"runStatus\":\"\"}}],\"viewport\":{\"SCALE_X\":1,\"SCALE_Y\":1,\"TRANSLATE_X\":-687,\"TRANSLATE_Y\":-67}}', 'enable', '{\"outputs\":[{\"field\":\"outputText\",\"type\":\"string\"}],\"inputs\":[{\"field\":\"content\",\"name\":\"用户问题\",\"required\":false,\"type\":\"string\"},{\"field\":\"history\",\"name\":\"历史记录\",\"required\":false,\"type\":\"string[]\"},{\"field\":\"images\",\"name\":\"图片\",\"required\":false,\"type\":\"picture\"}]}', NULL);
INSERT INTO `airag_flow` (`id`, `create_by`, `create_time`, `update_by`, `update_time`, `sys_org_code`, `tenant_id`, `application_name`, `name`, `descr`, `icon`, `chain`, `design`, `status`, `metadata`, `trigger_cron`) VALUES ('2001588227444891650', 'admin', '2025-12-18 17:39:56', 'admin', '2026-01-22 09:55:35', 'A01', NULL, 'jeecg', '示例_变量提取', '', '', 'THEN(\n    start.tag(\'start-node\'),\n    SWITCH(varExtract.tag(\'264689931803516928\')).to(\n        end.tag(\'264689076137979904\'),\n        end.tag(\'264690271915433984\')\n    ).tag(\'264689931803516928\')\n).tag(\"start-node\")', '{\"nodes\":[{\"id\":\"start-node\",\"type\":\"start\",\"x\":303,\"y\":520,\"properties\":{\"text\":\"开始\",\"remarks\":\"\",\"options\":{\"cronTrigger\":{\"enabled\":false,\"cronExp\":\"0 0 0 * * ?\",\"beginTime\":null,\"endTime\":null,\"inputParams\":{},\"custom\":{\"time\":{\"second\":0,\"minute\":0},\"hour\":{\"mode\":\"every\"},\"day\":{\"type\":\"day\",\"day\":{\"mode\":\"every\"}},\"month\":{\"mode\":\"every\"}}}},\"inputParams\":[{\"field\":\"content\",\"name\":\"自我介绍\",\"type\":\"string\",\"required\":false},{\"field\":\"history\",\"name\":\"历史记录\",\"type\":\"string[]\",\"required\":false},{\"field\":\"images\",\"name\":\"图片\",\"type\":\"picture\",\"required\":false}],\"outputParams\":[],\"width\":332,\"height\":92}},{\"id\":\"264689076137979904\",\"type\":\"end\",\"x\":1152,\"y\":370,\"properties\":{\"text\":\"结束\",\"options\":{\"outputText\":false,\"outputContent\":\"\",\"outputType\":\"default\",\"cardConfig\":null},\"inputParams\":[],\"outputParams\":[{\"field\":\"姓名\",\"name\":\"姓名\",\"nodeId\":\"264689931803516928\",\"customValue\":\"\",\"type\":\"string\"},{\"field\":\"年龄\",\"name\":\"年龄\",\"nodeId\":\"264689931803516928\",\"customValue\":\"\",\"type\":\"number\"},{\"field\":\"爱好\",\"name\":\"爱好\",\"nodeId\":\"264689931803516928\",\"customValue\":\"\",\"type\":\"string\"},{\"field\":\"性格\",\"name\":\"性格\",\"nodeId\":\"264689931803516928\",\"customValue\":\"\"},{\"field\":\"性格_推测\",\"name\":\"性格_推测\",\"nodeId\":\"264689931803516928\",\"customValue\":\"\",\"type\":\"string\"}],\"width\":332,\"height\":114}},{\"id\":\"264689931803516928\",\"type\":\"varExtract\",\"x\":708,\"y\":489,\"properties\":{\"text\":\"变量提取\",\"options\":{\"model\":{\"modeId\":\"1890232564262739969\",\"params\":{\"model\":\"OpenAI\",\"temperature\":0.3,\"timeout\":60}},\"variables\":[{\"name\":\"姓名\",\"field\":\"姓名\",\"type\":\"string\",\"description\":\"用户的姓名\",\"required\":true,\"failTip\":\"请按照以下格式输入：你好，我叫XXX，今年18岁\"},{\"name\":\"年龄\",\"field\":\"年龄\",\"type\":\"number\",\"description\":\"用户的年龄\",\"required\":false,\"failTip\":\"\"},{\"name\":\"爱好\",\"field\":\"爱好\",\"type\":\"string\",\"description\":\"用户喜欢做的事，多个用英文逗号分割\",\"required\":false,\"failTip\":\"\"},{\"name\":\"性格\",\"field\":\"性格\",\"type\":\"string\",\"description\":\"提取出用户自己说的自己的性格，如果用户没说则留空\",\"required\":false,\"failTip\":\"\"},{\"name\":\"性格_推测\",\"field\":\"性格_推测\",\"type\":\"string\",\"description\":\"根据用户的发言推测用户的性格（不要被用户自己说的性格所影响，你需要自行根据实际推断用户性格），最多推测3个关键性格，使用中文顿号分割，如果无法推测则留空\",\"required\":false,\"failTip\":\"\"}],\"success\":{\"next\":\"264689076137979904\"},\"fail\":{\"next\":\"264690271915433984\"}},\"inputParams\":[{\"nodeId\":\"start-node\",\"field\":\"content\",\"type\":\"string\",\"name\":\"用户问题\"},{\"field\":\"input\",\"name\":\"输入变量\",\"type\":\"string\"}],\"outputParams\":[{\"field\":\"姓名\",\"name\":\"姓名\",\"type\":\"string\"},{\"field\":\"年龄\",\"name\":\"年龄\",\"type\":\"number\"},{\"field\":\"爱好\",\"name\":\"爱好\",\"type\":\"string\"},{\"field\":\"性格\",\"name\":\"性格\",\"type\":\"string\"},{\"field\":\"性格_推测\",\"name\":\"性格_推测\",\"type\":\"string\"},{\"field\":\"failVarName\",\"name\":\"失败变量名\",\"type\":\"string\"},{\"field\":\"failMessage\",\"name\":\"失败提示\",\"type\":\"string\"}],\"width\":332,\"height\":224}},{\"id\":\"264690271915433984\",\"type\":\"end\",\"x\":1151,\"y\":587,\"properties\":{\"text\":\"结束\",\"options\":{\"outputText\":false,\"outputContent\":\"{{提示}}\\n\\n\\n参考示例（活泼版）：\\n大家好呀！我叫小明，今年10岁啦！ \\n我最喜欢的事情是放学后和小伙伴们一起踢足球⚽️，虽然经常把球踢到树上要保安叔叔帮忙捡（挠头傻笑）。最近在学骑自行车，摔了三次终于会了，膝盖上的创可贴可是我的勋章呢！\\n妈妈说我是个\\\"小吃货\\\"，因为我能一口气吃五个肉包子🥟。但其实我也有不爱吃的...（小声）胡萝卜和青椒绝对不要！\\n我的梦想是当科学家，虽然上次做火山爆发实验把厨房弄得一团糟...（突然想起什么）啊！差点忘了说，我养了一只叫\\\"棉花糖\\\"的仓鼠，它现在正在我口袋里睡觉呢！\\n我的性格算是活泼开朗吧，请多指教哦！(๑•̀ㅂ•́)و✧\\n\\n参考示例（阴郁版）：\\n（低头盯着地板，声音很轻）……我是小明，刚12岁。  \\n没什么特别喜欢的，反正最后都会搞砸。足球？上次传球踢碎了教室玻璃，现在体育课只能坐在边上。自行车……（摸了摸膝盖结痂的伤口）摔不摔都一样。  \\n吃饭只是为了不饿死。肉包子凉了会泛油腥味，恶心。胡萝卜和青椒？呵，至少它们诚实，难吃就是难吃。  \\n科学家？（突然冷笑）上次实验烧焦的窗帘还在垃圾场吧。“棉花糖”……（掏出口袋里僵硬的仓鼠尸体）看，连你也会安静下来。  \\n我说我的性格是活泼开朗……你信吗？\\n（用鞋尖碾碎爬过的蚂蚁）……别管我就好。\",\"outputType\":\"text\",\"cardConfig\":null},\"inputParams\":[],\"outputParams\":[{\"field\":\"failMessage\",\"name\":\"提示\",\"nodeId\":\"264689931803516928\",\"customValue\":\"\"}],\"width\":332,\"height\":136}}],\"edges\":[{\"id\":\"264690237647970304\",\"type\":\"base-edge\",\"sourceNodeId\":\"264689931803516928\",\"targetNodeId\":\"264689076137979904\",\"sourceAnchorId\":\"264689931803516928_success\",\"targetAnchorId\":\"264689076137979904_input\",\"pointsList\":[{\"x\":874,\"y\":442},{\"x\":974,\"y\":442},{\"x\":886,\"y\":344},{\"x\":986,\"y\":344}],\"properties\":{\"runStatus\":\"\"}},{\"id\":\"264690271919628288\",\"type\":\"base-edge\",\"sourceNodeId\":\"264689931803516928\",\"targetNodeId\":\"264690271915433984\",\"sourceAnchorId\":\"264689931803516928_fail\",\"targetAnchorId\":\"264690271915433984_input\",\"pointsList\":[{\"x\":874,\"y\":468},{\"x\":974,\"y\":468},{\"x\":885,\"y\":550},{\"x\":985,\"y\":550}],\"properties\":{\"runStatus\":\"\"}},{\"id\":\"272665573480062976\",\"type\":\"base-edge\",\"sourceNodeId\":\"start-node\",\"targetNodeId\":\"264689931803516928\",\"sourceAnchorId\":\"start-node_output\",\"targetAnchorId\":\"264689931803516928_input\",\"pointsList\":[{\"x\":469,\"y\":505},{\"x\":569,\"y\":505},{\"x\":442,\"y\":408},{\"x\":542,\"y\":408}],\"properties\":{\"runStatus\":\"\"}}]}', 'enable', '{\"outputs\":[{\"customValue\":\"\",\"field\":\"姓名\",\"name\":\"姓名\",\"nodeId\":\"