INSERT INTO `airag_knowledge_doc` (`id`, `create_by`, `create_time`, `update_by`, `update_time`, `sys_org_code`, `tenant_id`, `knowledge_id`, `title`, `type`, `content`, `status`, `metadata`) VALUES ('1993974500714127363', 'admin', '2025-11-27 17:25:42', 'admin', '2025-11-27 17:25:46', NULL, NULL, '1993971013594931202', 'treeSelect', 'file', NULL, 'complete', '{\"sourcesPath\":\"D://opt//upFiles\\\\1993971013594931202\\\\402881829ac4a1fb019ac4a1fbc20000\\\\files\",\"filePath\":\"\\\\1993971013594931202\\\\402881829ac4a1fb019ac4a1fbc20000\\\\files\\\\docs\\\\uniapp3\\\\ui\\\\treeSelect.md\"}');
INSERT INTO `airag_mcp` (`id`, `icon`, `name`, `descr`, `category`, `type`, `endpoint`, `headers`, `tools`, `status`, `synced`, `metadata`, `create_by`, `create_time`, `update_by`, `update_time`, `sys_org_code`, `tenant_id`) VALUES ('1983474860536475649', NULL, '高德MCP', '高德MCP，包含查询路线、路况、天气等工具', 'mcp', 'sse', 'https://mcp.amap.com/sse?key=adaea6afab82893d0ccb4bd0239abcdd', '', '[{\"name\":\"maps_direction_bicycling\",\"description\":\"骑行路径规划用于规划骑行通勤方案，规划时会考虑天桥、单行线、封路等情况。最大支持 500km 的骑行路线规划\",\"parameters\":[{\"name\":\"origin\",\"description\":\"出发点经纬度，坐标格式为：经度，纬度\",\"required\":true},{\"name\":\"destination\",\"description\":\"目的地经纬度，坐标格式为：经度，纬度\",\"required\":true}]},{\"name\":\"maps_direction_driving\",\"description\":\"驾车路径规划 API 可以根据用户起终点经纬度坐标规划以小客车、轿车通勤出行的方案，并且返回通勤方案的数据。\",\"parameters\":[{\"name\":\"origin\",\"description\":\"出发点经纬度，坐标格式为：经度，纬度\",\"required\":true},{\"name\":\"destination\",\"description\":\"目的地经纬度，坐标格式为：经度，纬度\",\"required\":true}]},{\"name\":\"maps_direction_transit_integrated\",\"description\":\"根据用户起终点经纬度坐标规划综合各类公共（火车、公交、地铁）交通方式的通勤方案，并且返回通勤方案的数据，跨城场景下必须传起点城市与终点城市\",\"parameters\":[{\"name\":\"origin\",\"description\":\"出发点经纬度，坐标格式为：经度，纬度\",\"required\":true},{\"name\":\"destination\",\"description\":\"目的地经纬度，坐标格式为：经度，纬度\",\"required\":true},{\"name\":\"city\",\"description\":\"公共交通规划起点城市\",\"required\":true},{\"name\":\"cityd\",\"description\":\"公共交通规划终点城市\",\"required\":true}]},{\"name\":\"maps_direction_walking\",\"description\":\"根据输入起点终点经纬度坐标规划100km 以内的步行通勤方案，并且返回通勤方案的数据\",\"parameters\":[{\"name\":\"origin\",\"description\":\"出发点经度，纬度，坐标格式为：经度，纬度\",\"required\":true},{\"name\":\"destination\",\"description\":\"目的地经度，纬度，坐标格式为：经度，纬度\",\"required\":true}]},{\"name\":\"maps_distance\",\"description\":\"测量两个经纬度坐标之间的距离,支持驾车、步行以及球面距离测量\",\"parameters\":[{\"name\":\"origins\",\"description\":\"起点经度，纬度，可以传多个坐标，使用竖线隔离，比如120,30|120,31，坐标格式为：经度，纬度\",\"required\":true},{\"name\":\"destination\",\"description\":\"终点经度，纬度，坐标格式为：经度，纬度\",\"required\":true},{\"name\":\"type\",\"description\":\"距离测量类型,1代表驾车距离测量，0代表直线距离测量，3步行距离测量\"}]},{\"name\":\"maps_geo\",\"description\":\"将详细的结构化地址转换为经纬度坐标。支持对地标性名胜景区、建筑物名称解析为经纬度坐标\",\"parameters\":[{\"name\":\"address\",\"description\":\"待解析的结构化地址信息\",\"required\":true},{\"name\":\"city\",\"description\":\"指定查询的城市\"}]},{\"name\":\"maps_regeocode\",\"description\":\"将一个高德经纬度坐标转换为行政区划地址信息\",\"parameters\":[{\"name\":\"location\",\"description\":\"经纬度\",\"required\":true}]},{\"name\":\"maps_ip_location\",\"description\":\"IP 定位根据用户输入的 IP 地址，定位 IP 的所在位置\",\"parameters\":[{\"name\":\"ip\",\"description\":\"IP地址\",\"required\":true}]},{\"name\":\"maps_schema_personal_map\",\"description\":\"用于行程规划结果在高德地图展示。将行程规划位置点按照行程顺序填入lineList，返回结果为高德地图打开的URI链接，该结果不需总结，直接返回！\",\"parameters\":[{\"name\":\"orgName\",\"description\":\"行程规划地图小程序名称\",\"required\":true},{\"name\":\"lineList\",\"description\":\"行程列表\",\"required\":true}]},{\"name\":\"maps_around_search\",\"description\":\"周边搜，根据用户传入关键词以及坐标location，搜索出radius半径范围的POI\",\"parameters\":[{\"name\":\"keywords\",\"description\":\"搜索关键词\",\"required\":true},{\"name\":\"location\",\"description\":\"中心点经度纬度\",\"required\":true},{\"name\":\"radius\",\"description\":\"搜索半径\"}]},{\"name\":\"maps_search_detail\",\"description\":\"查询关键词搜或者周边搜获取到的POI ID的详细信息\",\"parameters\":[{\"name\":\"id\",\"description\":\"关键词搜或者周边搜获取到的POI ID\",\"required\":true}]},{\"name\":\"maps_text_search\",\"description\":\"关键字搜索 API 根据用户输入的关键字进行 POI 搜索，并返回相关的信息\",\"parameters\":[{\"name\":\"keywords\",\"description\":\"查询关键字\",\"required\":true},{\"name\":\"city\",\"description\":\"查询城市\"},{\"name\":\"citylimit\",\"description\":\"是否限制城市范围内搜索，默认不限制\"}]},{\"name\":\"maps_schema_navi\",\"description\":\" Schema唤醒客户端-导航页面，用于根据用户输入终点信息，返回一个拼装好的客户端唤醒URI，用户点击该URI即可唤起对应的客户端APP。唤起客户端后，会自动跳转到导航页面。\",\"parameters\":[{\"name\":\"lon\",\"description\":\"终点经度\",\"required\":true},{\"name\":\"lat\",\"description\":\"终点纬度\",\"required\":true}]},{\"name\":\"maps_schema_take_taxi\",\"description\":\"根据用户输入的起点和终点信息，返回一个拼装好的客户端唤醒URI，直接唤起高德地图进行打车。直接展示生成的链接，不需要总结\",\"parameters\":[{\"name\":\"slon\",\"description\":\"起点经度\"},{\"name\":\"slat\",\"description\":\"起点纬度\"},{\"name\":\"sname\",\"description\":\"起点名称\"},{\"name\":\"dlon\",\"description\":\"终点经度\",\"required\":true},{\"name\":\"dlat\",\"description\":\"终点纬度\",\"required\":true},{\"name\":\"dname\",\"description\":\"终点名称\",\"required\":true}]},{\"name\":\"maps_weather\",\"description\":\"根据城市名称或者标准adcode查询指定城市的天气\",\"parameters\":[{\"name\":\"city\",\"description\":\"城市名称或者adcode\",\"required\":true}]}]', 'enable', 1, '{\"tool_count\":15}', 'admin', '2025-10-29 18:03:53', 'admin', '2026-01-23 17:58:21', 'A04', NULL);
INSERT INTO `airag_mcp` (`id`, `icon`, `name`, `descr`, `category`, `type`, `endpoint`, `headers`, `tools`, `status`, `synced`, `metadata`, `create_by`, `create_time`, `update_by`, `update_time`, `sys_org_code`, `tenant_id`) VALUES ('1986312214909321217', NULL, '商品采购助手', '为AI Agent提供商品管理API（DEMO)', 'plugin', 'api', NULL, '', '[{\"name\":\"list_products\",\"description\":\"查询可购买的商品列表,支持按分类和关键词筛选；商品的id只能通过这个接口查询。\",\"path\":\"/demo/shop/products\",\"method\":\"GET\",\"enabled\":true,\"parameters\":[{\"name\":\"category\",\"description\":\"商品分类,可选值: \\\"电子产品\\\", \\\"图书\\\", \\\"生活用品\\\", \\\"食品\\\"\",\"type\":\"String\",\"location\":\"Query\",\"required\":false,\"defaultValue\":\"\"},{\"name\":\"keyword\",\"description\":\"搜索关键词,用于在商品名称和描述中搜索\",\"type\":\"String\",\"location\":\"Query\",\"required\":false,\"defaultValue\":\"\"}],\"responses\":[{\"name\":\"id\",\"description\":\"商品ID，对应下单的ProductId\",\"type\":\"String\"},{\"name\":\"name\",\"description\":\"商品名称\",\"type\":\"String\"},{\"name\":\"price\",\"description\":\"价格(元)\",\"type\":\"String\"},{\"name\":\"category\",\"description\":\"分类\",\"type\":\"String\"},{\"name\":\"description\",\"description\":\"描述\",\"type\":\"String\"},{\"name\":\"stock\",\"description\":\"库存数量\",\"type\":\"String\"}]},{\"name\":\"check_stock\",\"description\":\"查询指定商品的当前库存情况\",\"path\":\"/demo/shop/stock\",\"method\":\"GET\",\"enabled\":true,\"parameters\":[{\"name\":\"productId\",\"description\":\"商品ID\",\"type\":\"String\",\"location\":\"Query\",\"required\":true,\"defaultValue\":\"\"}],\"responses\":[{\"name\":\"productId\",\"description\":\"商品ID\",\"type\":\"String\"},{\"name\":\"productName\",\"description\":\"商品名称\",\"type\":\"String\"},{\"name\":\"stock\",\"description\":\"当前库存数量\",\"type\":\"String\"},{\"name\":\"available\",\"description\":\"是否有货\",\"type\":\"Boolean\"}]},{\"name\":\"create_order\",\"description\":\"为用户创建购买订单\",\"path\":\"/demo/shop/purchase\",\"method\":\"POST\",\"enabled\":true,\"parameters\":[{\"name\":\"productId\",\"description\":\"要购买的商品的ID，对应商品的信息的id\",\"type\":\"String\",\"location\":\"Query\",\"required\":true,\"defaultValue\":\"\"},{\"name\":\"quantity\",\"description\":\" 购买数量,必须大于0\",\"type\":\"Integer\",\"location\":\"Query\",\"required\":true,\"defaultValue\":\"\"},{\"name\":\"userId\",\"description\":\"用户ID,用于关联订单\",\"type\":\"String\",\"location\":\"Query\",\"required\":false,\"defaultValue\":\"\"}],\"responses\":[{\"name\":\"id\",\"description\":\"订单ID\",\"type\":\"String\"},{\"name\":\"productId\",\"description\":\"商品ID\",\"type\":\"String\"},{\"name\":\"productName\",\"description\":\"商品名称\",\"type\":\"String\"},{\"name\":\"quantity\",\"description\":\"购买数量\",\"type\":\"String\"},{\"name\":\"unitPrice\",\"description\":\"单价\",\"type\":\"String\"},{\"name\":\"totalAmount\",\"description\":\"总金额\",\"type\":\"String\"},{\"name\":\"status\",\"description\":\"订单状态\",\"type\":\"String\"},{\"name\":\"createTime\",\"description\":\"创建时间\",\"type\":\"String\"}]},{\"name\":\"confirm_payment\",\"description\":\"确认订单支付,扣减商品库存\",\"path\":\"/demo/shop/stock/deduct\",\"method\":\"POST\",\"enabled\":true,\"parameters\":[{\"name\":\"orderId\",\"description\":\"订单ID\",\"type\":\"String\",\"location\":\"Query\",\"required\":true,\"defaultValue\":\"\"}],\"responses\":[{\"name\":\"orderId\",\"description\":\"订单ID\",\"type\":\"String\"},{\"name\":\"productId\",\"description\":\"商品ID\",\"type\":\"String\"},{\"name\":\"productName\",\"description\":\"商品名称\",\"type\":\"String\"},{\"name\":\"deductedQuantity\",\"description\":\"扣减的数量\",\"type\":\"String\"},{\"name\":\"remainingStock\",\"description\":\"剩余库存\",\"type\":\"String\"},{\"name\":\"orderStatus\",\"description\":\"订单状态\",\"type\":\"String\"}]},{\"name\":\"get_order_details\",\"description\":\"查询指定订单的详细信息\",\"path\":\"/demo/shop/order\",\"method\":\"GET\",\"enabled\":true,\"parameters\":[{\"name\":\"orderId\",\"description\":\"订单ID\",\"type\":\"String\",\"location\":\"Query\",\"required\":false,\"defaultValue\":\"\"}],\"responses\":[]},{\"name\":\"get_categories\",\"description\":\"获取所有可用的商品分类\",\"path\":\"/demo/shop/categories\",\"method\":\"GET\",\"enabled\":true,\"parameters\":[],\"responses\":[]}]', 'enable', 1, '{\"tokenParamName\":\"X-Access-Token\",\"tool_count\":6,\"authType\":\"token\",\"tokenParamValue\":\"\"}', 'admin', '2025-11-06 13:58:31', 'admin', '2025-11-13 17:16:57', 'A05A01A01', NULL);
INSERT INTO `airag_mcp` (`id`, `icon`, `name`, `descr`, `category`, `type`, `endpoint`, `headers`, `tools`, `status`, `synced`, `metadata`, `create_by`, `create_time`, `update_by`, `update_time`, `sys_org_code`, `tenant_id`) VALUES ('1988091188723412994', NULL, 'BraveSearch', '基于Brave的网络检索插件，支持使用Brave搜索资料', 'plugin', 'api', 'https://api.search.brave.com', '{\"Accept\":\"*/*\",\"X-Subscription-Token\":\"???\"}', '[{\"name\":\"search\",\"description\":\"从搜索引擎根据问题搜索结果\",\"path\":\"/res/v1/web/search\",\"method\":\"GET\",\"enabled\":true,\"parameters\":[{\"name\":\"count\",\"description\":\"查询数量\",\"type\":\"String\",\"location\":\"Query\",\"required\":false,\"defaultValue\":\"10\"},{\"name\":\"q\",\"description\":\"查询内容（问题）\",\"type\":\"String\",\"location\":\"Query\",\"required\":true,\"defaultValue\":\"\"}],\"responses\":[{\"name\":\"title\",\"description\":\"结果标题\",\"type\":\"String\"},{\"name\":\"description\",\"description\":\"结果描述\",\"type\":\"String\"},{\"name\":\"url\",\"description\":\"结果原文地址\",\"type\":\"String\"}]}]', 'enable', 1, '{\"tokenParamName\":\"X-Subscription-Token\",\"tool_count\":1,\"authType\":\"token\",\"tokenParamValue\":\"BSATNKM5e6Hm_2LewptVvLSn0eDzWf6\"}', 'admin', '2025-11-11 11:47:31', 'admin', '2025-11-13 17:16:52', 'A05A01A01', NULL);
INSERT INTO `airag_mcp` (`id`, `icon`, `name`, `descr`, `category`, `type`, `endpoint`, `headers`, `tools`, `status`, `synced`, `metadata`, `create_by`, `create_time`, `update_by`, `update_time`, `sys_org_code`, `tenant_id`) VALUES ('1988208474780168193', NULL, 'Unsplash', '图片搜索插件，支持用关键词搜索相关图片', 'plugin', 'api', 'https://api.unsplash.com', '{\"Accept-Version\":\"v1\",\"Authorization\":\"Client-ID ???\"}', '[{\"name\":\"search_photos\",\"description\":\"通过接口查询与关键词相关的图片列表。\",\"path\":\"/search/photos\",\"method\":\"GET\",\"enabled\":true,\"parameters\":[{\"name\":\"page\",\"description\":\"分页页码，数字类型\",\"type\":\"Number\",\"location\":\"Query\",\"required\":true,\"defaultValue\":\"1\"},{\"name\":\"per_page\",\"description\":\"每页数量\",\"type\":\"Number\",\"location\":\"Query\",\"required\":true,\"defaultValue\":\"1\"},{\"name\":\"query\",\"description\":\"关键词，对图片的描述（查询条件）\",\"type\":\"String\",\"location\":\"Query\",\"required\":true,\"defaultValue\":\"\"}],\"responses\":[{\"name\":\"results\",\"description\":\"查询到的结果集合\",\"type\":\"Array\"},{\"name\":\"urls\",\"description\":\"结果集合中的图片地址，根据清晰度有多个选项\",\"type\":\"Array\"}]}]', 'enable', 1, '{\"tokenParamName\":\"Authorization\",\"tool_count\":1,\"authType\":\"token\",\"tokenParamValue\":\"Client-ID Ixug6rX2j1PMb08A0HRpwny8dAWi1vBLN1gymow75LQ\"}', 'admin', '2025-11-11 19:33:34', 'admin', '2025-11-13 17:16:45', 'A05A01A01', NULL);
INSERT INTO `airag_mcp` (`id`, `icon`, `name`, `descr`, `category`, `type`, `endpoint`, `headers`, `tools`, `status`, `synced`, `metadata`, `create_by`, `create_time`, `update_by`, `update_time`, `sys_org_code`, `tenant_id`) VALUES ('1998661532445491201', NULL, 'stdio命令', NULL, 'mcp', 'stdio', 'python C:/Users/Administrator/Desktop/image/main.py', '', '[{\"name\":\"get_time\",\"description\":\"获取当前时间\",\"parameters\":[{\"name\":\"format\",\"description\":\"时间格式\"}]},{\"name\":\"text_process\",\"description\":\"文本处理工具\",\"parameters\":[{\"name\":\"text\",\"description\":\"输入文本\",\"required\":true},{\"name\":\"operation\",\"description\":\"操作类型\"}]},{\"name\":\"format_data\",\"description\":\"格式化数据\",\"parameters\":[{\"name\":\"data\",\"description\":\"原始数据\",\"required\":true},{\"name\":\"format\",\"description\":\"格式类型\"}]}]', 'enable', 1, '{\"tool_count\":3}', 'admin', '2025-12-10 15:50:17', 'admin', '2025-12-30 10:53:03', 'A05A01A01', NULL);
INSERT INTO `airag_mcp` (`id`, `icon`, `name`, `descr`, `category`, `type`, `endpoint`, `headers`, `tools`, `status`, `synced`, `metadata`, `create_by`, `create_time`, `update_by`, `update_time`, `sys_org_code`, `tenant_id`) VALUES ('2001570058113265665', NULL, '百度地图http', NULL, 'mcp', 'http', 'https://mcp.map.baidu.com/mcp?ak=', '{\"Accept-Version\":\"V2.6\"}', '[{\"name\":\"map_geocode\",\"description\":\"地理编码服务: 将地址解析为对应的位置坐标.地址结构越完整, 地址内容越准确, 解析的坐标精度越高.\",\"parameters\":[{\"name\":\"address\",\"description\":\"待解析的地址.最多支持84个字节.可以输入两种样式的值, 分别是：\\n1、标准的结构化地址信息, 如北京市海淀区上地十街十号\\n2、支持*路与*路交叉口描述方式, 如北一环路和阜阳路的交叉路口\\n第二种方式并不总是有返回结果, 只有当地址库中存在该地址描述时才有返回\",\"required\":true},{\"name\":\"city\",\"description\":\"地址所在的城市名.用于限制同名地址的检索范围, 如\'北京市\'\"},{\"name\":\"inarea\",\"description\":\"在哪个地区范围内进行搜索, 仅在is_china为false时有效, 需要使用对应区域的国家代码, 如\'USA\', 多个地区可用\',\'分割, 如\'USA,PHL,CAN,MEX\'\"},{\"name\":\"is_china\",\"description\":\"查询地是否在中国大陆以外地区, 可选值为`true`或`false`, 默认为`true`\"}]},{\"name\":\"map_reverse_geocode\",\"description\":\"逆地理编码服务: 根据纬经度坐标, 获取对应位置的地址描述, 所在行政区划, 道路以及相关POI等信息\",\"parameters\":[{\"name\":\"latitude\",\"description\":\"纬度 (bd09ll)\",\"required\":true},{\"name\":\"longitude\",\"description\":\"经度 (bd09ll)\",\"required\":true}]},{\"name\":\"map_search_places\",\"description\":\"地点检索服务: 支持检索城市内的地点信息(最小到city级别), 也可支持圆形区域内的周边地点信息检索.\\n城市内检索: 检索某一城市内（目前最细到城市级别）的地点信息.\\n周边检索: 设置圆心和半径, 检索圆形区域内的地点信息（常用于周边检索场景）.\",\"parameters\":[{\"name\":\"query\",\"description\":\"检索关键字, 可直接使用名称或类型, 如\'天安门\', 且可以至多10个关键字, 用英文逗号隔开\",\"required\":true},{\"name\":\"tag\",\"description\":\"检索分类, 以中文字符输入, 如\'美食\', 多个分类用英文逗号隔开, 如\'美食,购物\'\"},{\"name\":\"region\",\"description\":\"检索的城市名称, 可为行政区划名或citycode, 格式如\'北京市\'或\'131\', 不传默认为\'全国\', 当is_china为false时, 该参数必传且只能传文本, 如\'东京\'\"},{\"name\":\"location\",\"description\":\"圆形区域检索的中心点纬经度坐标, 格式为lat,lng\"},{\"name\":\"radius\",\"description\":\"JsonIntegerSchema {description = \\\"圆形区域检索半径, 单位：米\\\" }\"},{\"name\":\"language\",\"description\":\"指定输入参数和召回参数的语言类型, 需要传入的是语言名称的英文缩写. \\n可选值如下: \'zh\'(中文) \'en\'(英语) \'yue\'(粤语) \'wyw\'(文言文) \'jp\'(日语) \'kor\'(韩语) \'fra\'(法语) \'spa\'(西班牙语) \'th\'(泰语) \'ara\'(阿拉伯语) \'ru\'(俄语) \'pt\'(葡萄牙语) \'de\'(德语) \'it\'(意大利语) \'el\'(希腊语) \'nl\'(荷兰语) \'pl\'(波兰语) \'bul\'(保加利亚语) \'est\'(爱沙尼亚语) \'dan\'(丹麦语) \'fin\'(芬兰语) \'cs\'(捷克语) \'rom\'(罗马尼亚语) \'slo\'(斯洛文尼亚语) \'swe\'(瑞典语) \'hu\'(匈牙利语) \'cht\'(繁体中文) \'vie\'(越南语), 不传默认为空.\"},{\"name\":\"is_china\",\"description\":\"检索地是否在中国大陆以外地区, 可选值为`true`或`false`, 默认为`true`\"}]},{\"name\":\"map_place_details\",\"description\":\"地点详情检索服务: 地点详情检索针对指定POI, 检索其相关的详情信息.\\n通过地点检索服务获取POI uid.使用地点详情检索功能, 传入uid, 即可检索POI详情信息, 如评分、营业时间等(不同类型POI对应不同类别详情数据).\",\"parameters\":[{\"name\":\"uid\",\"description\":\"POI的唯一标识\",\"required\":true},{\"name\":\"is_china\",\"description\":\"查询地是否在中国大陆以外地区, 可选值为`true`或`false`, 默认为`true`\"}]},{\"name\":\"map_directions_matrix\",\"description\":\"批量算路服务: 根据起点和终点坐标计算路线规划距离和行驶时间.\\n批量算路目前支持驾车、骑行、步行.\\n步行时任意起终点之间的距离不得超过200KM, 超过此限制会返回参数错误.\\n驾车批量算路一次最多计算100条路线, 起终点个数之积不能超过100.\",\"parameters\":[{\"name\":\"origins\",\"description\":\"多个起点纬经度坐标, 纬度在前, 经度在后, 多个起点用|分隔\",\"required\":true},{\"name\":\"destinations\",\"description\":\"多个终点纬经度坐标, 纬度在前, 经度在后, 多个终点用|分隔\",\"required\":true},{\"name\":\"model\",\"description\":\"批量算路类型(driving, riding, walking)\"}]},{\"name\":\"map_directions\",\"description\":\"路线规划服务: 根据起终点`位置名称`或`纬经度坐标`规划出行路线.\\n驾车路线规划: 根据起终点`位置名称`或`纬经度坐标`规划驾车出行路线.\\n骑行路线规划: 根据起终点`位置名称`或`纬经度坐标`规划骑行出行路线.\\n步行路线规划: 根据起终点`位置名称`或`纬经度坐标`规划步行出行路线.\\n公交路线规划: 根据起终点`位置名称`或`纬经度坐标`规划公共交通出行路线.\",\"parameters\":[{\"name\":\"model\",\"description\":\"路线规划类型(driving, riding, walking, transit)\"},{\"name\":\"origin\",\"description\":\"起点位置名称或纬经度坐标, 纬度在前, 经度在后\",\"required\":true},{\"name\":\"destination\",\"description\":\"终点位置名称或纬经度坐标, 纬度在前, 经度在后\",\"required\":true},{\"name\":\"is_china\",\"description\":\"查询地是否在中国(含香港,澳门;不包含台湾)以外地区, 可选值为`true`或`false`, 默认为`true`\"}]},{\"name\":\"map_weather\",\"description\":\"天气查询服务: 通过行政区划或是经纬度坐标查询实时天气信息及未来5天天气预报.\",\"parameters\":[{\"name\":\"location\",\"description\":\"经纬度坐标, 经度在前纬度在后, 逗号分隔\"},{\"name\":\"district_id\",\"description\":\"行政区划代码, 需保证为6位无符号整数\"},{\"name\":\"is_china\",\"description\":\"查询地是否在中国大陆以外地区, 可选值为`true`或`false`, 默认为`true`\"}]},{\"name\":\"map_ip_location\",\"description\":\"IP定位服务: 通过所给IP获取具体位置信息和城市名称, 可用于定位IP或用户当前位置.\",\"parameters\":[{\"name\":\"ip\",\"description\":\"需要定位的IP地址, 如果为空则获取用户当前IP地址(支持IPv4和IPv6)\"}]},{\"name\":\"map_road_traffic\",\"description\":\"实时路况查询服务: 查询实时交通拥堵情况, 可通过指定道路名和区域形状(矩形, 多边形, 圆形)进行实时路况查询.\\n道路实时路况查询: 查询具体道路的实时拥堵评价和拥堵路段、拥堵距离、拥堵趋势等信息.\\n矩形区域实时路况查询: 查询指定矩形地理范围的实时拥堵情况和各拥堵路段信息.\\n多边形区域实时路况查询: 查询指定多边形地理范围的实时拥堵情况和各拥堵路段信息.\\n圆形区域(周边)实时路况查询: 查询某中心点周边半径范围内的实时拥堵情况和各拥堵路段信息.\",\"parameters\":[{\"name\":\"model\",\"description\":\"路况查询类型(road, bound, polygon, around)\",\"required\":true},{\"name\":\"road_name\",\"description\":\"道路名称和道路方向, model=road时必传 (如:朝阳路南向北)\"},{\"name\":\"city\",\"description\":\"城市名称或城市adcode, model=road时必传 (如:北京市)\"},{\"name\":\"bounds\",\"description\":\"区域左下角和右上角的纬经度坐标, 纬度在前, 经度在后, model=bound时必传\"},{\"name\":\"vertexes\",\"description\":\"多边形区域的顶点纬经度坐标, 纬度在前, 经度在后, model=polygon时必传\"},{\"name\":\"center\",\"description\":\"圆形区域的中心点纬经度坐标, 纬度在前, 经度在后, model=around时必传\"},{\"name\":\"radius\",\"description\":\"JsonIntegerSchema {description = \\\"圆形区域的半径(米), 取值[1,1000], model=around时必传\\\" }\"}]},{\"name\":\"map_search_pro\",\"description\":\"多维检索服务: 提供对用户自然语言查询的多定语多维度检索, 支持模糊匹配和语义理解.\\n仅在需求模糊的场景下再做优先使用, 可检索行政区划、道路、门址、POI、AOI等GIS信息. 参考示例: “可以带狗的餐厅”, “适合自驾的旅游景点”类的复杂泛搜.\",\"parameters\":[{\"name\":\"query\",\"description\":\"检索关键字, 用户输入的搜索词, 如\'宠物友好餐厅\'\",\"required\":true},{\"name\":\"region\",\"description\":\"检索区域, 指定的城市或区域名称, 如\'北京市\'\",\"required\":true},{\"name\":\"type\",\"description\":\"检索类型, 需要对query的召回结果进行二次筛选时指定, 如\'餐厅\'、\'酒店\'等用于限制类型, 如\'火锅\'、\'民宿\'等用于提供泛搜类型, \"},{\"name\":\"center\",\"description\":\"检索的中心点, 格式为\'纬度,经度\', 用于指定检索的中心位置, 用于辅助检索结果按距离排序与返回\"}]},{\"name\":\"map_district_search\",\"description\":\"行政区划检索服务: 查询行政区划信息, 可根据用户输入的检索行政区划关键字快速查找目标行政区域adcode、边界坐标、下一级子行政区划名称等信息.\",\"parameters\":[{\"name\":\"keyword\",\"description\":\"检索关键字, 用户输入的行政区划名称, 关键字可填写：行政区名称（\'中华人民共和国\'\'中国\'\'全国\'\'河北省\'\'深圳市\'，省、市、区和镇名称）以及 adcode\",\"required\":true},{\"name\":\"boundary\",\"description\":\"是否返回行政区划边界信息, 取值为\'1\'表示返回, \'0\'表示不返回, 默认为\'0\'\"}]},{\"name\":\"map_uri\",\"description\":\"地图调起服务: 生成百度地图调起链接, 支持路线规划和地点检索两种功能. 通过service参数决定使用哪种功能.\",\"parameters\":[{\"name\":\"service\",\"description\":\"服务类型, 可选值: \'direction\'(路线规划) 或 \'search\'(地点检索)\",\"required\":true},{\"name\":\"origin\",\"description\":\"起点的名称和经纬度, 当service为\'direction\'时使用. 格式: name:天安门|latlng:39.98871,116.43234. 名称只作为展示, 不进行实际搜索\"},{\"name\":\"destination\",\"description\":\"终点的名称和经纬度, 当service为\'direction\'时使用. 格式同origin\"},{\"name\":\"mode\",\"description\":\"导航模式, 当service为\'direction\'时使用. 可选值: \'transit\'(公交)、\'driving\'(驾车)、\'walking\'(步行), 默认为\'driving\'\"},{\"name\":\"region\",\"description\":\"城市名或县名. 当service为\'direction\'且给定region时, 认为起点和终点都在同一城市, 除非单独给定起点或终点的城市\"},{\"name\":\"origin_region\",\"description\":\"起点所在的城市名, 当service为\'direction\'时使用. 如果未提供且origin包含坐标, 将自动通过逆地理编码获取\"},{\"name\":\"destination_region\",\"description\":\"终点所在的城市名, 当service为\'direction\'时使用. 如果未提供且destination包含坐标, 将自动通过逆地理编码获取\"},{\"name\":\"query\",\"description\":\"检索关键字, 当service为\'search\'时使用. 如\'海底捞\'\"},{\"name\":\"location\",\"description\":\"检索中心点经纬度, 当service为\'search\'时使用. 格式: 纬度,经度\"},{\"name\":\"radius\",\"description\":\"检索半径(米), 当service为\'search\'时使用. 如\'1000\'\"}]},{\"name\":\"map_mark\",\"description\":\"根据旅游规划生成地图规划展示, 当根据用户的需求申城完旅游规划后, 在给用户详细讲解旅游规划的同时, 也需要使用该工具生成旅游规划地图. 该工具只会生成一个分享用的url, 并对针对该url生成一个二维码便于用户分享.\",\"parameters\":[{\"name\":\"text_content\",\"description\":\"旅行规划的文本描述(注意避免传入特殊字符, 如\\\\等)\",\"required\":true}]}]', 'enable', 1, '{\"tool_count\":13}', 'admin', '2025-12-18 16:27:44', 'admin', '2026-04-28 09:42:41', 'A05A01A01', NULL);
