INSERT INTO `chat2bi_domain` (`id`, `name`, `description`, `datasource_id`, `status`, `sort_no`, `joins_json`, `perm_json`, `create_by`, `create_time`, `update_by`, `update_time`, `tenant_id`, `aggregate_query_limit`, `detail_query_limit`) VALUES ('6a01a7bce0174875a413f60e5bdec16b', '保险分析域', '保险业务问数：保单、保费、保额、理赔的多维分析', '', 'enabled', 1, '[{\"id\": 1, \"left\": \"f7c4d22abafa4ac982679e9b1fba3cc5\", \"right\": \"70b99ccd7def497592a7df9f333f42fe\", \"leftCol\": \"cust_id\", \"rightCol\": \"id\", \"type\": \"LEFT JOIN\"}, {\"id\": 2, \"left\": \"56b5a44298cc4dfa82d8594be16ff3b3\", \"right\": \"f7c4d22abafa4ac982679e9b1fba3cc5\", \"leftCol\": \"policy_id\", \"rightCol\": \"id\", \"type\": \"LEFT JOIN\"}]', '{\"grantRoles\": [], \"grantUsers\": [], \"sensWords\": [\"王总\"], \"sensCats\": {\"politics\": true, \"abuse\": true}, \"rowRules\": [{\"id\": 1, \"role\": \"区域经理\", \"field\": \"region\", \"op\": \"=\", \"value\": \"华东\", \"dynamic\": false, \"sysVar\": \"\"}], \"colRules\": [{\"id\": 1, \"role\": \"分析师\", \"field\": \"premium\", \"action\": \"脱敏\"}], \"sensitivity\": {}, \"isPublic\": false}', 'admin', '2026-05-24 10:00:00', 'admin', '2026-05-25 10:00:00', 0, 50, 50);
INSERT INTO `chat2bi_domain` (`id`, `name`, `description`, `datasource_id`, `status`, `sort_no`, `joins_json`, `perm_json`, `create_by`, `create_time`, `update_by`, `update_time`, `tenant_id`, `aggregate_query_limit`, `detail_query_limit`) VALUES ('8422bb4067874cd5b9c8976962621104', '系统用户分析域', '平台系统用户分析：用户、部门、归属关系的多维统计', '', 'enabled', 2, '[{\"id\": 1, \"left\": \"6e67740eef90410ea898c08dc0159aad\", \"right\": \"e7a66f18e0a24068934ab3972ca2d718\", \"leftCol\": \"user_id\", \"rightCol\": \"id\", \"type\": \"LEFT JOIN\"}, {\"id\": 2, \"left\": \"6e67740eef90410ea898c08dc0159aad\", \"right\": \"d1c0fc67d9a64c19b36bd12bfcf22cdd\", \"leftCol\": \"dep_id\", \"rightCol\": \"id\", \"type\": \"LEFT JOIN\"}]', '{\"grantRoles\":[],\"grantUsers\":[],\"sensWords\":[],\"sensCats\":{\"politics\":true,\"abuse\":true},\"rowRules\":[],\"colRules\":[{\"id\":1779706530340,\"role\":\"区域经理\",\"field\":\"org_code\",\"action\":\"脱敏\"},{\"id\":1779706535255,\"role\":\"区域经理\",\"field\":\"parent_id\",\"action\":\"脱敏\"},{\"id\":1779706542086,\"role\":\"财务\",\"field\":\"status\",\"action\":\"脱敏\"}],\"sensitivity\":{},\"isPublic\":true}', 'admin', '2026-05-24 11:00:00', 'admin', '2026-05-25 18:56:10', 0, 50, 50);
INSERT INTO `chat2bi_message` (`id`, `conversation_id`, `role`, `content`, `msg_json`, `sort_no`, `create_time`) VALUES ('05a430c90bd2438b9daf729f1f5270e5', 'bc75e772eafe43639e4e8f1698e51543', 'user', '各险种的保费总额', '{\"role\": \"user\", \"text\": \"各险种的保费总额\"}', 0, '2026-05-24 06:00:00');
INSERT INTO `chat2bi_message` (`id`, `conversation_id`, `role`, `content`, `msg_json`, `sort_no`, `create_time`) VALUES ('063575b460304bd6af6bef809338180e', '3d83bf2875f34bb4aa4119a43d515b99', 'ai', '已理解你的问题，按下面的口径为你取数（可直接调整）：', '{\"role\": \"ai\", \"text\": \"已理解你的问题，按下面的口径为你取数（可直接调整）：\", \"dsl\": {\"metric\": \"实赔金额\", \"dimension\": \"险种类型\", \"time\": \"全部\", \"filter\": \"\", \"limit\": 100}, \"data\": [[\"意外险\", \"661,410\"], [\"健康险\", \"606,549\"], [\"车险\", \"539,711\"], [\"财产险\", \"425,733\"], [\"寿险\", \"408,964\"]], \"sql\": \"SELECT product_type, SUM(settle_amount) AS settle_sum\\nFROM ins_claim\\nWHERE status=\'已赔付\'\\nGROUP BY product_type\\nORDER BY 2 DESC\", \"insight\": \"「意外险」的实赔金额最高（661,410），约占总量的 25%。\", \"chart\": false, \"chartType\": \"柱状图\", \"followup\": false}', 1, '2026-05-24 08:00:00');
