\"\"],[\"1179675874431131649\",\"qinfeng\",\"秦风\",\"1\",\"1\",\"20011\",\"qinfeng@jeecg.org\",\"13411111111\",\"A05A01\",\"2019-10-03T16:33:40\",\"投资控股集团有限公司\"],[\"e9ca23d68d884d4ebb19d07889727dae\",\"admin\",\"管理员\",\"1\",\"1\",\"A0001\",\"zhangdaiscott@163.com\",\"18611111111\",\"A01A05\",\"2019-06-21T17:54:10\",\"信息技术发展有限公司\"],[\"e9ca23d68d884d4ebb19d07889727dae\",\"admin\",\"管理员\",\"1\",\"1\",\"A0001\",\"zhangdaiscott@163.com\",\"18611111111\",\"A01A05\",\"2019-06-21T17:54:10\",\"研发部\"],[\"a75d45a015c44384a04449ee80dc3503\",\"jeecg\",\"JEECG演示\",\"1\",\"1\",\"A002\",\"jeecgos@163.com\",\"18611788525\",\"A01\",\"2019-02-13T16:02:36\",\"北京国炬软件信息\"]],\"sql\":\"SELECT \\n    u.id AS 用户ID,\\n    u.username AS 登录账号,\\n    u.realname AS 真实姓名,\\n    u.sex AS 性别,\\n    u.status AS 状态,\\n    u.work_no AS 工号,\\n    u.email AS 邮箱,\\n    u.phone AS 手机号,\\n    u.org_code AS 用户机构编码,\\n    u.create_time AS 创建时间,\\n    d.depart_name AS 部门名称\\nFROM sys_user u\\nLEFT JOIN sys_user_depart ud ON u.id = ud.user_id\\nLEFT JOIN sys_depart d ON ud.dep_id = d.id\\nORDER BY u.create_time DESC\\nLIMIT 50\",\"insight\":\"共查询到 30 条记录，11 个字段。\",\"chart\":false,\"chartType\":\"柱状图\",\"followup\":false}', 12, '2026-08-10 11:38:51');
