INSERT INTO `chat2bi_table` (`id`, `domain_id`, `name`, `label`, `mode`, `sql_text`, `columns_json`, `sort_no`, `create_by`, `create_time`, `update_by`, `update_time`, `tenant_id`) VALUES ('56b5a44298cc4dfa82d8594be16ff3b3', '6a01a7bce0174875a413f60e5bdec16b', 'ins_claim', '理赔', 'table', '', '[{\"col\": \"id\", \"type\": \"pk\", \"agg\": \"—\", \"alias\": \"理赔ID\", \"enabled\": true}, {\"col\": \"claim_no\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"理赔单号\", \"enabled\": true}, {\"col\": \"policy_id\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"保单ID\", \"enabled\": true}, {\"col\": \"policy_no\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"保单号\", \"enabled\": true}, {\"col\": \"cust_name\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"客户姓名\", \"enabled\": true}, {\"col\": \"product_type\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"险种类型\", \"enabled\": true}, {\"col\": \"report_date\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"报案日期\", \"enabled\": true}, {\"col\": \"claim_type\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"理赔类型（医疗费用/身故赔付/车辆损失/意外伤害/重疾给付）\", \"enabled\": true}, {\"col\": \"claim_amount\", \"type\": \"metric\", \"agg\": \"SUM\", \"alias\": \"申请理赔金额（元）\", \"enabled\": true}, {\"col\": \"settle_amount\", \"type\": \"metric\", \"agg\": \"SUM\", \"alias\": \"实际赔付金额（元）\", \"enabled\": true}, {\"col\": \"status\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"理赔状态（待审核/已赔付/已拒赔）\", \"enabled\": true}, {\"col\": \"province\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"出险省份\", \"enabled\": true}]', 2, 'admin', '2026-05-24 10:00:00', 'admin', '2026-05-24 10:00:00', 0);
INSERT INTO `chat2bi_table` (`id`, `domain_id`, `name`, `label`, `mode`, `sql_text`, `columns_json`, `sort_no`, `create_by`, `create_time`, `update_by`, `update_time`, `tenant_id`) VALUES ('6e67740eef90410ea898c08dc0159aad', '8422bb4067874cd5b9c8976962621104', 'sys_user_depart', '用户部门关联', 'table', '', '[{\"col\": \"ID\", \"type\": \"pk\", \"agg\": \"—\", \"alias\": \"关联ID\", \"enabled\": true}, {\"col\": \"user_id\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"用户ID\", \"enabled\": true}, {\"col\": \"dep_id\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"部门ID\", \"enabled\": true}]', 3, 'admin', '2026-05-24 11:00:00', 'admin', '2026-05-24 11:00:00', 0);
INSERT INTO `chat2bi_table` (`id`, `domain_id`, `name`, `label`, `mode`, `sql_text`, `columns_json`, `sort_no`, `create_by`, `create_time`, `update_by`, `update_time`, `tenant_id`) VALUES ('70b99ccd7def497592a7df9f333f42fe', '6a01a7bce0174875a413f60e5bdec16b', 'ins_customer', '客户', 'table', '', '[{\"col\": \"id\", \"type\": \"pk\", \"agg\": \"—\", \"alias\": \"客户ID\", \"enabled\": true}, {\"col\": \"cust_no\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"客户编号\", \"enabled\": true}, {\"col\": \"cust_name\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"客户姓名\", \"enabled\": true}, {\"col\": \"gender\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"性别（男/女）\", \"enabled\": true}, {\"col\": \"age\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"年龄\", \"enabled\": true}, {\"col\": \"province\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"省份\", \"enabled\": true}, {\"col\": \"city\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"城市\", \"enabled\": true}, {\"col\": \"region\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"大区（华东/华南/华北/华中/西南/西北）\", \"enabled\": true}, {\"col\": \"occupation\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"职业\", \"enabled\": true}, {\"col\": \"cust_level\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"客户等级（普通/银卡/金卡/白金）\", \"enabled\": true}, {\"col\": \"reg_date\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"注册日期\", \"enabled\": true}]', 3, 'admin', '2026-05-24 10:00:00', 'admin', '2026-05-24 10:00:00', 0);
INSERT INTO `chat2bi_table` (`id`, `domain_id`, `name`, `label`, `mode`, `sql_text`, `columns_json`, `sort_no`, `create_by`, `create_time`, `update_by`, `update_time`, `tenant_id`) VALUES ('a0d30daf82504bae9d9a2e18a45c4e4e', '6a01a7bce0174875a413f60e5bdec16b', 'v_ins_premium_trend', '月度保费趋势(虚拟SQL)', 'sql', 'SELECT DATE_FORMAT(sign_date, \'%Y-%m\') AS stat_month, product_type, COUNT(*) AS policy_cnt, SUM(premium) AS premium_total, SUM(coverage_amount) AS coverage_total FROM ins_policy GROUP BY stat_month, product_type ORDER BY stat_month', '[{\"col\": \"stat_month\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"统计月份\", \"enabled\": true}, {\"col\": \"product_type\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"险种类型\", \"enabled\": true}, {\"col\": \"policy_cnt\", \"type\": \"metric\", \"agg\": \"SUM\", \"alias\": \"保单数\", \"enabled\": true}, {\"col\": \"premium_total\", \"type\": \"metric\", \"agg\": \"SUM\", \"alias\": \"保费合计\", \"enabled\": true}, {\"col\": \"coverage_total\", \"type\": \"metric\", \"agg\": \"SUM\", \"alias\": \"保额合计\", \"enabled\": true}]', 4, 'admin', '2026-05-24 10:00:00', 'admin', '2026-05-24 10:00:00', 0);
INSERT INTO `chat2bi_table` (`id`, `domain_id`, `name`, `label`, `mode`, `sql_text`, `columns_json`, `sort_no`, `create_by`, `create_time`, `update_by`, `update_time`, `tenant_id`) VALUES ('d1c0fc67d9a64c19b36bd12bfcf22cdd', '8422bb4067874cd5b9c8976962621104', 'sys_depart', '部门', 'table', '', '[{\"col\": \"id\", \"type\": \"pk\", \"agg\": \"—\", \"alias\": \"部门ID\", \"enabled\": true}, {\"col\": \"depart_name\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"部门名称\", \"enabled\": true}, {\"col\": \"org_category\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"机构类别\", \"enabled\": true, \"dict\": \"org_category\"}, {\"col\": \"org_code\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"机构编码\", \"enabled\": true}, {\"col\": \"parent_id\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"上级部门ID\", \"enabled\": true}, {\"col\": \"status\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"状态\", \"enabled\": true}]', 2, 'admin', '2026-05-24 11:00:00', 'admin', '2026-05-24 11:00:00', 0);
INSERT INTO `chat2bi_table` (`id`, `domain_id`, `name`, `label`, `mode`, `sql_text`, `columns_json`, `sort_no`, `create_by`, `create_time`, `update_by`, `update_time`, `tenant_id`) VALUES ('e7a66f18e0a24068934ab3972ca2d718', '8422bb4067874cd5b9c8976962621104', 'sys_user', '用户', 'table', '', '[{\"col\": \"id\", \"type\": \"pk\", \"agg\": \"—\", \"alias\": \"用户ID\", \"enabled\": true}, {\"col\": \"username\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"登录账号\", \"enabled\": true}, {\"col\": \"realname\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"真实姓名\", \"enabled\": true}, {\"col\": \"sex\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"性别\", \"enabled\": true, \"dict\": \"sex\"}, {\"col\": \"status\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"状态\", \"enabled\": true, \"dict\": \"user_status\"}, {\"col\": \"work_no\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"工号\", \"enabled\": true}, {\"col\": \"email\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"邮箱\", \"enabled\": true}, {\"col\": \"phone\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"手机号\", \"enabled\": true}, {\"col\": \"org_code\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"机构编码\", \"enabled\": true}, {\"col\": \"create_time\", \"type\": \"dim\", \"agg\": \"—\", \"alias\": \"创建时间\", \"enabled\": true}]', 1, 'admin', '2026-05-24 11:00:00', 'admin', '2026-05-24 11:00:00', 0);
