INSERT INTO `onl_drag_dataset_head` (`id`, `name`, `code`, `parent_id`, `db_source`, `query_sql`, `content`, `iz_agent`, `data_type`, `api_method`, `create_time`, `create_by`, `update_time`, `update_by`, `low_app_id`, `tenant_id`) VALUES ('1522503560003067906', '首页_近一周访问量', '', '1516743332632494082', '707437208002265088', 'select count(*) as visit\n        	   ,count(distinct(ip)) as ip\n        	   ,DATE_FORMAT(create_time, \'%Y-%m-%d\') as tian\n        	   ,DATE_FORMAT(create_time, \'%m-%d\') as type\n        	   from sys_log \n         where log_type = 1 and create_time <= sysdate() and create_time >= (select date_sub(curdate(),interval 7 day))\n         group by tian,type\n         order by tian desc', '', '0', 'sql', 'get', '2022-05-06 17:08:30', 'admin', '2022-05-06 17:49:07', 'admin', NULL, NULL);
