pe\\\":\\\"温度\\\",\\\"yAxisIndex\\\":\\\"1\\\"},{\\\"name\\\":\\\"1997\\\",\\\"value\\\":37,\\\"type\\\":\\\"温度\\\",\\\"yAxisIndex\\\":\\\"1\\\"},{\\\"name\\\":\\\"1998\\\",\\\"value\\\":39,\\\"type\\\":\\\"温度\\\",\\\"yAxisIndex\\\":\\\"1\\\"},{\\\"name\\\":\\\"1999\\\",\\\"value\\\":33,\\\"type\\\":\\\"温度\\\",\\\"yAxisIndex\\\":\\\"1\\\"}]\",\"size\":{\"width\":382.0987654320988,\"height\":277.77777777777777},\"actionConfig\":{\"operateType\":\"modal\",\"modalName\":\"\",\"url\":\"\"},\"seriesType\":[{\"series\":\"降水量\",\"yIndex\":\"0\",\"type\":\"bar\"},{\"series\":\"温度\",\"yIndex\":\"1\",\"type\":\"line\"}],\"background\":\"#FFFFFF00\",\"w\":450,\"turnConfig\":{\"type\":\"_blank\",\"url\":\"\"},\"linkType\":\"url\",\"linkageConfig\":[],\"option\":{\"barWidth\":15,\"symbol\":\"emptyCircle\",\"xAxis\":{\"axisLabel\":{\"color\":\"#EEF1FA\"}},\"symbolSize\":4,\"legend\":{\"t\":0},\"tooltip\":{\"axisPointer\":{\"label\":{\"backgroundColor\":\"#333\",\"show\":true},\"type\":\"shadow\"},\"trigger\":\"axis\",\"textStyle\":{\"color\":\"#EEF1FA\"}},\"title\":{\"textAlign\":\"left\",\"show\":true,\"text\":\"\",\"textStyle\":{\"fontSize\":\"14\",\"fontWeight\":\"normal\"}},\"lineWidth\":1,\"areaStyleOpacity\":0,\"yAxis\":[{\"axisLabel\":{\"color\":\"#EEF1FA\"},\"splitLine\":{\"lineStyle\":{\"color\":\"#8F8D8D\"},\"show\":false,\"interval\":2},\"type\":\"value\",\"yUnit\":\"\"},{\"axisLabel\":{\"color\":\"#EEF1FA\"},\"splitLine\":{\"lineStyle\":{\"color\":\"#8F8D8D\"},\"interval\":2},\"type\":\"value\",\"yUnit\":\"\"}],\"customColor\":[{\"color1\":\"#1e90ff\",\"color\":\"#1e90ff\"},{\"color1\":\"#90ee90\",\"color\":\"#90ee90\"},{\"color1\":\"#00ced1\",\"color\":\"#00ced1\"},{\"color1\":\"#e2bd84\",\"color\":\"#e2bd84\"},{\"color1\":\"#7a90e0\",\"color\":\"#7a90e0\"},{\"color1\":\"#3ba272\",\"color\":\"#3ba272\"},{\"color1\":\"#2be7ff\",\"color\":\"#2be7ff\"},{\"color1\":\"#0a8ada\",\"color\":\"#0a8ada\"},{\"color1\":\"#ffd700\",\"color\":\"#ffd700\"}],\"borderRadius\":0,\"gri