INSERT INTO `onl_drag_page_comp` (`id`, `parent_id`, `page_Id`, `comp_id`, `component`, `config`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES ('1231392796344090624', NULL, '1231392793810731008', NULL, 'JStatsSummary', '{\"dataType\": 1, \"timeOut\": 0, \"size\": {\"width\": 1872, \"height\": 180}, \"chart\": {\"subclass\": \"JStatsSummary\", \"category\": \"Common\"}, \"option\": {\"layout\": {\"gap\": 16, \"padding\": {\"top\": 16, \"right\": 16, \"bottom\": 0, \"left\": 16}, \"justify\": \"space-between\", \"borderRadius\": 0, \"borderWidth\": 0, \"borderColor\": \"#0f66ff59\", \"shadow\": \"none\", \"fill\": {\"type\": \"none\", \"color\": \"#0b2b63\", \"gradient\": {\"enabled\": false, \"type\": \"linear\", \"direction\": \"to bottom right\", \"startColor\": \"#05336a\", \"endColor\": \"#0bb2ff\", \"angle\": 135}, \"image\": {\"url\": \"\", \"size\": \"cover\", \"repeat\": \"no-repeat\", \"position\": \"center\"}}}, \"card\": {\"minWidth\": 220, \"borderRadius\": 16, \"borderColor\": \"#0f66ff59\", \"borderWidth\": 1, \"shadow\": \"0 16px 48px #0b76ff59\", \"blur\": 24, \"padding\": {\"vertical\": 24, \"horizontal\": 24}, \"fill\": {\"type\": \"color\", \"color\": \"#0b2b63\", \"gradient\": {\"enabled\": false, \"type\": \"linear\", \"direction\": \"to bottom right\", \"startColor\": \"#05336a\", \"endColor\": \"#0bb2ff\", \"angle\": 135}, \"image\": {\"url\": \"\", \"size\": \"cover\", \"repeat\": \"no-repeat\", \"position\": \"center\"}}}, \"sections\": {\"top\": {\"align\": \"center\", \"paddingTop\": 0, \"paddingBottom\": 10, \"minHeight\": 0, \"show\": true, \"type\": \"value\", \"value\": {\"fontSize\": 34, \"fontWeight\": 600, \"fontColor\": \"#d8f1ff\", \"fontGradient\": {\"enabled\": true, \"type\": \"linear\", \"direction\": \"135deg\", \"startColor\": \"#73e0ff\", \"endColor\": \"#d8f1ff\"}, \"unitGap\": 6, \"unit\": {\"fontSize\": 18, \"fontWeight\": 500, \"fontColor\": \"#9ed3ff\", \"fontGradient\": {\"enabled\": false, \"type\": \"linear\", \"direction\": \"135deg\", \"startColor\": \"#9ed3ff\", \"endColor\": \"#cfeaff\"}}}}, \"middle\": {\"align\": \"center\", \"paddingTop\": 0, \"paddingBottom\": 10, \"minHeight\": 0, \"show\": true, \"type\": \"compare\", \"compare\": {\"label\": \"同比\", \"alignItems\": \"baseline\", \"labelStyle\": {\"fontSize\": 14, \"fontColor\": \"#9ed3ff\", \"fontGradient\": {\"enabled\": false, \"type\": \"linear\", \"direction\": \"135deg\", \"startColor\": \"#9ed3ff\", \"endColor\": \"#cfeaff\"}}, \"valueStyle\": {\"fontSize\": 14, \"fontColor\": \"#ffffff\", \"positiveColor\": \"#15f0c5\", \"positiveGradient\": {\"enabled\": false, \"type\": \"linear\", \"direction\": \"135deg\", \"startColor\": \"#15f0c5\", \"endColor\": \"#15f0c5\"}, \"negativeColor\": \"#D0021B\", \"negativeGradient\": {\"enabled\": false, \"type\": \"linear\", \"direction\": \"135deg\", \"startColor\": \"#D0021B\", \"endColor\": \"#D0021B\"}, \"fontGradient\": {\"enabled\": false, \"type\": \"linear\", \"direction\": \"135deg\", \"startColor\": \"#9ed3ff\", \"endColor\": \"#cfeaff\"}}}}, \"bottom\": {\"align\": \"center\", \"paddingTop\": 0, \"paddingBottom\": 10, \"minHeight\": 0, \"show\": true, \"type\": \"label\", \"label\": {\"fontSize\": 16, \"fontColor\": \"#cfeaff\", \"fontGradient\": {\"enabled\": false, \"type\": \"linear\", \"direction\": \"135deg\", \"startColor\": \"#cfeaff\", \"endColor\": \"#9ed3ff\"}}}}, \"fieldMap\": {\"label\": \"name\", \"value\": \"value\", \"unit\": \"suffix\", \"compareValue\": \"compareValue\", \"compareState\": \"compareState\", \"compareLabel\": \"compareLabel\", \"positiveValue\": \"1\", \"negativeValue\": \"0\"}, \"highlight\": []}, \"chartData\": \"[{\\\"id\\\": \\\"1\\\", \\\"name\\\": \\\"今日靠泊船舶\\\", \\\"value\\\": 87, \\\"suffix\\\": \\\"艘\\\", \\\"compareLabel\\\": \\\"日环比\\\", \\\"compareValue\\\": \\\"+5.2%\\\", \\\"compareState\\\": \\\"1\\\"}, {\\\"id\\\": \\\"2\\\", \\\"name\\\": \\\"集装箱吞吐量\\\", \\\"value\\\": 24850, \\\"suffix\\\": \\\"TEU\\\", \\\"compareLabel\\\": \\\"日环比\\\", \\\"compareValue\\\": \\\"+3.8%\\\", \\\"compareState\\\": \\\"1\\\"}, {\\\"id\\\": \\\"3\\\", \\\"name\\\": \\\"桥吊作业效率\\\", \\\"value\\\": 38.6, \\\"suffix\\\": \\\"箱/小时\\\", \\\"compareLabel\\\": \\\"日环比\\\", \\\"compareValue\\\": \\\"+1.5%\\\", \\\"compareState\\\": \\\"1\\\"}, {\\\"id\\\": \\\"4\\\", \\\"name\\\": \\\"堆场利用率\\\", \\\"value\\\": 76.3, \\\"suffix\\\": \\\"%\\\", \\\"compareLabel\\\": \\\"日环比\\\", \\\"compareValue\\\": \\\"-2.1%\\\", \\\"compareState\\\": \\\"0\\\"}, {\\\"id\\\": \\\"5\\\", \\\"name\\\": \\\"当前在港船舶\\\", \\\"value\\\": 142, \\\"suffix\\\": \\\"艘\\\", \\\"compareLabel\\\": \\\"日环比\\\", \\\"compareValue\\\": \\\"+8.4%\\\", \\\"compareState\\\": \\\"1\\\"}, {\\\"id\\\": \\\"6\\\", \\\"name\\\": \\\"综合运营指数\\\", \\\"value\\\": 94.8, \\\"suffix\\\": \\\"分\\\", \\\"compareLabel\\\": \\\"日环比\\\", \\\"compareValue\\\": \\\"+0.6%\\\", \\\"compareState\\\": \\\"1\\\"}]\", \"linkageConfig\": [], \"turnConfig\": {\"url\": \"\", \"type\": \"_blank\"}, \"linkType\": \"url\", \"w\": 1872, \"h\": 180, \"background\": \"#FFFFFF00\", \"borderColor\": \"#FFFFFF00\"}', 'admin', '2026-06-29 10:02:11', NULL, NULL);
