INSERT INTO `onl_drag_page_comp` (`id`, `parent_id`, `page_Id`, `comp_id`, `component`, `config`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES ('1231521823161274368', NULL, '1229579046974345216', NULL, 'JCustomEchart', '{\"borderColor\":\"#FFFFFF00\",\"dataType\":1,\"h\":300,\"customEchartOption\":\"\",\"url\":\"\",\"timeOut\":0,\"size\":{\"width\":979.1666666666667,\"height\":712.5},\"actionConfig\":{\"operateType\":\"modal\",\"modalName\":\"\",\"url\":\"\"},\"background\":\"#FFFFFF00\",\"w\":450,\"customRenderType\":\"html\",\"customHtmlContent\":\"<!DOCTYPE html>\\n<html lang=\\\"zh-CN\\\">\\n\\n<head>\\n  <meta charset=\\\"utf-8\\\">\\n  <meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1\\\">\\n  <title>3D 地球 + 中国 3D 地图（纯 HTML 版）</title>\\n\\n  <!--\\n    ============================================================\\n      3D 地球 + 中国 3D 地图融合版（纯 HTML，无模板语法、单文件）\\n      默认显示 3D 地球；点击中国国土高亮区域 → 相机推近 + 黑蒙层\\n      过渡 → 进入中国省级 3D 地图（可下钻到地市级）→ 返回按钮\\n      按层级递退；面包屑可点击跨级跳。\\n      依赖：Three.js r130 + addons（CDN 加载）。无 sibling JS 文件。\\n    ============================================================\\n  -->\\n\\n  <style>\\n    * {\\n      margin: 0;\\n      padding: 0;\\n      box-sizing: border-box;\\n    }\\n\\n    html,\\n    body {\\n      width: 100%;\\n      height: 100%;\\n      overflow: hidden;\\n      font-family: \'PingFang SC\', \'Microsoft YaHei\', system-ui, sans-serif;\\n    }\\n\\n    @keyframes pulseDot {\\n\\n      0%,\\n      100% {\\n        opacity: .55;\\n        transform: scale(.8);\\n      }\\n\\n      50% {\\n        opacity: 1;\\n        transform: scale(1.15);\\n      }\\n    }\\n\\n    @keyframes bjspin {\\n      to {\\n        transform: rotate(360deg);\\n      }\\n    }\\n\\n    /* === 地球场景（earth-only） === */\\n    #earth-root {\\n      position: fixed;\\n      inset: 0;\\n      /* background: radial-gradient(ellipse at 50% 45%, #05111f 0%, #020409 55%, #000 100%); */\\n      cursor: grab;\\n      overflow: hidden;\\n    }\\n\\n    #earth-holder {\\n      position: absolute;\\n      inset: 0;\\n    }\\n\\n    #earth-labels {\\n      position: absolute;\\n      inset: 0;\\n      pointer-events: none;\\n      z-index: 3;\\n    }\\n\\n    /* === 中国场景（china-only） === */\\n    #china-holder {\\n      position: fixed;\\n      inset: 0;\\n      background: transparent;\\n      font-family: \'Noto Sans SC\', \'PingFang SC\', \'Microsoft YaHei\', sans-serif;\\n      cursor: grab;\\n      overflow: hidden;\\n    }\\n\\n    #china-holder canvas {\\n      display: block;\\n      outline: none;\\n    }\\n\\n    .china-labels {\\n      position: absolute;\\n      inset: 0;\\n      pointer-events: none;\\n      z-index: 5;\\n      overflow: hidden;\\n    }\\n\\n    .china-header {\\n      position: absolute;\\n      left: 42px;\\n      top: 36px;\\n      z-index: 7;\\n      pointer-events: none;\\n      display: none;\\n    }\\n\\n    .china-header .title {\\n      font-size: 30px;\\n      font-weight: 900;\\n      color: #eaf4ff;\\n      letter-spacing: 2px;\\n      text-shadow: 0 0 24px rgba(60, 150, 255, .6);\\n    }\\n\\n    .china-header .sub-row {\\n      display: flex;\\n      align-items: center;\\n      gap: 9px;\\n      margin-top: 12px;\\n    }\\n\\n    .china-header .pulse {\\n      width: 7px;\\n      height: 7px;\\n      border-radius: 50%;\\n      background: #3fd2ff;\\n      box-shadow: 0 0 10px #3fd2ff;\\n      animation: pulseDot 1.6s infinite;\\n    }\\n\\n    .china-header .sub {\\n      font-size: 12px;\\n      letter-spacing: 3px;\\n      color: #7fb6e6;\\n    }\\n\\n    .china-back {\\n      display: none;\\n      align-items: center;\\n      gap: 8px;\\n      position: absolute;\\n      right: 42px;\\n      top: 40px;\\n      z-index: 8;\\n      pointer-events: auto;\\n      cursor: pointer;\\n      font-size: 13px;\\n      font-weight: 700;\\n      letter-spacing: 2px;\\n      color: #a5c8ff;\\n      padding: 9px 17px;\\n      border-radius: 7px;\\n      background: rgba(8, 30, 70, .78);\\n      border: 1px solid rgba(73, 176, 255, .55);\\n      box-shadow: 0 0 16px rgba(73, 176, 255, .28);\\n      backdrop-filter: blur(3px);\\n      user-select: none;\\n    }\\n\\n    .china-back .arrow {\\n      font-family: \'Orbitron\', sans-serif;\\n      font-size: 15px;\\n    }\\n\\n    .china-loading {\\n      position: absolute;\\n      inset: 0;\\n      z-index: 9;\\n      display: flex;\\n      flex-direction: column;\\n      align-items: center;\\n      justify-content: center;\\n      gap: 18px;\\n      color: #a5c8ff;\\n    }\\n\\n    .china-loading .spinner {\\n      width: 46px;\\n      height: 46px;\\n      border: 3px solid rgba(73, 176, 255, .18);\\n      border-top-color: #49b0ff;\\n      border-radius: 50%;\\n      animation: bjspin .9s linear infinite;\\n    }\\n\\n    .china-loading .txt {\\n      font-size: 13px;\\n      letter-spacing: 4px;\\n    }\\n\\n    /* === 左侧 6 个功能开关（earth-only） === */\\n    #feature-toggles {\\n      position: absolute;\\n      left: 20px;\\n      top: 50%;\\n      transform: translateY(-50%);\\n      display: flex;\\n      flex-direction: column;\\n      gap: 11px;\\n      z-index: 6;\\n    }\\n\\n    .feature-pill {\\n      width: 86px;\\n      padding: 9px 0;\\n      text-align: center;\\n      font-size: 14px;\\n      letter-spacing: 2px;\\n      border-radius: 4px;\\n      cursor: pointer;\\n      user-select: none;\\n      backdrop-filter: blur(4px);\\n      transition: all .18s ease;\\n    }\\n\\n    /* === 信息卡片（earth-only，点城市标记后显示） === */\\n    #info-card {\\n      display: none;\\n      position: absolute;\\n      width: 308px;\\n      z-index: 7;\\n      border-radius: 7px;\\n      overflow: hidden;\\n      background: linear-gradient(160deg, rgba(14, 30, 46, 0.94), rgba(7, 16, 26, 0.94));\\n      border: 1px solid rgba(90, 170, 220, 0.45);\\n      box-shadow:\\n        0 0 0 1px rgba(40, 90, 120, 0.5),\\n        0 18px 50px rgba(0, 0, 0, 0.6),\\n        inset 0 0 30px rgba(30, 90, 140, 0.25);\\n    }\\n\\n    .card-head {\\n      display: flex;\\n      align-items: center;\\n      justify-content: space-between;\\n      padding: 11px 14px;\\n      border-bottom: 1px solid rgba(80, 150, 200, 0.28);\\n      background: linear-gradient(180deg, rgba(30, 70, 100, 0.45), rgba(20, 45, 68, 0.2));\\n    }\\n\\n    .card-head-titles {\\n      display: flex;\\n      align-items: baseline;\\n      gap: 9px;\\n    }\\n\\n    .card-title {\\n      color: #54c8ff;\\n      font-size: 15px;\\n      font-weight: 600;\\n      letter-spacing: 1px;\\n    }\\n\\n    .card-title-en {\\n      color: #5e7d92;\\n      font-size: 10px;\\n      letter-spacing: 1.5px;\\n    }\\n\\n    .card-close {\\n      display: flex;\\n      align-items: center;\\n      gap: 4px;\\n      color: #7fa6bd;\\n      font-size: 12px;\\n      cursor: pointer;\\n      user-select: none;\\n    }\\n\\n    .card-close-x {\\n      font-size: 14px;\\n    }\\n\\n    .card-body {\\n      padding: 15px 16px 18px;\\n    }\\n\\n    .card-status {\\n      display: flex;\\n      align-items: center;\\n      gap: 10px;\\n      margin-bottom: 15px;\\n    }\\n\\n    .status-icon {\\n      width: 26px;\\n      height: 26px;\\n      border-radius: 50%;\\n      border: 1.5px solid #34d07a;\\n      display: flex;\\n      align-items: center;\\n      justify-content: center;\\n      color: #34d07a;\\n      font-size: 13px;\\n    }\\n\\n    .status-text {\\n      line-height: 1.2;\\n    }\\n\\n    .status-label {\\n      color: #e8f3fa;\\n      font-size: 14px;\\n    }\\n\\n    .status-en {\\n      color: #5c7d92;\\n      font-size: 9px;\\n      letter-spacing: 1.5px;\\n    }\\n\\n    .card-row {\\n      display: flex;\\n      align-items: center;\\n      justify-content: space-between;\\n      padding: 7px 0;\\n      border-top: 1px dashed rgba(80, 140, 180, 0.22);\\n      font-size: 12.5px;\\n    }\\n\\n    .row-label {\\n      color: #6f93a8;\\n    }\\n\\n    .row-value {\\n      color: #cfe4f2;\\n    }\\n\\n    .row-value.progress {\\n      display: flex;\\n      align-items: center;\\n      gap: 8px;\\n    }\\n\\n    .progress-track {\\n      width: 78px;\\n      height: 5px;\\n      border-radius: 3px;\\n      background: rgba(40, 80, 110, 0.5);\\n      overflow: hidden;\\n      display: inline-block;\\n    }\\n\\n    .progress-fill {\\n      display: block;\\n      width: 32%;\\n      height: 100%;\\n      background: linear-gradient(90deg, #2fa8ff, #54e0ff);\\n    }\\n\\n    /* === 面包屑（所有模式常驻，内容由 App 动态填充） === */\\n    #breadcrumb {\\n      position: absolute;\\n      left: 50%;\\n      bottom: 22px;\\n      transform: translateX(-50%);\\n      z-index: 6;\\n      display: flex;\\n      gap: 8px;\\n      align-items: center;\\n    }\\n\\n    .crumb-pill {\\n      padding: 3px 14px;\\n      border: 1px solid rgba(120, 180, 220, 0.4);\\n      border-radius: 3px;\\n      color: #bfe0f2;\\n      font-size: 13px;\\n      background: rgba(10, 24, 38, 0.55);\\n      user-select: none;\\n    }\\n\\n    .crumb-sep {\\n      color: #3d5a6e;\\n    }\\n\\n    /* === 模式控制 === */\\n    body[data-mode=\\\"china\\\"] .earth-only {\\n      display: none !important;\\n    }\\n\\n    body[data-mode=\\\"earth\\\"] .china-only {\\n      display: none !important;\\n    }\\n\\n    /* === 启动 loading 遮罩（CDN 拉 Three.js 时显示，App 启动后淡出） === */\\n    #app-loading {\\n      position: fixed; inset: 0;\\n      z-index: 100000;\\n      display: flex; flex-direction: column;\\n      align-items: center; justify-content: center;\\n      gap: 18px;\\n      /* background: radial-gradient(ellipse at 50% 45%, #05111f 0%, #020409 55%, #000 100%); */\\n      color: #a5c8ff;\\n      transition: opacity .4s ease;\\n    }\\n    #app-loading.hidden { opacity: 0; pointer-events: none; }\\n    #app-loading .spinner {\\n      width: 46px; height: 46px;\\n      border: 3px solid rgba(73, 176, 255, .18);\\n      border-top-color: #49b0ff;\\n      border-radius: 50%;\\n      animation: bjspin .9s linear infinite;\\n    }\\n    #app-loading .txt { font-size: 13px; letter-spacing: 4px; }\\n\\n    /* === 切换黑蒙层 === */\\n    #fusion-shroud {\\n      position: fixed;\\n      inset: 0;\\n      z-index: 99999;\\n      background: #000;\\n      opacity: 0;\\n      pointer-events: none;\\n      transition: opacity .3s ease;\\n    }\\n\\n    #fusion-shroud.active {\\n      opacity: 1;\\n    }\\n\\n    /* === 透明背景开关（由脚本顶部的 TRANSPARENT_BG 控制） === */\\n    html.transparent-bg,\\n    html.transparent-bg body,\\n    html.transparent-bg #earth-root,\\n    html.transparent-bg #china-holder {\\n      background: transparent !important;\\n    }\\n  </style>\\n</head>\\n<script>\\n/* ============================================================\\n   JeecgBoot 大屏视图联动驱动（高度内聚 · 单 IIFE）\\n   监听 3D 场景层级变化（全球 / 中国 / 省份），通过 window.JLink:\\n     · 互斥显隐\\\"全球\\\" / \\\"中国及省份\\\"组合\\n     · 同步标题（X销售运营大屏 · 实时驾驶舱）\\n     · 下钻到省时刷新组合内 7 个图表的省级仿真数据\\n   ============================================================ */\\n(function(){\\n  \'use strict\';\\n\\n  /* ---- 1. 组件 ID 常量（与大屏页面对齐）---- */\\n  var COMP = {\\n    TITLE:  \'1782269230310_997486\',\\n    GLOBAL: \'es-drager-1782724246158-1\',\\n    CHINA:  \'es-drager-1782722429243-1\',\\n    STATS:  \'1782269230311_305879\',\\n    LINE:   \'1782269230311_729434\',\\n    BAR:    \'1782269230312_205251\',\\n    PIE:    \'1782269230311_537352\',\\n    RING:   \'1782269230312_640892\',\\n    RANK:   \'1782269230311_284478\',\\n    LIST:   \'1782269230312_519981\'\\n  };\\n\\n  /* ---- 2. 省份全名 → 简称 ---- */\\n  var SHORT = {\\n    \'北京市\':\'北京\',\'上海市\':\'上海\',\'天津市\':\'天津\',\'重庆市\':\'重庆\',\\n    \'河北省\':\'河北\',\'山西省\':\'山西\',\'辽宁省\':\'辽宁\',\'吉林省\':\'吉林\',\\n    \'黑龙江省\':\'黑龙江\',\'江苏省\':\'江苏\',\'浙江省\':\'浙江\',\'安徽省\':\'安徽\',\\n    \'福建省\':\'福建\',\'江西省\':\'江西\',\'山东省\':\'山东\',\'河南省\':\'河南\',\\n    \'湖北省\':\'湖北\',\'湖南省\':\'湖南\',\'广东省\':\'广东\',\'海南省\':\'海南\',\\n    \'四川省\':\'四川\',\'贵州省\':\'贵州\',\'云南省\':\'云南\',\'陕西省\':\'陕西\',\\n    \'甘肃省\':\'甘肃\',\'青海省\':\'青海\',\'台湾省\':\'台湾\',\\n    \'内蒙古自治区\':\'内蒙古\',\'广西壮族自治区\':\'广西\',\'西藏自治区\':\'西藏\',\\n    \'宁夏回族自治区\':\'宁夏\',\'新疆维吾尔自治区\':\'新疆\',\\n    \'香港特别行政区\':\'香港\',\'澳门特别行政区\':\'澳门\'\\n  };\\n  function toShort(full){\\n    if (!full) return \'\';\\n    if (SHORT[full]) return SHORT[full];\\n    return full.replace(/省$|市$|特别行政区$|维吾尔自治区$|壮族自治区$|回族自治区$|自治区$/, \'\');\\n  }\\n\\n  /* ---- 3. 省级仿真数据（按省名 hash 种子，同省稳定）---- */\\n  function hashStr(s){\\n    var h = 0;\\n    for (var i=0;i<s.length;i++) h = ((h*31) + s.charCodeAt(i)) >>> 0;\\n    return h || 1;\\n  }\\n  function seedRand(seed){\\n    var s = seed;\\n    return function(){\\n      s = (s * 9301 + 49297) % 233280;\\n      return s / 233280;\\n    };\\n  }\\n  function intIn(lo, hi, r){ return Math.floor(lo + r() * (hi - lo + 1)); }\\n  function pct(r){ return (5 + r()*30).toFixed(1) + \'%\'; }\\n\\n  function buildStats(r){\\n    return [\\n      {id:\'1\', name:\'总销售额(万元)\', value: intIn(8000, 95000, r), suffix:\'万\', compareLabel:\'环比\', compareValue:\'+\'+pct(r), compareState:\'1\'},\\n      {id:\'2\', name:\'订单总数\',       value: intIn(20000, 280000, r), suffix:\'单\', compareLabel:\'同比\', compareValue:\'+\'+pct(r), compareState:\'1\'},\\n      {id:\'3\', name:\'活跃用户\',       value: intIn(3000, 45000, r),  suffix:\'人\', compareLabel:\'同比\', compareValue:\'+\'+pct(r), compareState:\'1\'},\\n      {id:\'4\', name:\'客单价(元)\',     value: intIn(120, 480, r),     suffix:\'元\', compareLabel:\'环比\', compareValue:\'+\'+pct(r), compareState:\'1\'},\\n      {id:\'5\', name:\'转化率\',         value: +(1 + r()*6).toFixed(2), suffix:\'%\', compareLabel:\'环比\', compareValue:\'+\'+pct(r), compareState:\'1\'},\\n      {id:\'6\', name:\'好评率\',         value: +(92 + r()*7).toFixed(1), suffix:\'%\', compareLabel:\'同比\', compareValue:\'+\'+pct(r), compareState:\'1\'}\\n    ];\\n  }\\n  function buildLine(r){\\n    var out = [];\\n    for (var i=1;i<=12;i++) out.push({name: i+\'月\', value: intIn(1500, 8500, r)});\\n    return out;\\n  }\\n  function buildBar(r){\\n    return [\\n      {name:\'待付款\', value: intIn(2000, 18000, r)},\\n      {name:\'已付款\', value: intIn(10000, 42000, r)},\\n      {name:\'已发货\', value: intIn(8000, 35000, r)},\\n      {name:\'已签收\', value: intIn(6000, 30000, r)},\\n      {name:\'已退款\', value: intIn(300, 2800, r)}\\n    ];\\n  }\\n  function buildPie(r){\\n    var cats = [\'服装鞋包\',\'食品生鲜\',\'美妆个护\',\'3C数码\',\'家居家电\',\'母婴玩具\'];\\n    return cats.map(function(n){ return {name:n, value: intIn(3000, 18000, r)}; });\\n  }\\n  function buildRing(r){\\n    var ways = [\'微信支付\',\'支付宝\',\'银行卡\',\'现金/到付\'];\\n    return ways.map(function(n){ return {name:n, value: intIn(8000, 145000, r)}; });\\n  }\\n  function buildRank(name, r){\\n    var areas = [\'·市辖区\',\'·开发区\',\'·高新区\',\'·经开区\',\'·工业园\',\'·滨海新区\',\'·北部新区\',\'·南部新区\',\'·东部新城\',\'·西部新城\',\'·江北区\',\'·江南区\',\'·城东\'];\\n    var out = [];\\n    for (var k=0;k<areas.length;k++) out.push({name: name + areas[k], value: intIn(800, 9500, r)});\\n    return out.sort(function(a,b){ return b.value - a.value; });\\n  }\\n  function buildList(name, r){\\n    var surnames = [\'李\',\'王\',\'张\',\'刘\',\'陈\',\'杨\',\'黄\',\'赵\',\'吴\',\'周\',\'徐\',\'孙\',\'马\',\'朱\',\'胡\'];\\n    var out = [];\\n    for (var k=0;k<14;k++){\\n      var h = intIn(8, 22, r), m = intIn(0, 59, r), s = intIn(0, 59, r);\\n      out.push({\\n        user:    surnames[intIn(0, surnames.length-1, r)] + \'**\',\\n        province: name,\\n        amount:  \'¥\' + intIn(180, 8800, r),\\n        time:    (\'0\'+h).slice(-2)+\':\'+(\'0\'+m).slice(-2)+\':\'+(\'0\'+s).slice(-2)\\n      });\\n    }\\n    return out;\\n  }\\n  function buildProvinceData(name){\\n    var r = seedRand(hashStr(name));\\n    return {\\n      stats: buildStats(r),\\n      line:  buildLine(r),\\n      bar:   buildBar(r),\\n      pie:   buildPie(r),\\n      ring:  buildRing(r),\\n      rank:  buildRank(name, r),\\n      list:  buildList(name, r)\\n    };\\n  }\\n\\n  /* ---- 4. 派发动作（通过 window.JLink）---- */\\n  function JL(){ return (typeof window.JLink !== \'undefined\') ? window.JLink : null; }\\n  /* 模拟真实接口：每个图表独立随机延迟 500-1300ms，期间显示 loading 遮罩\\n     loading(id, ms) 自带超时自动关 → 与 setData 同步，正好\\\"loading 转完→数据出现\\\" */\\n  function mockDelay(){ return 500 + Math.floor(Math.random() * 800); }\\n  function simulateAsync(id, rows){\\n    var jl = JL(); if (!jl) return;\\n    var d = mockDelay();\\n    /* loading 是新增 API，低版本平台无此方法 → typeof 守卫优雅降级（仍保留延迟） */\\n    if (typeof jl.loading === \'function\') jl.loading(id, d);\\n    setTimeout(function(){ jl.setData(id, rows); }, d);\\n  }\\n  function setTitle(label){\\n    var jl = JL(); if (!jl) return;\\n    jl.setData(COMP.TITLE, [{ value: label + \'销售运营大屏 · 实时驾驶舱\' }]);\\n  }\\n  function applyGlobal(){\\n    var jl = JL(); if (!jl) return;\\n    jl.show(COMP.GLOBAL);\\n    jl.hide(COMP.CHINA);\\n    setTitle(\'全球\');\\n  }\\n  /* \\\"中国及省份\\\"组合内会被 setData 覆盖的 7 个目标 id —— 既是省级写入清单，也是回放清单 */\\n  var DIRTY_IDS = [COMP.STATS, COMP.LINE, COMP.BAR, COMP.PIE, COMP.RING, COMP.RANK, COMP.LIST];\\n  /* CHINA_DEFAULT 注入时由 inject_driver.py 从 page 配置静态读出 7 个组件的 chartData 编入：\\n     无需 JLink.get（父端 findCompById 不递归 JGroup.props.elements，子组件查不到） */\\n  var CHINA_DEFAULT = {\\\"1782269230311_305879\\\": [{\\\"id\\\": \\\"1\\\", \\\"name\\\": \\\"总销售额(万元)\\\", \\\"value\\\": 48620, \\\"suffix\\\": \\\"万\\\", \\\"compareLabel\\\": \\\"环比\\\", \\\"compareValue\\\": \\\"+12.5%\\\", \\\"compareState\\\": \\\"1\\\"}, {\\\"id\\\": \\\"2\\\", \\\"name\\\": \\\"订单总数\\\", \\\"value\\\": 286453, \\\"suffix\\\": \\\"单\\\", \\\"compareLabel\\\": \\\"同比\\\", \\\"compareValue\\\": \\\"+8.3%\\\", \\\"compareState\\\": \\\"1\\\"}, {\\\"id\\\": \\\"3\\\", \\\"name\\\": \\\"客户总数\\\", \\\"value\\\": 158730, \\\"suffix\\\": \\\"人\\\", \\\"compareLabel\\\": \\\"环比\\\", \\\"compareValue\\\": \\\"+5.2%\\\", \\\"compareState\\\": \\\"1\\\"}, {\\\"id\\\": \\\"4\\\", \\\"name\\\": \\\"复购率\\\", \\\"value\\\": 38.5, \\\"suffix\\\": \\\"%\\\", \\\"compareLabel\\\": \\\"环比\\\", \\\"compareValue\\\": \\\"+2.1%\\\", \\\"compareState\\\": \\\"1\\\"}, {\\\"id\\\": \\\"5\\\", \\\"name\\\": \\\"退款率\\\", \\\"value\\\": 2.8, \\\"suffix\\\": \\\"%\\\", \\\"compareLabel\\\": \\\"同比\\\", \\\"compareValue\\\": \\\"-0.6%\\\", \\\"compareState\\\": \\\"0\\\"}, {\\\"id\\\": \\\"6\\\", \\\"name\\\": \\\"活跃城市\\\", \\\"value\\\": 268, \\\"suffix\\\": \\\"个\\\", \\\"compareLabel\\\": \\\"环比\\\", \\\"compareValue\\\": \\\"+4.0%\\\", \\\"compareState\\\": \\\"1\\\"}], \\\"1782269230311_729434\\\": [{\\\"name\\\": \\\"1月\\\", \\\"value\\\": 3850}, {\\\"name\\\": \\\"2月\\\", \\\"value\\\": 3120}, {\\\"name\\\": \\\"3月\\\", \\\"value\\\": 4280}, {\\\"name\\\": \\\"4月\\\", \\\"value\\\": 3960}, {\\\"name\\\": \\\"5月\\\", \\\"value\\\": 4520}, {\\\"name\\\": \\\"6月\\\", \\\"value\\\": 4180}, {\\\"name\\\": \\\"7月\\\", \\\"value\\\": 4650}, {\\\"name\\\": \\\"8月\\\", \\\"value\\\": 4380}, {\\\"name\\\": \\\"9月\\\", \\\"value\\\": 4720}, {\\\"name\\\": \\\"10月\\\", \\\"value\\\": 5180}, {\\\"name\\\": \\\"11月\\\", \\\"value\\\": 4890}, {\\\"name\\\": \\\"12月\\\", \\\"value\\\": 5240}], \\\"1782269230312_205251\\\": [{\\\"name\\\": \\\"待付款\\\", \\\"value\\\": 18650}, {\\\"name\\\": \\\"已付款\\\", \\\"value\\\": 32480}, {\\\"name\\\": \\\"已发货\\\", \\\"value\\\": 45230}, {\\\"name\\\": \\\"已签收\\\", \\\"value\\\": 168320}, {\\\"name\\\": \\\"退款中\\\", \\\"value\\\": 8260}], \\\"1782269230311_537352\\\": [{\\\"name\\\": \\\"服装鞋包\\\", \\\"value\\\": 12480}, {\\\"name\\\": \\\"数码家电\\\", \\\"value\\\": 9820}, {\\\"name\\\": \\\"食品生鲜\\\", \\\"value\\\": 8650}, {\\\"name\\\": \\\"美妆护肤\\\", \\\"value\\\": 7320}, {\\\"name\\\": \\\"家居日用\\\", \\\"value\\\": 5980}, {\\\"name\\\": \\\"其他\\\", \\\"value\\\": 4370}], \\\"1782269230312_640892\\\": [{\\\"name\\\": \\\"微信支付\\\", \\\"value\\\": 138420}, {\\\"name\\\": \\\"支付宝\\\", \\\"value\\\": 95630}, {\\\"name\\\": \\\"银行卡\\\", \\\"value\\\": 38260}, {\\\"name\\\": \\\"信用卡\\\", \\\"value\\\": 14160}], \\\"1782269230311_284478\\\": [{\\\"name\\\": \\\"广东省\\\", \\\"value\\\": 8950}, {\\\"name\\\": \\\"江苏省\\\", \\\"value\\\": 7820}, {\\\"name\\\": \\\"山东省\\\", \\\"value\\\": 6780}, {\\\"name\\\": \\\"浙江省\\\", \\\"value\\\": 6420}, {\\\"name\\\": \\\"北京市\\\", \\\"value\\\": 5680}, {\\\"name\\\": \\\"上海市\\\", \\\"value\\\": 5380}, {\\\"name\\\": \\\"四川省\\\", \\\"value\\\": 4920}, {\\\"name\\\": \\\"河南省\\\", \\\"value\\\": 4580}, {\\\"name\\\": \\\"湖北省\\\", \\\"value\\\": 3980}, {\\\"name\\\": \\\"湖南省\\\", \\\"value\\\": 3620}, {\\\"name\\\": \\\"福建省\\\", \\\"value\\\": 3420}, {\\\"name\\\": \\\"河北省\\\", \\\"value\\\": 3180}, {\\\"name\\\": \\\"安徽省\\\", \\\"value\\\": 2980}], \\\"1782269230312_519981\\\": [{\\\"user\\\": \\\"李**\\\", \\\"province\\\": \\\"广东\\\", \\\"amount\\\": \\\"¥1280\\\", \\\"time\\\": \\\"13:42:18\\\"}, {\\\"user\\\": \\\"王**\\\", \\\"province\\\": \\\"江苏\\\", \\\"amount\\\": \\\"¥860\\\", \\\"time\\\": \\\"13:42:05\\\"}, {\\\"user\\\": \\\"张**\\\", \\\"province\\\": \\\"北京\\\", \\\"amount\\\": \\\"¥2380\\\", \\\"time\\\": \\\"13:41:52\\\"}, {\\\"user\\\": \\\"陈**\\\", \\\"province\\\": \\\"浙江\\\", \\\"amount\\\": \\\"¥520\\\", \\\"time\\\": \\\"13:41:38\\\"}, {\\\"user\\\": \\\"杨**\\\", \\\"province\\\": \\\"上海\\\", \\\"amount\\\": \\\"¥3680\\\", \\\"time\\\": \\\"13:41:21\\\"}, {\\\"user\\\": \\\"黄**\\\", \\\"province\\\": \\\"山东\\\", \\\"amount\\\": \\\"¥980\\\", \\\"time\\\": \\\"13:41:08\\\"}, {\\\"user\\\": \\\"赵**\\\", \\\"province\\\": \\\"四川\\\", \\\"amount\\\": \\\"¥1580\\\", \\\"time\\\": \\\"13:40:55\\\"}, {\\\"user\\\": \\\"周**\\\", \\\"province\\\": \\\"湖北\\\", \\\"amount\\\": \\\"¥420\\\", \\\"time\\\": \\\"13:40:42\\\"}, {\\\"user\\\": \\\"吴**\\\", \\\"province\\\": \\\"河南\\\", \\\"amount\\\": \\\"¥1980\\\", \\\"time\\\": \\\"13:40:31\\\"}, {\\\"user\\\": \\\"徐**\\\", \\\"province\\\": \\\"福建\\\", \\\"amount\\\": \\\"¥720\\\", \\\"time\\\": \\\"13:40:18\\\"}, {\\\"user\\\": \\\"孙**\\\", \\\"province\\\": \\\"湖南\\\", \\\"amount\\\": \\\"¥1380\\\", \\\"time\\\": \\\"13:40:05\\\"}, {\\\"user\\\": \\\"马**\\\", \\\"province\\\": \\\"河北\\\", \\\"amount\\\": \\\"¥560\\\", \\\"time\\\": \\\"13:39:48\\\"}, {\\\"user\\\": \\\"朱**\\\", \\\"province\\\": \\\"安徽\\\", \\\"amount\\\": \\\"¥2180\\\", \\\"time\\\": \\\"13:39:32\\\"}, {\\\"user\\\": \\\"胡**\\\", \\\"province\\\": \\\"陕西\\\", \\\"amount\\\": \\\"¥880\\\", \\\"time\\\": \\\"13:39:18\\\"}, {\\\"user\\\": \\\"郭**\\\", \\\"province\\\": \\\"辽宁\\\", \\\"amount\\\": \\\"¥1620\\\", \\\"time\\\": \\\"13:39:02\\\"}]};\\n  function pushChinaCache(){\\n    if (typeof CHINA_DEFAULT === \'undefined\') return;\\n    DIRTY_IDS.forEach(function(id){\\n      var rows = CHINA_DEFAULT[id];\\n      if (rows && rows.length) simulateAsync(id, rows);\\n    });\\n  }\\n  function applyCountry(){\\n    var jl = JL(); if (!jl) return;\\n    jl.hide(COMP.GLOBAL);\\n    jl.show(COMP.CHINA);\\n    setTitle(\'中国\');\\n    /* 直接 setData 回放注入时编入的中国默认数据 */\\n    pushChinaCache();\\n  }\\n  function applyProvince(shortName){\\n    var jl = JL(); if (!jl) return;\\n    jl.hide(COMP.GLOBAL);\\n    jl.show(COMP.CHINA);\\n    setTitle(shortName);\\n    var d = buildProvinceData(shortName);\\n    /* 7 个图表各自独立 loading + 延迟 setData，模拟并发接口请求 */\\n    simulateAsync(COMP.STATS, d.stats);\\n    simulateAsync(COMP.LINE,  d.line);\\n    simulateAsync(COMP.BAR,   d.bar);\\n    simulateAsync(COMP.PIE,   d.pie);\\n    simulateAsync(COMP.RING,  d.ring);\\n    simulateAsync(COMP.RANK,  d.rank);\\n    simulateAsync(COMP.LIST,  d.list);\\n  }\\n\\n  /* ---- 5. 状态检测 ---- */\\n  var prevView = \'\';\\n  function detect(){\\n    var mode = document.body.getAttribute(\'data-mode\') || \'earth\';\\n    if (mode === \'earth\') return [\'global\', \'\'];\\n    var t = document.getElementById(\'china-title\');\\n    var text = t ? (t.textContent || \'\').trim() : \'\';\\n    var head = text.split(\'·\')[0].trim();\\n    if (!head || head === \'中国\') return [\'china\', \'\'];\\n    return [\'province\', toShort(head)];\\n  }\\n  function apply(){\\n    var v = detect();\\n    var key = v[0] + \':\' + v[1];\\n    if (key === prevView) return;\\n    prevView = key;\\n    if (v[0] === \'global\')        applyGlobal();\\n    else if (v[0] === \'china\')    applyCountry();\\n    else                          applyProvince(v[1]);\\n  }\\n\\n  /* ---- 6. 启动 + 观察 ---- */\\n  function start(){\\n    if (!document.body) { setTimeout(start, 80); return; }\\n    var titleEl = document.getElementById(\'china-title\');\\n    if (!titleEl) { setTimeout(start, 120); return; }\\n    var mo = new MutationObserver(apply);\\n    mo.observe(document.body, { attributes: true, attributeFilter: [\'data-mode\'] });\\n    mo.observe(titleEl, { childList: true, characterData: true, subtree: true });\\n    apply();                    /* 初始派发 */\\n    setInterval(apply, 1500);   /* 兜底轮询防漏 */\\n  }\\n  if (document.readyState === \'loading\') {\\n    document.addEventListener(\'DOMContentLoaded\', start);\\n  } else {\\n    start();\\n  }\\n})();\\n</script>\\n\\n\\n<body data-mode=\\\"earth\\\">\\n\\n  <!-- 启动 loading：在 importmap 拉 Three.js 期间盖住整个屏幕，避免黑屏 -->\\n  <div id=\\\"app-loading\\\">\\n    <div class=\\\"spinner\\\"></div>\\n    <div class=\\\"txt\\\">正在努力加载中...</div>\\n  </div>\\n\\n  <!-- ============ 地球场景 ============ -->\\n  <div id=\\\"earth-root\\\" class=\\\"earth-only\\\">\\n    <div id=\\\"earth-holder\\\"></div>\\n    <div id=\\\"earth-labels\\\"></div>\\n  </div>\\n\\n  <!-- ============ 中国场景 ============ -->\\n  <div id=\\\"china-holder\\\" class=\\\"china-only\\\">\\n    <div id=\\\"china-labels\\\" class=\\\"china-labels\\\"></div>\\n    <div class=\\\"china-header\\\">\\n      <div class=\\\"title\\\" id=\\\"china-title\\\">中国 · 三维地图</div>\\n      <div class=\\\"sub-row\\\">\\n        <span class=\\\"pulse\\\"></span>\\n        <span class=\\\"sub\\\" id=\\\"china-sub\\\">34 省级行政区 · 点击区域下钻</span>\\n      </div>\\n    </div>\\n    <div class=\\\"china-back\\\" id=\\\"china-back\\\">\\n      <span class=\\\"arrow\\\">‹</span> <span id=\\\"china-back-label\\\">返回全球地图</span>\\n    </div>\\n    <div class=\\\"china-loading\\\" id=\\\"china-loading\\\">\\n      <div class=\\\"spinner\\\"></div>\\n      <div class=\\\"txt\\\" id=\\\"china-loading-txt\\\">加载地理数据…</div>\\n    </div>\\n  </div>\\n\\n  <!-- ============ 左侧功能开关（仅地球场景） ============ -->\\n  <div id=\\\"feature-toggles\\\" class=\\\"earth-only\\\"></div>\\n\\n  <!-- ============ 城市信息卡片（仅地球场景） ============ -->\\n  <div id=\\\"info-card\\\" class=\\\"earth-only\\\">\\n    <div class=\\\"card-head\\\">\\n      <div class=\\\"card-head-titles\\\">\\n        <span class=\\\"card-title\\\">标题内容</span>\\n        <span class=\\\"card-title-en\\\">TITLE CONTENT</span>\\n      </div>\\n      <span class=\\\"card-close\\\" id=\\\"card-close\\\">\\n        关闭 <span class=\\\"card-close-x\\\">×</span>\\n      </span>\\n    </div>\\n    <div class=\\\"card-body\\\">\\n      <div class=\\\"card-status\\\">\\n        <div class=\\\"status-icon\\\">✓</div>\\n        <div class=\\\"status-text\\\">\\n          <div class=\\\"status-label\\\">在线</div>\\n          <div class=\\\"status-en\\\">ONLINE</div>\\n        </div>\\n      </div>\\n      <div class=\\\"card-row\\\">\\n        <span class=\\\"row-label\\\">事件名称</span>\\n        <span class=\\\"row-value\\\" id=\\\"card-city\\\">标题名称内容详情</span>\\n      </div>\\n      <div class=\\\"card-row\\\">\\n        <span class=\\\"row-label\\\">发生时间</span>\\n        <span class=\\\"row-value\\\">2024.03.18</span>\\n      </div>\\n      <div class=\\\"card-row\\\">\\n        <span class=\\\"row-label\\\">处理速度</span>\\n        <span class=\\\"row-value progress\\\">\\n          <span class=\\\"progress-track\\\"><span class=\\\"progress-fill\\\"></span></span>\\n          32%\\n        </span>\\n      </div>\\n    </div>\\n  </div>\\n\\n  <!-- ============ 面包屑（跨场景常驻） ============ -->\\n  <div id=\\\"breadcrumb\\\"></div>\\n\\n\\n  <!-- ============ Three.js r130 via importmap ============ -->\\n  <script type=\\\"importmap\\\">\\n  {\\n    \\\"imports\\\": {\\n      \\\"three\\\": \\\"https://unpkg.com/three@0.130.0/build/three.module.js\\\",\\n      \\\"three/addons/\\\": \\\"https://unpkg.com/three@0.130.0/examples/jsm/\\\"\\n    }\\n  }\\n  </script>\\n\\n  <!-- ============ 全部逻辑：THREE 桥接 + 三个类 + 启动 ============ -->\\n  <script type=\\\"module\\\">\\n    import * as THREE_NS from \'three\';\\n    import { EffectComposer } from \'three/addons/postprocessing/EffectComposer.js\';\\n    import { RenderPass } from \'three/addons/postprocessing/RenderPass.js\';\\n    import { UnrealBloomPass } from \'three/addons/postprocessing/UnrealBloomPass.js\';\\n    import { ShaderPass } from \'three/addons/postprocessing/ShaderPass.js\';\\n    import { CopyShader } from \'three/addons/shaders/CopyShader.js\';\\n\\n    // ESM namespace is frozen; copy到 plain object 再补 addons，方便后面 THREE.XXX 直接用\\n    const THREE = Object.assign({}, THREE_NS, {\\n      EffectComposer, RenderPass, UnrealBloomPass, ShaderPass, CopyShader,\\n    });\\n\\n    // ============ 全局开关 ============\\n    // 透明背景开关：true=页面背景完全透明（body / 地球场景 / 中国场景），false=保留原黑色径向渐变\\n    const TRANSPARENT_BG = true;\\n    document.documentElement.classList.toggle(\'transparent-bg\', TRANSPARENT_BG);\\n\\n    // ChinaMap 用的主题色（仅 blue 一套）\\n    const PALETTES = {\\n      blue: {\\n        top: 0x0c3f96, side: 0x0a2356,\\n        edge: 0x49b0ff, glow: 0x3fd2ff,\\n        marker: 0x3fd2ff, city: 0xffae34,\\n        textWarm: 0xa5c8ff, bg: 0x081e46,\\n      },\\n    };\\n\\n    // ============================================================\\n    //  EarthScene：3D 地球场景\\n    //  - 构造：new EarthScene(holderDiv, labelLayerDiv, opts)\\n    //  - opts: { rotateSpeed, features, onChinaClick, onCityClick }\\n    // ============================================================\\n    class EarthScene {\\n      constructor(holder, labelLayer, opts = {}) {\\n        this.holder = holder;\\n        this.labelLayer = labelLayer;\\n        this.opts = opts;\\n        this._dead = false;\\n        this.R = 100;\\n        this.labelsVisible = true;\\n        this._init();\\n      }\\n\\n      destroy() {\\n        this._dead = true;\\n        if (this._raf) cancelAnimationFrame(this._raf);\\n        if (this._onResize) window.removeEventListener(\'resize\', this._onResize);\\n        if (this._renderer) {\\n          try { this._renderer.dispose(); } catch (e) { }\\n          if (this._renderer.domElement.parentNode) {\\n            this._renderer.domElement.parentNode.removeChild(this._renderer.domElement);\\n          }\\n        }\\n        if (this.labelLayer) this.labelLayer.innerHTML = \'\';\\n      }\\n\\n      flyToChina(durationMs, onDone) {\\n        if (this._dead || !this._camera || !this._hubV) { onDone && onDone(); return; }\\n        const camera = this._camera;\\n        // 目标：相机沿当前位置→hub 方向缩到 0.45 倍\\n        const startPos = camera.position.clone();\\n        // 把 hubV 从 spin 局部坐标转世界坐标后再算方向（spin 在转）\\n        const hubWorld = this._hubV.clone();\\n        if (this.hubGlow && this.hubGlow.parent) {\\n          this.hubGlow.parent.localToWorld(hubWorld);\\n        }\\n        const dir = startPos.clone().sub(hubWorld).normalize();\\n        const dist0 = startPos.distanceTo(hubWorld);\\n        const endPos = hubWorld.clone().add(dir.multiplyScalar(dist0 * 0.45));\\n        const t0 = performance.now();\\n        const tick = () => {\\n          if (this._dead) { onDone && onDone(); return; }\\n          const t = Math.min(1, (performance.now() - t0) / durationMs);\\n          // ease-in-out cubic\\n          const e = t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;\\n          camera.position.lerpVectors(startPos, endPos, e);\\n          camera.lookAt(0, 0, 0);\\n          // hub 辉光放大到 1.8x\\n          if (this.hubGlow) {\\n            const base = 44;\\n            const target = base * 1.8;\\n            const s = base + (target - base) * e;\\n            this.hubGlow.scale.set(s, s, 1);\\n          }\\n          if (t < 1) requestAnimationFrame(tick);\\n          else onDone && onDone();\\n        };\\n        tick();\\n      }\\n\\n      // 经纬度 → Three.js 三维向量（半径 r）\\n      llToVec(lat, lon, r) {\\n        const phi = (90 - lat) * Math.PI / 180;\\n        const theta = (lon + 180) * Math.PI / 180;\\n        return new THREE.Vector3(\\n          -r * Math.sin(phi) * Math.cos(theta),\\n          r * Math.cos(phi),\\n          r * Math.sin(phi) * Math.sin(theta),\\n        );\\n      }\\n\\n      // 两点之间构造一条抬起的二次贝塞尔弧线（飞线弧度由 lift 控制）\\n      makeArc(a, b, lift) {\\n        const mid = a.clone().add(b).multiplyScalar(0.5);\\n        const d = a.distanceTo(b);\\n        mid.normalize().multiplyScalar(this.R + d * lift);\\n        return new THREE.QuadraticBezierCurve3(a, mid, b);\\n      }\\n\\n      // 径向渐变光斑纹理（用于辉光、彗星、城市点）\\n      glowTexture(color, soft) {\\n        const s = 128;\\n        const c = document.createElement(\'canvas\');\\n        c.width = c.height = s;\\n        const g = c.getContext(\'2d\');\\n        const grd = g.createRadialGradient(s / 2, s / 2, 0, s / 2, s / 2, s / 2);\\n        grd.addColorStop(0, \'rgba(\' + color + \',1)\');\\n        grd.addColorStop(soft ? 0.25 : 0.18, \'rgba(\' + color + \',0.55)\');\\n        grd.addColorStop(1, \'rgba(\' + color + \',0)\');\\n        g.fillStyle = grd;\\n        g.fillRect(0, 0, s, s);\\n        const t = new THREE.Texture(c);\\n        t.needsUpdate = true;\\n        return t;\\n      }\\n\\n      // 城市标记：外环 + 实心点 + 外圈微光\\n      markerTexture(color) {\\n        const s = 128;\\n        const c = document.createElement(\'canvas\');\\n        c.width = c.height = s;\\n        const g = c.getContext(\'2d\');\\n        g.translate(s / 2, s / 2);\\n        g.strokeStyle = \'rgba(\' + color + \',0.95)\'; g.lineWidth = 7;\\n        g.beginPath(); g.arc(0, 0, 30, 0, Math.PI * 2); g.stroke();\\n        g.fillStyle = \'rgba(\' + color + \',1)\';\\n        g.beginPath(); g.arc(0, 0, 11, 0, Math.PI * 2); g.fill();\\n        g.strokeStyle = \'rgba(\' + color + \',0.4)\'; g.lineWidth = 3;\\n        g.beginPath(); g.arc(0, 0, 46, 0, Math.PI * 2); g.stroke();\\n        const t = new THREE.Texture(c);\\n        t.needsUpdate = true;\\n        return t;\\n      }\\n\\n      // 切换某个 group 的可见性。Component 收到用户的开关后调这个。\\n      // labels 是 DOM 不在 this.G 里，单独处理。\\n      setFeature(k, v) {\\n        if (this.G && this.G[k]) this.G[k].visible = v;\\n        if (k === \'labels\') this.labelsVisible = v;\\n      }\\n\\n      // 中国高亮：在一张 4096×2048 经纬度画布上绘制国土 + 省界\\n      paintChina() {\\n        const C = this._china;\\n        if (!C) return;\\n        const { cg, cW, cH, tex } = C;\\n        cg.clearRect(0, 0, cW, cH);\\n        const proj = (lon, lat) => [(lon + 180) / 360 * cW, (90 - lat) / 180 * cH];\\n        const ringPath = (ring) => {\\n          cg.beginPath();\\n          for (let i = 0; i < ring.length; i++) {\\n            const q = proj(ring[i][0], ring[i][1]);\\n            i ? cg.lineTo(q[0], q[1]) : cg.moveTo(q[0], q[1]);\\n          }\\n        };\\n        cg.lineJoin = \'round\'; cg.lineCap = \'round\';\\n        if (C.provinces && C.provinces.length) {\\n          const eachRing = (f, cb) => {\\n            const g = f.geometry; if (!g) return;\\n            if (g.type === \'Polygon\') g.coordinates.forEach(cb);\\n            else if (g.type === \'MultiPolygon\') g.coordinates.forEach(p => p.forEach(cb));\\n          };\\n          cg.fillStyle = \'rgba(40,122,186,0.42)\';\\n          C.provinces.forEach(f => eachRing(f, r => { ringPath(r); cg.closePath(); cg.fill(); }));\\n          cg.shadowColor = \'rgba(120,224,255,0.9)\'; cg.shadowBlur = 6;\\n          cg.strokeStyle = \'rgba(176,238,255,0.6)\'; cg.lineWidth = 1.7;\\n          C.provinces.forEach(f => eachRing(f, r => { ringPath(r); cg.stroke(); }));\\n          cg.shadowBlur = 10; cg.strokeStyle = \'rgba(150,232,255,0.32)\'; cg.lineWidth = 3.4;\\n          C.provinces.forEach(f => eachRing(f, r => { ringPath(r); cg.stroke(); }));\\n          cg.shadowBlur = 0;\\n        } else {\\n          const { chinaLL, hainan, taiwan } = C;\\n          [chinaLL, hainan, taiwan].forEach(r => {\\n            ringPath(r); cg.closePath();\\n            cg.fillStyle = \'rgba(48,140,205,0.5)\'; cg.fill();\\n          });\\n          cg.shadowColor = \'rgba(120,225,255,0.95)\'; cg.shadowBlur = 20;\\n          cg.strokeStyle = \'rgba(205,247,255,0.96)\'; cg.lineWidth = 5;\\n          [chinaLL, hainan, taiwan].forEach(r => { ringPath(r); cg.closePath(); cg.stroke(); });\\n          cg.shadowBlur = 0;\\n        }\\n        tex.needsUpdate = true;\\n      }\\n\\n      // ============================================================\\n      //  Three.js 主初始化（场景搭建 + 动画循环）\\n      //  原 Component.initThree() 整体迁移过来；this.holderRef.current → this.holder\\n      //  this.labelRef.current → this.labelLayer；this.props.rotateSpeed → this.opts.rotateSpeed\\n      // ============================================================\\n      _init() {\\n        const R = 100;           // 地球半径\\n        this.R = R;\\n        const holder = this.holder;\\n        const root = this.holder.parentNode;\\n        const W = root.clientWidth, H = root.clientHeight;\\n\\n        // ---------- 场景 / 相机 / 渲染器 ----------\\n        const scene = new THREE.Scene();\\n        const camera = new THREE.PerspectiveCamera(34, W / H, 1, 5000);\\n        camera.position.set(0, 74, 460);\\n        camera.lookAt(0, 0, 0);\\n        this._camera = camera;\\n\\n        const renderer = new THREE.WebGLRenderer({\\n          antialias: true,\\n          alpha: true,\\n          preserveDrawingBuffer: true,\\n        });\\n        this._renderer = renderer;\\n        renderer.setPixelRatio(Math.min(devicePixelRatio, 2));\\n        renderer.setSize(W, H);\\n        renderer.outputEncoding = THREE.sRGBEncoding;\\n        while (holder.firstChild) holder.removeChild(holder.firstChild);\\n        holder.appendChild(renderer.domElement);\\n\\n        this._renderOnce = () => { try { renderer.render(scene, camera); } catch (e) { } };\\n\\n        // 两层组：axial 控制地轴倾斜，spin 控制自转\\n        const axial = new THREE.Group(); axial.rotation.z = 0.40; scene.add(axial);\\n        const spin = new THREE.Group(); axial.add(spin);\\n\\n        // ---------- 星空 ----------\\n        const sg = new THREE.BufferGeometry();\\n        const N = 6500, sp = [];\\n        for (let i = 0; i < N; i++) {\\n          const r = 700 + Math.random() * 1600;\\n          const u = Math.random(), v = Math.random();\\n          const th = 2 * Math.PI * u, ph = Math.acos(2 * v - 1);\\n          sp.push(\\n            r * Math.sin(ph) * Math.cos(th),\\n            r * Math.sin(ph) * Math.sin(th),\\n            r * Math.cos(ph),\\n          );\\n        }\\n        sg.setAttribute(\'position\', new THREE.Float32BufferAttribute(sp, 3));\\n        const stars = new THREE.Points(sg, new THREE.PointsMaterial({\\n          color: 0xbcd4e6, size: 1.5, sizeAttenuation: true,\\n          transparent: true, opacity: 0.9,\\n        }));\\n        scene.add(stars);\\n        this.stars = stars;\\n\\n        // ---------- 地球：昼夜过渡 Shader ----------\\n        const loader = new THREE.TextureLoader();\\n        loader.crossOrigin = \'anonymous\';\\n        const RES = (window.__resources || {});\\n        const base = \'https://threejs.org/examples/textures/planets/\';\\n        const onTex = () => { if (this._renderOnce) this._renderOnce(); };\\n\\n        const dayInline = (document.getElementById(\'inline-tex-earth-day\')?.textContent || \'\').trim();\\n        const day = loader.load(dayInline || RES.earthDay || (base + \'earth_atmos_2048.jpg\'), onTex);\\n        day.encoding = THREE.sRGBEncoding;\\n        const night = loader.load(RES.earthNight || (base + \'earth_lights_2048.png\'), onTex);\\n        const cloudsInline = (document.getElementById(\'inline-tex-earth-clouds\')?.textContent || \'\').trim();\\n        const clouds = loader.load(cloudsInline || RES.earthClouds || (base + \'earth_clouds_1024.png\'), onTex);\\n\\n        // 太阳方向（影响昼夜混合）\\n        const sunDir = new THREE.Vector3(0.55, 0.18, 0.9).normalize();\\n\\n        const earthMat = new THREE.ShaderMaterial({\\n          uniforms: {\\n            dayTex: { value: day },\\n            nightTex: { value: night },\\n            sunDir: { value: sunDir },\\n          },\\n          vertexShader: `\\n            varying vec2 vUv; varying vec3 vWN; varying vec3 vWP;\\n            void main() {\\n              vUv = uv;\\n              vWN = normalize(mat3(modelMatrix) * normal);\\n              vec4 wp = modelMatrix * vec4(position, 1.0);\\n              vWP = wp.xyz;\\n              gl_Position = projectionMatrix * viewMatrix * wp;\\n            }`,\\n          fragmentShader: `\\n            uniform sampler2D dayTex;\\n            uniform sampler2D nightTex;\\n            uniform vec3 sunDir;\\n            varying vec2 vUv; varying vec3 vWN; varying vec3 vWP;\\n            void main() {\\n              float it = dot(normalize(vWN), normalize(sunDir));\\n              float m  = smoothstep(-0.18, 0.32, it);   // 昼夜过渡曲线\\n              vec3 d   = texture2D(dayTex, vUv).rgb;\\n              d        = mix(d, d * vec3(0.78, 0.95, 1.25), 0.35);  // 偏冷的色调\\n              vec3 n   = texture2D(nightTex, vUv).rgb;\\n              n        = n * vec3(1.3, 1.05, 0.6) * 1.5;            // 灯火偏暖\\n              vec3 col = mix(n, d, m);\\n              // 朝向相机的轻微补光，避免完全黑边\\n              float cam = clamp(dot(normalize(vWN), normalize(cameraPosition - vWP)), 0.0, 1.0);\\n              col += d * 0.10 * cam;\\n              col += vec3(0.015, 0.045, 0.085) * m;\\n              gl_FragColor = vec4(col, 1.0);\\n            }`,\\n        });\\n        const earth = new THREE.Mesh(new THREE.SphereGeometry(R, 72, 72), earthMat);\\n        spin.add(earth);\\n\\n        // 云层（独立旋转）\\n        const cloudMesh = new THREE.Mesh(\\n          new THREE.SphereGeometry(R * 1.012, 64, 64),\\n          new THREE.MeshBasicMaterial({\\n            map: clouds, transparent: true, opacity: 0.42,\\n            depthWrite: false, blending: THREE.NormalBlending,\\n          }),\\n        );\\n        spin.add(cloudMesh);\\n        this.cloudMesh = cloudMesh;\\n\\n        // ---------- 大气辉光（外层背面 + 内层正面菲涅尔） ----------\\n        const atmoMat = new THREE.ShaderMaterial({\\n          uniforms: { c: { value: new THREE.Color(0x3aa6ff) } },\\n          vertexShader: `\\n            varying vec3 vN; varying vec3 vP;\\n            void main() {\\n              vN = normalize(normalMatrix * normal);\\n              vec4 mv = modelViewMatrix * vec4(position, 1.0);\\n              vP = mv.xyz;\\n              gl_Position = projectionMatrix * mv;\\n            }`,\\n          fragmentShader: `\\n            uniform vec3 c; varying vec3 vN; varying vec3 vP;\\n            void main() {\\n              vec3 v = normalize(-vP);\\n              float f = pow(1.0 - abs(dot(vN, v)), 3.0);\\n              gl_FragColor = vec4(c, f * 0.9);\\n            }`,\\n          side: THREE.BackSide, transparent: true,\\n          blending: THREE.AdditiveBlending, depthWrite: false,\\n        });\\n        axial.add(new THREE.Mesh(new THREE.SphereGeometry(R * 1.18, 64, 64), atmoMat));\\n\\n        // 内层菲涅尔辉光\\n        const innerMat = new THREE.ShaderMaterial({\\n          uniforms: { c: { value: new THREE.Color(0x6cc3ff) } },\\n          vertexShader: `\\n            varying vec3 vN; varying vec3 vP;\\n            void main() {\\n              vN = normalize(normalMatrix * normal);\\n              vec4 mv = modelViewMatrix * vec4(position, 1.0);\\n              vP = mv.xyz;\\n              gl_Position = projectionMatrix * mv;\\n            }`,\\n          fragmentShader: `\\n            uniform vec3 c; varying vec3 vN; varying vec3 vP;\\n            void main() {\\n              vec3 v = normalize(-vP);\\n              float f = pow(1.0 - abs(dot(vN, v)), 4.5);\\n              gl_FragColor = vec4(c, f * 0.5);\\n            }`,\\n          side: THREE.FrontSide, transparent: true,\\n          blending: THREE.AdditiveBlending, depthWrite: false,\\n        });\\n        spin.add(new THREE.Mesh(new THREE.SphereGeometry(R * 1.005, 64, 64), innerMat));\\n\\n        // ---------- 城市数据 ----------\\n        //   hub = true 表示中心枢纽（浙江）\\n        //   grp = \'air\' / \'land\' / \'sea\' 决定它和枢纽间用什么线连接\\n        const cities = [\\n          { n: \'浙江\', lat: 29.1, lon: 120.0, hub: true },\\n\\n          // 欧洲 (飞线)\\n          { n: \'巴黎\', lat: 48.85, lon: 2.35, grp: \'air\' },\\n          { n: \'莫斯科\', lat: 55.75, lon: 37.6, grp: \'air\' },\\n          { n: \'柏林\', lat: 52.52, lon: 13.4, grp: \'air\' },\\n          { n: \'伦敦\', lat: 51.5, lon: -0.13, grp: \'air\' },\\n          { n: \'罗马\', lat: 41.9, lon: 12.5, grp: \'air\' },\\n          { n: \'马德里\', lat: 40.42, lon: -3.7, grp: \'air\' },\\n          { n: \'阿姆斯特丹\', lat: 52.37, lon: 4.9, grp: \'air\' },\\n          { n: \'阿布贾\', lat: 9.07, lon: 7.5, grp: \'air\' },\\n          { n: \'开罗\', lat: 30.0, lon: 31.2, grp: \'air\' },\\n\\n          // 亚洲陆运 / 飞线\\n          { n: \'德黑兰\', lat: 35.7, lon: 51.4, grp: \'land\' },\\n          { n: \'乌兰巴托\', lat: 47.9, lon: 106.9, grp: \'land\' },\\n          { n: \'东京\', lat: 35.7, lon: 139.7, grp: \'air\' },\\n          { n: \'新德里\', lat: 28.6, lon: 77.2, grp: \'land\' },\\n          { n: \'内比都\', lat: 19.7, lon: 96.1, grp: \'land\' },\\n          { n: \'曼谷\', lat: 13.75, lon: 100.5, grp: \'land\' },\\n\\n          // 东南亚 + 印度洋 + 南太平洋（海航线）\\n          { n: \'马尼拉\', lat: 14.6, lon: 121.0, grp: \'sea\' },\\n          { n: \'内罗毕\', lat: -1.29, lon: 36.8, grp: \'sea\' },\\n          { n: \'斯里兰卡\', lat: 6.9, lon: 79.8, grp: \'sea\' },\\n          { n: \'新加坡\', lat: 1.35, lon: 103.8, grp: \'sea\' },\\n          { n: \'珀斯\', lat: -31.95, lon: 115.86, grp: \'sea\' },\\n          { n: \'塔那那利佛\', lat: -18.9, lon: 47.5, grp: \'sea\' },\\n          { n: \'苏瓦\', lat: -18.1, lon: 178.4, grp: \'sea\' },\\n\\n          // 非洲 (飞线)\\n          { n: \'拉各斯\', lat: 6.45, lon: 3.4, grp: \'air\' },\\n          { n: \'约翰内斯堡\', lat: -26.2, lon: 28.05, grp: \'air\' },\\n          { n: \'金沙萨\', lat: -4.32, lon: 15.3, grp: \'air\' },\\n          { n: \'亚的斯亚贝巴\', lat: 9.03, lon: 38.74, grp: \'air\' },\\n          { n: \'达喀尔\', lat: 14.69, lon: -17.45, grp: \'air\' },\\n\\n          // 澳大利亚 (海航线)\\n          { n: \'悉尼\', lat: -33.87, lon: 151.21, grp: \'sea\' },\\n          { n: \'墨尔本\', lat: -37.81, lon: 144.96, grp: \'sea\' },\\n\\n          // 北美洲首都 (trans-Pacific 海航线)\\n          { n: \'华盛顿\', lat: 38.9, lon: -77.0, grp: \'sea\' },\\n          { n: \'渥太华\', lat: 45.4, lon: -75.7, grp: \'sea\' },\\n          { n: \'墨西哥城\', lat: 19.4, lon: -99.1, grp: \'sea\' },\\n          { n: \'洛杉矶\', lat: 34.05, lon: -118.24, grp: \'sea\' },\\n          { n: \'旧金山\', lat: 37.77, lon: -122.42, grp: \'sea\' },\\n\\n          // 南美洲首都 (trans-Pacific 海航线)\\n          { n: \'利马\', lat: -12.0, lon: -77.0, grp: \'sea\' },\\n          { n: \'圣地亚哥\', lat: -33.4, lon: -70.6, grp: \'sea\' },\\n          { n: \'布宜诺斯艾利斯\', lat: -34.6, lon: -58.4, grp: \'sea\' },\\n        ];\\n\\n        const hub = cities[0];\\n        const hubV = this.llToVec(hub.lat, hub.lon, R);\\n        this._hubV = hubV;\\n        // 让中国枢纽朝向相机（初始视角）\\n        spin.rotation.y = -Math.atan2(hubV.x, hubV.z) + 0.28;\\n\\n        // ---------- 枢纽太阳辉光 ----------\\n        const hubGlow = new THREE.Sprite(new THREE.SpriteMaterial({\\n          map: this.glowTexture(\'255,224,120\', true),\\n          transparent: true, blending: THREE.AdditiveBlending,\\n          depthWrite: false, depthTest: true,\\n        }));\\n        hubGlow.scale.set(46, 46, 1);\\n        hubGlow.position.copy(hubV.clone().multiplyScalar(1.02));\\n        spin.add(hubGlow);\\n        this.hubGlow = hubGlow;\\n\\n        // ---------- 城市标记 / 柱状图 / DOM 标签 ----------\\n        this.markers = [];\\n        this.labels = [];\\n        const bars = new THREE.Group();\\n        this.bars = bars;\\n        spin.add(bars);\\n        const labelLayer = this.labelLayer;\\n\\n        cities.forEach((c, i) => {\\n          const v = this.llToVec(c.lat, c.lon, R * 1.005);\\n          const col = c.hub ? \'255,224,120\'\\n            : (c.grp === \'sea\' ? \'90,220,255\' : \'150,230,255\');\\n\\n          // 城市标记（Sprite）\\n          const m = new THREE.Sprite(new THREE.SpriteMaterial({\\n            map: this.markerTexture(col),\\n            transparent: true, depthWrite: false, depthTest: true,\\n            blending: THREE.AdditiveBlending,\\n          }));\\n          m.scale.set(7.5, 7.5, 1);\\n          m.position.copy(v.clone().multiplyScalar(1.01));\\n          m.userData = { city: c.n };\\n          spin.add(m);\\n          this.markers.push(m);\\n\\n          // 圆柱 + 顶部光点（除枢纽外都加）\\n          if (!c.hub) {\\n            const h = 8 + (i % 5) * 4 + Math.random() * 8;\\n            const bar = new THREE.Mesh(\\n              new THREE.CylinderGeometry(0.55, 0.9, h, 8),\\n              new THREE.MeshBasicMaterial({\\n                color: 0xddf4ff, transparent: true, opacity: 0.85,\\n                blending: THREE.AdditiveBlending, depthWrite: false,\\n              }),\\n            );\\n            const up = v.clone().normalize();\\n            bar.position.copy(v.clone().add(up.clone().multiplyScalar(h / 2)));\\n            bar.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), up);\\n            bars.add(bar);\\n\\n            const tip = new THREE.Sprite(new THREE.SpriteMaterial({\\n              map: this.glowTexture(\'200,240,255\', true),\\n              transparent: true, blending: THREE.AdditiveBlending, depthWrite: false,\\n            }));\\n            tip.scale.set(7, 7, 1);\\n            tip.position.copy(v.clone().add(up.clone().multiplyScalar(h)));\\n            bars.add(tip);\\n          }\\n\\n          // DOM 标签（动画循环里投影到屏幕）\\n          const el = document.createElement(\'div\');\\n          el.style.cssText = \'position:absolute;transform:translate(-50%,-145%);\'\\n            + \'background:rgba(8,18,28,0.74);border:1px solid rgba(110,180,220,0.42);\'\\n            + \'color:#cfe4f2;font-size:11px;letter-spacing:1px;padding:2px 8px;\'\\n            + \'border-radius:3px;white-space:nowrap;pointer-events:none;text-shadow:0 1px 2px #000;\';\\n          el.textContent = c.n;\\n          if (c.hub) { el.style.color = \'#ffe79a\'; el.style.borderColor = \'rgba(255,210,90,0.6)\'; }\\n          labelLayer.appendChild(el);\\n          this.labels.push({ el, v: v.clone() });\\n        });\\n\\n        // ============================================================\\n        //  中国高亮（国土发光 + 省界 + 国界）\\n        // ============================================================\\n\\n        // 国界轮廓（顺时针，[lon, lat]）—— DataV 没加载到时的兜底\\n        const chinaLL = [\\n          [73.5, 39.5], [75, 40.5], [76.5, 41], [80, 42], [82, 45], [85, 47], [87, 48.5],\\n          [90, 47.8], [92, 45], [96, 43], [100, 42.5], [102, 42], [106, 42], [111, 43.5], [114, 45], [116, 46], [118, 48], [120, 49.5], [122, 51.5], [125, 53],\\n          [127, 50], [130, 48.5], [134, 48.3], [134.3, 47.3], [132, 45], [131, 44], [130.5, 42.8], [131, 42.5], [128, 42], [126, 41], [124, 40.2], [122.5, 40.8],\\n          [121, 39], [118.5, 39.2], [117.8, 38.7], [119, 38], [121, 37], [122.6, 37.4], [121.5, 36.1], [120, 35.5], [120.3, 34], [121, 32.5], [121.9, 31], [121, 30], [121.6, 29], [120, 28], [119, 26.5], [117, 24.5], [116, 23], [113.5, 22], [111, 21], [110, 21.2], [108.5, 21.3], [106.7, 21.6],\\n          [105, 23], [103.5, 22.6], [102, 22.4], [101.5, 22.4], [101, 21.2], [99.2, 22], [98.8, 24], [97.5, 25], [98.5, 26], [98.2, 27.5], [96.5, 29], [94, 28.5], [92, 27.8], [90, 28.2], [88, 27.3], [85, 28.6], [82, 30.4], [79.5, 32], [78.5, 33.5], [78, 35], [76, 36.5], [75, 37.5], [74.5, 38.5], [73.5, 39.5],\\n        ];\\n        const hainan = [[110.6, 20.1], [111, 19.2], [110.2, 18.5], [109.2, 18.4], [108.6, 19.3], [109.3, 20], [110.6, 20.1]];\\n        const taiwan = [[121.6, 25.3], [122, 24], [121.4, 22.5], [120.4, 22.4], [120, 23.5], [120.6, 25], [121.6, 25.3]];\\n\\n        const cW = 4096, cH = 2048;\\n        const cc = document.createElement(\'canvas\');\\n        cc.width = cW; cc.height = cH;\\n        const cg = cc.getContext(\'2d\');\\n\\n        const chinaTex = new THREE.Texture(cc);\\n        chinaTex.needsUpdate = true;\\n        chinaTex.anisotropy = 8;\\n        chinaTex.encoding = THREE.sRGBEncoding;\\n\\n        this._china = { cc, cg, cW, cH, chinaLL, hainan, taiwan, tex: chinaTex, provinces: null };\\n        this.paintChina();\\n\\n        const chinaShell = new THREE.Mesh(\\n          new THREE.SphereGeometry(R * 1.004, 96, 96),\\n          new THREE.MeshBasicMaterial({\\n            map: chinaTex, transparent: true,\\n            blending: THREE.AdditiveBlending, depthWrite: false,\\n          }),\\n        );\\n        spin.add(chinaShell);\\n        this._chinaShell = chinaShell;\\n\\n        // 异步拉真省界（DataV GeoAtlas），到了之后重画\\n        fetch((window.__resources && window.__resources.provinceData)\\n          || \'https://geo.datav.aliyun.com/areas_v3/bound/100000_full.json\')\\n          .then(r => r.json())\\n          .then(j => {\\n            if (this._dead || !this._china) return;\\n            this._china.provinces = (j && j.features) || [];\\n            this.paintChina();\\n            if (this._renderOnce) this._renderOnce();\\n          })\\n          .catch(() => { });\\n\\n        // ============================================================\\n        //  飞线 / 陆运线 / 海航线\\n        // ============================================================\\n        const arcs = new THREE.Group(); this.arcs = arcs; spin.add(arcs);\\n        const land = new THREE.Group(); this.land = land; spin.add(land);\\n        const sea = new THREE.Group(); this.sea = sea; spin.add(sea);\\n        const comets = new THREE.Group(); this.comets = comets; spin.add(comets);\\n        this._comets = [];\\n\\n        // 通用：把一条曲线采样成 Line 加进组\\n        const addLine = (curve, grp, color, op, dashed) => {\\n          const pts = curve.getPoints(80);\\n          const g = new THREE.BufferGeometry().setFromPoints(pts);\\n          const mat = dashed\\n            ? new THREE.LineDashedMaterial({\\n              color, transparent: true, opacity: op,\\n              dashSize: 2.4, gapSize: 2.4,\\n              blending: THREE.AdditiveBlending, depthWrite: false,\\n            })\\n            : new THREE.LineBasicMaterial({\\n              color, transparent: true, opacity: op,\\n              blending: THREE.AdditiveBlending, depthWrite: false,\\n            });\\n          const line = new THREE.Line(g, mat);\\n          if (dashed) line.computeLineDistances();\\n          grp.add(line);\\n          return curve;\\n        };\\n\\n        // 飞线 / 陆运线（贝塞尔弧）\\n        const airColors = [0xffb066, 0xffd28a, 0xcfe8ff];\\n        cities.forEach((c, i) => {\\n          if (c.hub) return;\\n          const v = this.llToVec(c.lat, c.lon, R);\\n\\n          if (c.grp === \'air\') {\\n            const curve = this.makeArc(hubV, v, 0.5);\\n            const col = airColors[i % airColors.length];\\n            // 半透明发光管 + 一条线\\n            const tube = new THREE.Mesh(\\n              new THREE.TubeGeometry(curve, 84, 0.42, 8, false),\\n              new THREE.MeshBasicMaterial({\\n                color: col, transparent: true, opacity: 0.28,\\n                blending: THREE.AdditiveBlending, depthWrite: false,\\n              }),\\n            );\\n            arcs.add(tube);\\n            addLine(curve, arcs, col, 0.32, false);\\n            this._comets.push({ curve, t: Math.random(), air: true, grp: \'arcs\', col: new THREE.Color(col) });\\n          } else if (c.grp === \'land\') {\\n            addLine(this.makeArc(hubV, v, 0.10), land, 0xbfe0ff, 0.42, false);\\n            this._comets.push({ curve: this.makeArc(hubV, v, 0.10), t: Math.random(), small: true, grp: \'land\' });\\n          }\\n        });\\n\\n        // 海航线：按真实海上走廊布点，避免连线穿陆地\\n        // 每条值是 [lon, lat] 路径点\\n        const seaRoutes = {\\n          \'马尼拉\': [[120, 29], [123, 25.5], [122, 21], [120.5, 18], [119.6, 16], [120.6, 14.7], [121, 14.6]],\\n          \'新加坡\': [[120, 29], [123, 25.5], [121, 21], [118, 17], [114, 12], [110, 7.5], [107, 5], [105, 3], [104, 2], [103.8, 1.35]],\\n          \'斯里兰卡\': [[120, 29], [123, 25.5], [121, 21], [118, 17], [114, 12], [110, 7.5], [106, 4], [103, 2], [100, 3], [97, 5], [93, 6], [88, 7], [84, 7], [81, 7], [79.8, 6.9]],\\n          \'珀斯\': [[120, 29], [123, 25.5], [121, 21], [118, 17], [114, 12], [110, 7.5], [108, 4], [107, 0], [106, -4], [107, -9], [110, -16], [112.5, -23], [114, -28], [115.86, -31.95]],\\n          \'塔那那利佛\': [[120, 29], [123, 25.5], [121, 21], [118, 17], [114, 12], [110, 7.5], [106, 4], [103, 2], [99, 2], [93, 2], [85, 0], [77, -2], [68, -5], [59, -9], [51, -14], [48, -17], [47.5, -18.9]],\\n          \'内罗毕\': [[120, 29], [123, 25.5], [121, 21], [118, 17], [114, 12], [110, 7.5], [106, 4], [103, 2], [99, 2], [92, 1], [82, 0], [71, -1], [60, -2.5], [50, -3.2], [43, -3.8], [40, -4], [36.8, -1.29]],\\n          \'苏瓦\': [[120, 29], [126, 27], [133, 23], [140, 19], [148, 14], [157, 7], [166, -2], [173, -10], [178.4, -18.1]],\\n          \'悉尼\': [[120, 29], [123, 25], [122, 20], [125, 14], [129, 8], [133, 1], [137, -6], [142, -13], [148, -21], [152, -28], [152.5, -33], [151.21, -33.87]],\\n          \'墨尔本\': [[120, 29], [123, 25], [122, 20], [125, 14], [129, 8], [133, 1], [137, -6], [142, -13], [148, -21], [151, -29], [150, -36], [146, -38.5], [144.96, -37.81]],\\n\\n          // 北美洲: 出东海 → 北太平洋 → 北美西岸 → 巴拿马 → 东岸\\n          \'墨西哥城\': [[122, 30], [128, 33], [140, 36], [155, 37], [170, 36], [-175, 34], [-160, 30], [-145, 26], [-130, 22], [-118, 18], [-106, 16], [-99.1, 19.4]],\\n          \'洛杉矶\': [[122, 30], [128, 34], [140, 38], [155, 40], [170, 41], [-178, 40], [-165, 38], [-150, 36], [-135, 35], [-124, 34], [-119, 33.5], [-118.24, 34.05]],\\n          \'旧金山\': [[122, 30], [128, 34], [140, 39], [155, 42], [170, 44], [-178, 44], [-165, 43], [-150, 42], [-138, 41], [-127, 39], [-123, 37.8], [-122.42, 37.77]],\\n          \'华盛顿\': [[122, 30], [128, 33], [140, 36], [155, 37], [170, 36], [-175, 34], [-160, 30], [-145, 25], [-130, 20], [-118, 15], [-108, 11], [-101, 9], [-95, 9], [-90, 9.5], [-83, 9], [-80, 12], [-78, 20], [-75, 30], [-75.5, 37], [-77, 38.9]],\\n          \'渥太华\': [[122, 30], [128, 33], [140, 36], [155, 38], [170, 38], [-175, 37], [-160, 34], [-145, 29], [-130, 24], [-118, 18], [-108, 12], [-101, 9], [-95, 9], [-90, 9.5], [-83, 9], [-80, 12], [-78, 22], [-74, 32], [-70, 40], [-71, 44], [-75.7, 45.4]],\\n\\n          // 南美洲: 出东海 → 南太平洋 → 南美西岸\\n          \'利马\': [[120, 29], [124, 22], [133, 12], [145, 2], [160, -6], [178, -12], [-170, -14], [-150, -15], [-130, -14], [-110, -13], [-92, -12.5], [-82, -12], [-77, -12]],\\n          \'圣地亚哥\': [[120, 29], [124, 22], [133, 12], [145, 2], [160, -6], [178, -12], [-170, -16], [-150, -19], [-130, -22], [-110, -25], [-92, -29], [-80, -32], [-72, -33.4], [-70.6, -33.4]],\\n          \'布宜诺斯艾利斯\': [[120, 29], [124, 22], [133, 12], [145, 2], [160, -6], [178, -12], [-170, -16], [-150, -19], [-130, -22], [-110, -26], [-92, -32], [-80, -38], [-73, -44], [-66, -50], [-62, -50], [-58, -44], [-57, -38], [-58.4, -34.6]],\\n        };\\n\\n        // 一组路径点 → Catmull-Rom 曲线 → 投到球面 → 虚线 + 彗星轨道\\n        const buildSeaLane = (wps) => {\\n          const v3 = wps.map(p => this.llToVec(p[1], p[0], R));\\n          const curve = new THREE.CatmullRomCurve3(v3, false, \'catmullrom\', 0.4);\\n          const N = Math.max(80, wps.length * 18);\\n          const pts = curve.getPoints(N).map(p => p.clone().normalize().multiplyScalar(R * 1.004));\\n          const g = new THREE.BufferGeometry().setFromPoints(pts);\\n          const line = new THREE.Line(g, new THREE.LineDashedMaterial({\\n            color: 0x4fd2ff, transparent: true, opacity: 0.6,\\n            dashSize: 2.2, gapSize: 2.0,\\n            blending: THREE.AdditiveBlending, depthWrite: false,\\n          }));\\n          line.computeLineDistances();\\n          sea.add(line);\\n          // 用投到球面后的点重新建一条曲线给彗星轨迹\\n          const cv = new THREE.CatmullRomCurve3(pts, false, \'catmullrom\', 0.0);\\n          this._comets.push({ curve: cv, t: Math.random(), sea: true, grp: \'sea\', col: new THREE.Color(0x7fe6ff) });\\n        };\\n        cities.forEach(c => { if (c.grp === \'sea\' && seaRoutes[c.n]) buildSeaLane(seaRoutes[c.n]); });\\n\\n        // ============================================================\\n        //  彗星粒子（每条线由 CN 个点拼成头亮尾淡的流动效果）\\n        // ============================================================\\n        const CN = 20;\\n        const NP = this._comets.length * CN;\\n        const cpos = new Float32Array(NP * 3);\\n        const csize = new Float32Array(NP);\\n        const calpha = new Float32Array(NP);\\n        const ccol = new Float32Array(NP * 3);\\n\\n        const cgeo = new THREE.BufferGeometry();\\n        cgeo.setAttribute(\'position\', new THREE.BufferAttribute(cpos, 3));\\n        cgeo.setAttribute(\'aSize\', new THREE.BufferAttribute(csize, 1));\\n        cgeo.setAttribute(\'aAlpha\', new THREE.BufferAttribute(calpha, 1));\\n        cgeo.setAttribute(\'aColor\', new THREE.BufferAttribute(ccol, 3));\\n\\n        const cmat = new THREE.ShaderMaterial({\\n          uniforms: {\\n            tex: { value: this.glowTexture(\'255,250,235\', true) },\\n            scale: { value: H },\\n          },\\n          vertexShader: `\\n            attribute float aSize;\\n            attribute float aAlpha;\\n            attribute vec3  aColor;\\n            varying float vA;\\n            varying vec3  vC;\\n            uniform float scale;\\n            void main() {\\n              vA = aAlpha;\\n              vC = aColor;\\n              vec4 mv = modelViewMatrix * vec4(position, 1.0);\\n              gl_PointSize = aSize * (scale / -mv.z);\\n              gl_Position  = projectionMatrix * mv;\\n            }`,\\n          fragmentShader: `\\n            uniform sampler2D tex;\\n            varying float vA;\\n            varying vec3  vC;\\n            void main() {\\n              vec4 t = texture2D(tex, gl_PointCoord);\\n              gl_FragColor = vec4(vC, 1.0) * t.a * vA;\\n            }`,\\n          transparent: true, blending: THREE.AdditiveBlending,\\n          depthWrite: false, depthTest: true,\\n        });\\n        const cpts = new THREE.Points(cgeo, cmat);\\n        comets.add(cpts);\\n        this._cgeo = cgeo;\\n        this._CN = CN;\\n\\n        // ============================================================\\n        //  粒子光环 + 卫星\\n        // ============================================================\\n        const halo = new THREE.Group();\\n        this.halo = halo;\\n        scene.add(halo);\\n\\n        // 赤道平面的粒子环\\n        const ringR = R * 1.62, RP = 2200, rpos = [];\\n        for (let i = 0; i < RP; i++) {\\n          const a = Math.random() * Math.PI * 2;\\n          const rr = ringR + (Math.random() - 0.5) * 10;\\n          rpos.push(Math.cos(a) * rr, (Math.random() - 0.5) * 2.2, Math.sin(a) * rr);\\n        }\\n        const rg = new THREE.BufferGeometry();\\n        rg.setAttribute(\'position\', new THREE.Float32BufferAttribute(rpos, 3));\\n        const ringPts = new THREE.Points(rg, new THREE.PointsMaterial({\\n          color: 0x9fd0ff, size: 1.7, transparent: true, opacity: 0.7,\\n          blending: THREE.AdditiveBlending, depthWrite: false,\\n        }));\\n        halo.add(ringPts);\\n        this.ringPts = ringPts;\\n\\n        // 两条细实线环（内外两层）\\n        [ringR, ringR * 1.16].forEach((rad, idx) => {\\n          const seg = 256;\\n          const lineRing = new THREE.LineLoop(\\n            new THREE.BufferGeometry().setFromPoints(\\n              Array.from({ length: seg }, (__, i) => {\\n                const a = i / seg * Math.PI * 2;\\n                return new THREE.Vector3(Math.cos(a) * rad, 0, Math.sin(a) * rad);\\n              }),\\n            ),\\n            new THREE.LineBasicMaterial({\\n              color: 0x6fa8d6, transparent: true,\\n              opacity: idx ? 0.18 : 0.32,\\n              blending: THREE.AdditiveBlending, depthWrite: false,\\n            }),\\n          );\\n          halo.add(lineRing);\\n        });\\n\\n        // 卫星（机身 + 两片太阳能板）\\n        const sat = new THREE.Group();\\n        const body = new THREE.Mesh(\\n          new THREE.BoxGeometry(3, 2.4, 2.4),\\n          new THREE.MeshBasicMaterial({ color: 0xdfe9f0 }),\\n        );\\n        const panelMat = new THREE.MeshBasicMaterial({\\n          color: 0x2a6fb0, transparent: true, opacity: 0.85, side: THREE.DoubleSide,\\n        });\\n        const p1 = new THREE.Mesh(new THREE.BoxGeometry(7, 0.2, 3), panelMat); p1.position.x = 5.5;\\n        const p2 = new THREE.Mesh(new THREE.BoxGeometry(7, 0.2, 3), panelMat); p2.position.x = -5.5;\\n        sat.add(body, p1, p2);\\n        halo.add(sat);\\n        this.sat = sat;\\n        this.satR = ringR * 1.16;\\n\\n        // ============================================================\\n        //  交互：鼠标拖拽旋转 + 点击拾取\\n        // ============================================================\\n        this.G = { bars, arcs, comets, land, sea, halo };\\n        if (this.opts.features) {\\n          Object.keys(this.opts.features).forEach(k => this.setFeature(k, this.opts.features[k]));\\n        }\\n\\n        const raycaster = new THREE.Raycaster();\\n        let dragging = false, lastX = 0, lastY = 0, moved = 0;\\n        this.idleFrames = 0;\\n\\n        const down = (e) => {\\n          dragging = true; moved = 0;\\n          const p = e.touches ? e.touches[0] : e;\\n          lastX = p.clientX; lastY = p.clientY;\\n          root.style.cursor = \'grabbing\';\\n        };\\n        const move = (e) => {\\n          if (!dragging) return;\\n          const p = e.touches ? e.touches[0] : e;\\n          const dx = p.clientX - lastX, dy = p.clientY - lastY;\\n          lastX = p.clientX; lastY = p.clientY;\\n          moved += Math.abs(dx) + Math.abs(dy);\\n          spin.rotation.y += dx * 0.005;\\n          axial.rotation.x = Math.max(-0.5, Math.min(0.5, axial.rotation.x + dy * 0.003));\\n          this.idleFrames = 0;\\n        };\\n        const up = (e) => {\\n          dragging = false;\\n          root.style.cursor = \'grab\';\\n          // 拖动距离很小时当作点击 → 先查中国国土，再 fallback 拾取城市标记\\n          if (moved < 5) {\\n            const rect = renderer.domElement.getBoundingClientRect();\\n            const p = e.changedTouches ? e.changedTouches[0] : e;\\n            const mx = ((p.clientX - rect.left) / rect.width) * 2 - 1;\\n            const my = -((p.clientY - rect.top) / rect.height) * 2 + 1;\\n            raycaster.setFromCamera({ x: mx, y: my }, camera);\\n\\n            // 1) 优先：是否点中中国国土？\\n            if (this._chinaShell) {\\n              const hits = raycaster.intersectObject(this._chinaShell, false);\\n              if (hits.length && hits[0].uv) {\\n                const uv = hits[0].uv;\\n                const C = this._china;\\n                const px = Math.floor(uv.x * C.cW);\\n                const py = Math.floor((1 - uv.y) * C.cH);\\n                const pixel = C.cg.getImageData(px, py, 1, 1).data;\\n                if (pixel[3] > 25) {                  // alpha > 0.1\\n                  if (this.opts.onChinaClick) {\\n                    this.opts.onChinaClick();\\n                    return;\\n                  }\\n                }\\n              }\\n            }\\n\\n            // 2) fallback：原城市标记拾取（保留信息卡片交互）\\n            const hit = raycaster.intersectObjects(this.markers, false);\\n            if (hit.length) {\\n              const name = hit[0].object.userData.city;\\n              if (this.opts.onCityClick) {\\n                this.opts.onCityClick(name, p, rect);\\n              }\\n            }\\n          }\\n        };\\n        root.addEventListener(\'mousedown\', down);\\n        root.addEventListener(\'mousemove\', move);\\n        window.addEventListener(\'mouseup\', up);\\n        root.addEventListener(\'touchstart\', down, { passive: true });\\n        root.addEventListener(\'touchmove\', move, { passive: true });\\n        window.addEventListener(\'touchend\', up);\\n\\n        this._onResize = () => {\\n          const w = root.clientWidth, h = root.clientHeight;\\n          camera.aspect = w / h;\\n          camera.updateProjectionMatrix();\\n          renderer.setSize(w, h);\\n        };\\n        window.addEventListener(\'resize\', this._onResize);\\n\\n        // ============================================================\\n        //  动画主循环\\n        // ============================================================\\n        const tmp = new THREE.Vector3();\\n        const camDir = new THREE.Vector3();\\n        let satA = 0;\\n\\n        const animate = () => {\\n          if (this._dead) return;\\n          this._raf = requestAnimationFrame(animate);\\n\\n          // 自转（90 帧无交互后自动旋转）\\n          const speed = (this.opts.rotateSpeed ?? 0.6);\\n          this.idleFrames++;\\n          if (this.idleFrames > 90) spin.rotation.y += 0.0011 * speed;\\n          cloudMesh.rotation.y += 0.0004;\\n          stars.rotation.y += 0.00006;\\n          halo.rotation.y += 0.0008;\\n\\n          // 枢纽辉光呼吸\\n          const ps = 44 + Math.sin(performance.now() * 0.0025) * 5;\\n          hubGlow.scale.set(ps, ps, 1);\\n\\n          // 卫星椭圆轨道\\n          satA += 0.004;\\n          const sr = this.satR;\\n          this.sat.position.set(Math.cos(satA) * sr, Math.sin(satA * 0.6) * sr * 0.18, Math.sin(satA) * sr);\\n          this.sat.rotation.y = -satA;\\n\\n          // ---------- 彗星头亮尾淡 ----------\\n          const pa = this._cgeo.attributes.position.array;\\n          const sa = this._cgeo.attributes.aSize.array;\\n          const al = this._cgeo.attributes.aAlpha.array;\\n          const co = this._cgeo.attributes.aColor.array;\\n          this._comets.forEach((cm, ci) => {\\n            const grp = cm.grp && this.G[cm.grp];\\n            const off = grp ? !grp.visible : false;\\n\\n            // 推进位置 t（不同类型不同速度）\\n            cm.t += (cm.air ? 0.0042 : cm.sea ? 0.0030 : 0.0035);\\n            if (cm.t > 1) cm.t -= 1;\\n\\n            const headSize = cm.air ? 5.5 : cm.sea ? 3.4 : 3.2;\\n            const r = cm.col ? cm.col.r : 0.78;\\n            const g = cm.col ? cm.col.g : 0.92;\\n            const b = cm.col ? cm.col.b : 1.0;\\n\\n            for (let j = 0; j < CN; j++) {\\n              const tt = cm.t - j * 0.011;        // 尾巴落后头部\\n              const base = ci * CN + j;\\n              const p3 = base * 3;\\n              if (off || tt < 0 || tt > 1) {\\n                al[base] = 0;\\n                pa[p3] = pa[p3 + 1] = pa[p3 + 2] = 99999;\\n                continue;\\n              }\\n              cm.curve.getPointAt(tt, tmp);\\n              pa[p3] = tmp.x; pa[p3 + 1] = tmp.y; pa[p3 + 2] = tmp.z;\\n              const f = 1 - j / CN;                 // 1 在头, 0 在尾\\n              sa[base] = headSize * (0.35 + 0.65 * f);\\n              al[base] = Math.pow(f, 1.6);\\n              co[p3] = r; co[p3 + 1] = g; co[p3 + 2] = b;\\n            }\\n          });\\n          this._cgeo.attributes.position.needsUpdate = true;\\n          this._cgeo.attributes.aSize.needsUpdate = true;\\n          this._cgeo.attributes.aAlpha.needsUpdate = true;\\n          this._cgeo.attributes.aColor.needsUpdate = true;\\n\\n          // ---------- DOM 标签投影 ----------\\n          camera.getWorldDirection(camDir);\\n          const w = renderer.domElement.clientWidth;\\n          const h = renderer.domElement.clientHeight;\\n          this.labels.forEach(L => {\\n            if (!this.labelsVisible) { L.el.style.display = \'none\'; return; }\\n            spin.localToWorld(tmp.copy(L.v));\\n            // 背向相机的隐藏\\n            const facing = tmp.clone().sub(camera.position).normalize().dot(tmp.clone().normalize());\\n            if (facing > -0.12) { L.el.style.display = \'none\'; return; }\\n            const proj = tmp.clone().project(camera);\\n            if (proj.z > 1) { L.el.style.display = \'none\'; return; }\\n            L.el.style.display = \'block\';\\n            L.el.style.left = ((proj.x * 0.5 + 0.5) * w) + \'px\';\\n            L.el.style.top = ((-proj.y * 0.5 + 0.5) * h) + \'px\';\\n          });\\n\\n          renderer.render(scene, camera);\\n        };\\n        animate();\\n      }\\n    }\\n\\n    // ============================================================\\n    //  ChinaMap：中国 3D 地图\\n    //  - 构造：new ChinaMap(host, refs, opts)\\n    //    refs = { labels, title, sub, back, backLabel, loading, loadingTxt }\\n    //  - opts.onLevelChange(level, regionName)\\n    // ============================================================\\n    class ChinaMap {\\n      constructor(host, refs, opts = {}) {\\n        this.host = host;\\n        this.refs = refs || {};\\n        this.opts = opts;\\n        this.labelsEl = this.refs.labels;\\n        this.loadingEl = this.refs.loading;\\n        this.titleEl = this.refs.title;\\n        this.subEl = this.refs.sub;\\n        this.backBtn = this.refs.back;\\n        this._alive = true;\\n        this._level = \'country\';\\n        this._provCache = {};\\n        // 注意：back 按钮的 click 由 Component.onChinaBackClick 通过模板 onclick 统一调度，\\n        // 这里不再 addEventListener(\'click\', () => this._back())，否则两个 handler 会同时跑，\\n        // 在省级点 _back 后 Component 看到的 _level 已经变成 country，被误判为\\\"回地球\\\"。\\n        if (this.opts.onLevelChange) this.opts.onLevelChange(\'country\', null);\\n        this._loadCountry();\\n      }\\n\\n      destroy() {\\n        this._alive = false;\\n        this._teardown();\\n      }\\n\\n      _loading(txt) {\\n        if (!this.loadingEl) return;\\n        this.loadingEl.style.display = \'flex\';\\n        const t = this.refs.loadingTxt || this.loadingEl.querySelector(\'[data-txt]\');\\n        if (t && txt) t.textContent = txt;\\n      }\\n      _hideLoading() { if (this.loadingEl) this.loadingEl.style.display = \'none\'; }\\n\\n      _toast(msg) {\\n        if (!this.host) return;\\n        const d = document.createElement(\'div\');\\n        d.textContent = msg;\\n        d.style.cssText = \'position:absolute;left:50%;top:52%;transform:translate(-50%,-50%);z-index:10;background:rgba(8,22,48,.94);border:1px solid #49b0ff;color:#eaf6ff;padding:12px 22px;border-radius:8px;font-size:14px;letter-spacing:1px;box-shadow:0 0 22px rgba(73,176,255,.5);\';\\n        this.host.appendChild(d);\\n        setTimeout(() => { d.style.transition = \'opacity .4s\'; d.style.opacity = \'0\'; setTimeout(() => d.remove(), 420); }, 1600);\\n      }\\n\\n      async _fetchGeo(adcode, urls) {\\n        for (const u of urls) {\\n          try {\\n            const r = await fetch(u);\\n            if (!r.ok) continue;\\n            const j = await r.json();\\n            if (j && j.features && j.features.length) return j;\\n          } catch (e) { }\\n        }\\n        return null;\\n      }\\n\\n      async _loadCountry() {\\n        if (this._geoCountry) { this._build(this._geoCountry, false); return; }\\n        this._loading(\'加载地理数据…\');\\n        const geo = await this._fetchGeo(\'100000\', [\\n          \'https://geo.datav.aliyun.com/areas_v3/bound/100000_full.json\',\\n          \'https://geo.datav.aliyun.com/areas_v2/bound/100000_full.json\',\\n        ]);\\n        if (!this._alive) return;\\n        if (!geo) { this._loading(\'地理数据加载失败，请刷新重试\'); return; }\\n        this._geoCountry = geo;\\n        try { this._build(geo, false); } catch (e) { console.error(e); }\\n        if (!this._three) this._hideLoading();\\n      }\\n\\n      async _drill(adcode, name) {\\n        if (this._level !== \'country\' || this._busy) return;\\n        this._busy = true;\\n        this._loading(\'加载 \' + (name || \'\') + \' 地图…\');\\n        let geo = this._provCache[adcode];\\n        if (!geo) {\\n          geo = await this._fetchGeo(adcode, [\\n            \'https://geo.datav.aliyun.com/areas_v3/bound/\' + adcode + \'_full.json\',\\n            \'https://geo.datav.aliyun.com/areas_v2/bound/\' + adcode + \'_full.json\',\\n          ]);\\n        }\\n        this._busy = false;\\n        if (!this._alive) return;\\n        if (!geo) { this._hideLoading(); this._toast(\'该地区暂无下一级地图数据\'); return; }\\n        this._provCache[adcode] = geo;\\n        this._curAdcode = adcode;\\n        this._curName = name;\\n        this._level = \'prov\';\\n        this._teardown();\\n        try { this._build(geo, true, name); } catch (e) { console.error(e); }\\n        if (!this._three) { this._hideLoading(); this._toast(\'地图渲染失败，请重试\'); }\\n        // 下钻成功 → 通知外部已进入省级\\n        if (this.opts.onLevelChange) this.opts.onLevelChange(\'prov\', name);\\n      }\\n\\n      _back() {\\n        if (this._level !== \'prov\' || this._busy) return;\\n        this._level = \'country\';\\n        this._curAdcode = null;\\n        this._teardown();\\n        if (this._geoCountry) { try { this._build(this._geoCountry, false); } catch (e) { console.error(e); } }\\n        if (!this._three) this._hideLoading();\\n        // 返回全国 → 通知外部\\n        if (this.opts.onLevelChange) this.opts.onLevelChange(\'country\', null);\\n      }\\n\\n      _palette() {\\n        return PALETTES.blue;\\n      }\\n\\n      _glowTex(hex) {\\n        const c = document.createElement(\'canvas\'); c.width = c.height = 128;\\n        const ctx = c.getContext(\'2d\');\\n        const r = (hex >> 16) & 255, gc = (hex >> 8) & 255, b = hex & 255;\\n        const rgba = (a) => `rgba(${r},${gc},${b},${a})`;\\n        const g = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);\\n        g.addColorStop(0, rgba(0.9));\\n        g.addColorStop(0.18, rgba(0.5));\\n        g.addColorStop(0.55, rgba(0.12));\\n        g.addColorStop(1, rgba(0));\\n        ctx.fillStyle = g; ctx.fillRect(0, 0, 128, 128);\\n        const t = new THREE.CanvasTexture(c); t.needsUpdate = true; return t;\\n      }\\n\\n      // soft gradient ring: faint inner, bright mid-band, faint outer — looks 3D, not flat\\n      _ringTex(hex) {\\n        const S = 256, c = document.createElement(\'canvas\'); c.width = c.height = S;\\n        const ctx = c.getContext(\'2d\');\\n        const r = (hex >> 16) & 255, gc = (hex >> 8) & 255, b = hex & 255;\\n        const rgba = (a) => `rgba(${r},${gc},${b},${a})`;\\n        const g = ctx.createRadialGradient(S / 2, S / 2, 0, S / 2, S / 2, S / 2);\\n        g.addColorStop(0.00, rgba(0));\\n        g.addColorStop(0.55, rgba(0));\\n        g.addColorStop(0.74, rgba(0.18));\\n        g.addColorStop(0.88, rgba(1));     // bright mid-band\\n        g.addColorStop(0.96, rgba(0.35));\\n        g.addColorStop(1.00, rgba(0));     // soft outer falloff\\n        ctx.fillStyle = g; ctx.beginPath(); ctx.arc(S / 2, S / 2, S / 2, 0, Math.PI * 2); ctx.fill();\\n        const t = new THREE.CanvasTexture(c); t.needsUpdate = true; return t;\\n      }\\n\\n      _build(geo, isProvince, regionName) {\\n        if (!this.host || !this._alive) return;\\n        const P = this._palette();\\n        const shorten = (n) => n.replace(/省|市|自治区|特别行政区|壮族|回族|维吾尔/g, \'\') || n;\\n        const districtLabel = (n) => n.replace(/(.)(市|特别行政区)$/, \'$1\') || n;\\n        const W = this.host.clientWidth, H = this.host.clientHeight;\\n\\n        const scene = new THREE.Scene();\\n        // 嵌入外部系统时背景透明，故去掉黑色雾（FogExp2 不支持 alpha，否则远处会被染黑）\\n        const camera = new THREE.PerspectiveCamera(45, W / H, 0.1, 4000);\\n        camera.position.set(0, 172, 96);\\n\\n        const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });\\n        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));\\n        renderer.setSize(W, H);\\n        renderer.setClearColor(0x000000, 0);\\n        renderer.toneMapping = THREE.ACESFilmicToneMapping;\\n        renderer.toneMappingExposure = 1.0;\\n        this.host.appendChild(renderer.domElement);\\n\\n        // ---- lightweight orbit controller + click/hover hooks ----\\n        const target = new THREE.Vector3(0, 2, 6);\\n        const autoRot = false;\\n        const off = camera.position.clone().sub(target);\\n        let radius = off.length();\\n        let theta = Math.atan2(off.x, off.z);\\n        let phi = Math.acos(Math.min(1, Math.max(-1, off.y / radius)));\\n        let tTheta = theta, tPhi = phi, tRadius = radius;\\n        let dragging = false, lx = 0, ly = 0, downX = null, downY = null;\\n        let hoverFn = null, clickFn = null, hovered = null;\\n        let maxR = 320;\\n        const dom = renderer.domElement;\\n        const onDown = (e) => { dragging = true; lx = e.clientX; ly = e.clientY; downX = e.clientX; downY = e.clientY; if (this.host) this.host.style.cursor = \'grabbing\'; };\\n        const onMove = (e) => {\\n          if (hoverFn) hoverFn(e);\\n          if (!dragging) return;\\n          tTheta -= (e.clientX - lx) * 0.006;\\n          tPhi -= (e.clientY - ly) * 0.006;\\n          tPhi = Math.min(1.36, Math.max(0.12, tPhi));\\n          lx = e.clientX; ly = e.clientY;\\n        };\\n        const onUp = (e) => {\\n          const moved = (e && downX != null) ? Math.hypot(e.clientX - downX, e.clientY - downY) : 99;\\n          dragging = false;\\n          if (this.host) this.host.style.cursor = (hovered && this._level === \'country\') ? \'pointer\' : \'grab\';\\n          if (moved < 6 && clickFn) clickFn(e);\\n        };\\n        const onWheel = (e) => { e.preventDefault(); tRadius = Math.min(maxR, Math.max(40, tRadius * (1 + e.deltaY * 0.0012))); };\\n        dom.addEventListener(\'pointerdown\', onDown);\\n        window.addEventListener(\'pointermove\', onMove);\\n        window.addEventListener(\'pointerup\', onUp);\\n        dom.addEventListener(\'wheel\', onWheel, { passive: false });\\n        const ctl = {\\n          update() {\\n            if (autoRot && !dragging) tTheta += 0.0035;\\n            theta += (tTheta - theta) * 0.12;\\n            phi += (tPhi - phi) * 0.12;\\n            radius += (tRadius - radius) * 0.12;\\n            camera.position.set(\\n              target.x + radius * Math.sin(phi) * Math.sin(theta),\\n              target.y + radius * Math.cos(phi),\\n              target.z + radius * Math.sin(phi) * Math.cos(theta)\\n            );\\n            camera.lookAt(target);\\n          },\\n          dispose() {\\n            dom.removeEventListener(\'pointerdown\', onDown);\\n            window.removeEventListener(\'pointermove\', onMove);\\n            window.removeEventListener(\'pointerup\', onUp);\\n            dom.removeEventListener(\'wheel\', onWheel);\\n          }\\n        };\\n\\n        // composer / bloom — resilient: any failure falls back to plain render\\n        let composer = null;\\n        if (THREE.EffectComposer && THREE.UnrealBloomPass && THREE.RenderPass && THREE.CopyShader && THREE.ShaderPass) {\\n          try {\\n            composer = new THREE.EffectComposer(renderer);\\n            composer.addPass(new THREE.RenderPass(scene, camera));\\n            const bloomPass = new THREE.UnrealBloomPass(new THREE.Vector2(W, H), 0.42, 0.62, 0.6);\\n            // iframe 透明背景修复：UnrealBloomPass 内部 blur shader 把 alpha 硬编码为 1.0，\\n            // 导致最终叠加时透明区域 alpha 被加成非零（看起来就是黑色背景）。\\n            // 重写 compositeMaterial 让输出 alpha = 亮度（max rgb），暗处 alpha=0 保持透明，\\n            // 亮处 alpha>0 仍能让 bloom 扩散到 mesh 外。bloom 视觉效果完整保留。\\n            bloomPass.compositeMaterial.fragmentShader = `\\n              varying vec2 vUv;\\n              uniform sampler2D blurTexture1;\\n              uniform sampler2D blurTexture2;\\n              uniform sampler2D blurTexture3;\\n              uniform sampler2D blurTexture4;\\n              uniform sampler2D blurTexture5;\\n              uniform sampler2D dirtTexture;\\n              uniform float bloomStrength;\\n              uniform float bloomRadius;\\n              uniform float bloomFactors[NUM_MIPS];\\n              uniform vec3 bloomTintColors[NUM_MIPS];\\n\\n              float lerpBloomFactor(const in float factor) {\\n                float mirrorFactor = 1.2 - factor;\\n                return mix(factor, mirrorFactor, bloomRadius);\\n              }\\n\\n              void main() {\\n                vec4 bloomColor = bloomStrength * (\\n                  lerpBloomFactor(bloomFactors[0]) * vec4(bloomTintColors[0], 1.0) * texture2D(blurTexture1, vUv) +\\n                  lerpBloomFactor(bloomFactors[1]) * vec4(bloomTintColors[1], 1.0) * texture2D(blurTexture2, vUv) +\\n                  lerpBloomFactor(bloomFactors[2]) * vec4(bloomTintColors[2], 1.0) * texture2D(blurTexture3, vUv) +\\n                  lerpBloomFactor(bloomFactors[3]) * vec4(bloomTintColors[3], 1.0) * texture2D(blurTexture4, vUv) +\\n                  lerpBloomFactor(bloomFactors[4]) * vec4(bloomTintColors[4], 1.0) * texture2D(blurTexture5, vUv)\\n                );\\n                float a = clamp(max(max(bloomColor.r, bloomColor.g), bloomColor.b), 0.0, 1.0);\\n                gl_FragColor = vec4(bloomColor.rgb, a);\\n              }\\n            `;\\n            bloomPass.compositeMaterial.needsUpdate = true;\\n            composer.addPass(bloomPass);\\n          } catch (e) { composer = null; }\\n        }\\n\\n        // lights\\n        scene.add(new THREE.AmbientLight(0x2a456e, 0.7));\\n        const dir = new THREE.DirectionalLight(0x9fc4ee, 0.65); dir.position.set(40, 120, 60); scene.add(dir);\\n        const p1 = new THREE.PointLight(P.glow, 0.9, 400); p1.position.set(0, 70, 0); scene.add(p1);\\n\\n        // ---- projection ----\\n        const feats = geo.features;\\n        const keepFeat = (f) => {\\n          const nm = (f.properties && (f.properties.name || f.properties.NAME)) || \'\';\\n          const ad = String((f.properties && f.properties.adcode) || \'\');\\n          if (!nm) return false;\\n          if (!isProvince && (ad.indexOf(\'_JD\') >= 0 || nm.indexOf(\'南海\') >= 0 || nm.indexOf(\'诸岛\') >= 0 || nm.indexOf(\'九段\') >= 0)) return false;\\n          return true;\\n        };\\n        const allLon = [], allLat = [];\\n        feats.forEach(f => {\\n          if (!keepFeat(f)) return;\\n          const g = f.geometry; if (!g) return;\\n          const polys = g.type === \'MultiPolygon\' ? g.coordinates : [g.coordinates];\\n          polys.forEach(poly => poly.forEach(ring => ring.forEach(pt => { allLon.push(pt[0]); allLat.push(pt[1]); })));\\n        });\\n        const cx = (Math.min(...allLon) + Math.max(...allLon)) / 2;\\n        const cy = (Math.min(...allLat) + Math.max(...allLat)) / 2;\\n        const kx = Math.cos(cy * Math.PI / 180);\\n        let minX = 1e9, maxX = -1e9, minY = 1e9, maxY = -1e9;\\n        allLon.forEach((lon, i) => {\\n          const x = (lon - cx) * kx, y = (allLat[i] - cy);\\n          if (x < minX) minX = x; if (x > maxX) maxX = x;\\n          if (y < minY) minY = y; if (y > maxY) maxY = y;\\n        });\\n        const scale = 118 / Math.max(maxX - minX, maxY - minY);\\n        const prj = (lon, lat) => [(lon - cx) * kx * scale, (lat - cy) * scale];\\n\\n        const DEPTH = 7;\\n        const group = new THREE.Group();\\n        group.rotation.x = -Math.PI / 2;\\n        scene.add(group);\\n\\n        const topMat = new THREE.MeshStandardMaterial({ color: P.side, emissive: P.top, emissiveIntensity: 0.14, metalness: 0.45, roughness: 0.62, transparent: true, opacity: 0.97 });\\n        const sideMat = new THREE.MeshStandardMaterial({ color: P.side, emissive: P.edge, emissiveIntensity: 0.1, metalness: 0.6, roughness: 0.48 });\\n        const lineMat = new THREE.LineBasicMaterial({ color: P.edge, transparent: true, opacity: 0.95 });\\n        const baseLineMat = new THREE.LineBasicMaterial({ color: P.glow, transparent: true, opacity: 0.4 });\\n\\n        const districts = [];\\n        const pickMeshes = [];\\n        const featureMap = {};\\n        const polyArea = ring => { let a = 0; for (let i = 0, n = ring.length; i < n; i++) { const j = (i + 1) % n; a += ring[i][0] * ring[j][1] - ring[j][0] * ring[i][1]; } return Math.abs(a / 2); };\\n\\n        feats.forEach(f => {\\n          if (!keepFeat(f)) return;\\n          const g = f.geometry; if (!g) return;\\n          const name = (f.properties && (f.properties.name || f.properties.NAME)) || \'\';\\n          const adcode = String((f.properties && f.properties.adcode) || \'\');\\n          const fTop = topMat.clone(), fSide = sideMat.clone();\\n          const fMeshes = [];\\n          const polys = g.type === \'MultiPolygon\' ? g.coordinates : [g.coordinates];\\n          let bestRing = null, bestArea = -1;\\n          polys.forEach(poly => {\\n            const outer = poly[0];\\n            const ar0 = polyArea(outer);\\n            if (ar0 > bestArea) { bestArea = ar0; bestRing = outer; }\\n            let latSum = 0; for (const p of outer) latSum += p[1]; const latC = latSum / outer.length;\\n            if (!isProvince && latC < 18) return;\\n            if (ar0 < 0.02) return;\\n            const shape = new THREE.Shape();\\n            outer.forEach((pt, i) => { const [x, y] = prj(pt[0], pt[1]); i ? shape.lineTo(x, y) : shape.moveTo(x, y); });\\n            for (let h = 1; h < poly.length; h++) {\\n              const path = new THREE.Path();\\n              poly[h].forEach((pt, i) => { const [x, y] = prj(pt[0], pt[1]); i ? path.lineTo(x, y) : path.moveTo(x, y); });\\n              shape.holes.push(path);\\n            }\\n            const egeo = new THREE.ExtrudeGeometry(shape, { depth: DEPTH, bevelEnabled: true, bevelThickness: 0.6, bevelSize: 0.4, bevelSegments: 2 });\\n            const mesh = new THREE.Mesh(egeo, [fTop, fSide]);\\n            mesh.userData = { adcode, name };\\n            group.add(mesh); fMeshes.push(mesh); pickMeshes.push(mesh);\\n            poly.forEach(ring => {\\n              const pts = ring.map(pt => { const [x, y] = prj(pt[0], pt[1]); return new THREE.Vector3(x, y, DEPTH + 0.25); });\\n              group.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), lineMat));\\n              const fpts = ring.map(pt => { const [x, y] = prj(pt[0], pt[1]); return new THREE.Vector3(x, y, -0.4); });\\n              group.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(fpts), baseLineMat));\\n            });\\n          });\\n          featureMap[adcode] = { mats: [fTop, fSide], meshes: fMeshes, name };\\n          const isBeijingCountry = !isProvince && name === \'北京市\';\\n          if (bestRing && name && !isBeijingCountry) {\\n            let sx = 0, sy = 0; bestRing.forEach(pt => { sx += pt[0]; sy += pt[1]; });\\n            const [px, py] = prj(sx / bestRing.length, sy / bestRing.length);\\n            districts.push({ name: isProvince ? districtLabel(name) : shorten(name), rawName: name, px, py, adcode, area: bestArea });\\n          }\\n        });\\n\\n        // ---- auto-fit (true contain) ----\\n        const fitView = (instant, keepAngle) => {\\n          group.updateMatrixWorld(true);\\n          // bbox 只看实际地图 mesh，不算光柱/飞线/光晕（它们会向上拉得很高，把 bbox 撑大，相机被迫拉远）\\n          const box = new THREE.Box3();\\n          if (pickMeshes && pickMeshes.length) {\\n            for (const m of pickMeshes) box.expandByObject(m);\\n          } else {\\n            box.setFromObject(group);\\n          }\\n          const ctr = box.getCenter(new THREE.Vector3());\\n          target.set(ctr.x, 1, ctr.z);\\n          const corners = [];\\n          [box.min.x, box.max.x].forEach(X => [box.min.y, box.max.y].forEach(Y => [box.min.z, box.max.z].forEach(Z => corners.push(new THREE.Vector3(X, Y, Z)))));\\n          const az = keepAngle ? theta : 0;\\n          const tilt = keepAngle ? phi : 0.62;\\n          const tmp = camera.clone();\\n          let d = 200;\\n          // 全国视图填充更满（1.05 容忍轻微出框），省份保持原 0.92\\n          const fillTarget = isProvince ? 0.92 : 1.05;\\n          for (let it = 0; it < 40; it++) {\\n            tmp.position.set(target.x + d * Math.sin(tilt) * Math.sin(az), target.y + d * Math.cos(tilt), target.z + d * Math.sin(tilt) * Math.cos(az));\\n            tmp.lookAt(target); tmp.updateMatrixWorld(true);\\n            let m = 0;\\n            for (const c of corners) { const p = c.clone().project(tmp); m = Math.max(m, Math.abs(p.x), Math.abs(p.y)); }\\n            const nd = d * (m / fillTarget);\\n            const done = Math.abs(nd - d) < 0.05; d = nd; if (done) break;\\n          }\\n          maxR = Math.max(320, d * 2.4);\\n          tRadius = d;\\n          if (!keepAngle) { tPhi = tilt; tTheta = 0; }\\n          if (instant) { radius = d; if (!keepAngle) { phi = tilt; theta = 0; } }\\n        };\\n        fitView(true, false);\\n        this._refit = () => fitView(false, true);\\n\\n        // ---- markers + labels ----\\n        this._markers = [];\\n        this._labels = [];\\n        if (this.labelsEl) this.labelsEl.innerHTML = \'\';\\n\\n        const makeBadge = (name, isCity, adcode, clickable, tagText) => {\\n          const wrap = document.createElement(\'div\');\\n          wrap.style.cssText = \'position:absolute; left:0; top:0; display:flex; flex-direction:column; align-items:center; transform:translate(-50%,-100%); will-change:transform; transition:opacity .2s;\';\\n          const pill = document.createElement(\'div\');\\n          const ac = \'#\' + (isCity ? P.city : P.edge).toString(16).padStart(6, \'0\');\\n          if (isCity) {\\n            pill.style.cssText = `font-family:\'Noto Sans SC\',sans-serif; font-weight:900; font-size:19px; letter-spacing:1px; color:#fff; padding:9px 18px; border-radius:8px; white-space:nowrap; background:linear-gradient(180deg,rgba(40,18,2,.85),rgba(20,8,0,.9)); border:1.5px solid ${ac}; box-shadow:0 0 22px ${ac}99, inset 0 0 14px ${ac}55; text-shadow:0 0 12px ${ac};`;\\n            pill.innerHTML = name + (tagText ? \'<span style=\\\"font-family:Orbitron;font-size:9px;letter-spacing:3px;color:\' + ac + \';margin-left:8px;vertical-align:middle;\\\">\' + tagText + \'</span>\' : \'\');\\n          } else {\\n            pill.style.cssText = `font-family:\'Noto Sans SC\',sans-serif; font-weight:700; font-size:13px; letter-spacing:.5px; color:#eaf6ff; padding:5px 11px; border-radius:6px; white-space:nowrap; background:rgba(6,22,48,.72); border:1px solid ${ac}aa; box-shadow:0 0 12px ${ac}66, inset 0 0 8px ${ac}33; backdrop-filter:blur(2px);`;\\n            pill.textContent = name;\\n          }\\n          if (clickable) {\\n            pill.style.pointerEvents = \'auto\';\\n            pill.style.cursor = \'pointer\';\\n            pill.addEventListener(\'click\', (ev) => { ev.stopPropagation(); this._drill(adcode, name === \'北京\' ? \'北京市\' : name); });\\n            pill.addEventListener(\'mouseenter\', () => { if (featureMap[adcode]) featureMap[adcode].mats.forEach((m, i) => m.emissiveIntensity = i === 0 ? 0.7 : 0.55); });\\n            pill.addEventListener(\'mouseleave\', () => { if (featureMap[adcode]) featureMap[adcode].mats.forEach((m, i) => m.emissiveIntensity = i === 0 ? 0.22 : 0.16); });\\n          }\\n          const stem = document.createElement(\'div\');\\n          stem.style.cssText = `width:2px; height:${isCity ? 30 : 22}px; background:linear-gradient(180deg, ${ac}, ${ac}00);`;\\n          wrap.appendChild(pill); wrap.appendChild(stem);\\n          if (this.labelsEl) this.labelsEl.appendChild(wrap);\\n          return wrap;\\n        };\\n\\n        const addMarker = (px, py, name, isCity, adcode, tagText) => {\\n          const col = isCity ? P.city : P.marker;\\n          const anchor = new THREE.Object3D();\\n          anchor.position.set(px, py, DEPTH + 0.1); group.add(anchor);\\n          const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: this._glowTex(col), color: col, transparent: true, opacity: 0.55, depthWrite: false, blending: THREE.AdditiveBlending }));\\n          const s = isCity ? 8.5 : 3.6; sp.scale.set(s, s, s); sp.position.set(px, py, DEPTH + 1.2); group.add(sp);\\n          const rings = [];\\n          // concentric ripples as camera-facing billboards (Sprites) — always clean circles,\\n          // never collapse into horizontal lines at low angles, and don\'t smear across boundary lines\\n          const ringTex = this._ringTex(col);\\n          const ringCount = isCity ? 9 : 2;\\n          const rc = isCity ? 8.5 : 2.6;  // base ring diameter (world units)\\n          const rz = DEPTH + (isCity ? 2.4 : 1.4);\\n          for (let i = 0; i < ringCount; i++) {\\n            const rg = new THREE.Sprite(new THREE.SpriteMaterial({ map: ringTex, color: col, transparent: true, opacity: 0.7, depthWrite: false, blending: THREE.AdditiveBlending }));\\n            rg.position.set(px, py, rz); group.add(rg);\\n            rings.push({ mesh: rg, phase: i / ringCount, base: rc });\\n          }\\n          if (isCity) {\\n            // soft halo + bright core, also billboards\\n            const halo = new THREE.Sprite(new THREE.SpriteMaterial({ map: this._glowTex(col), color: col, transparent: true, opacity: 0.5, depthWrite: false, blending: THREE.AdditiveBlending }));\\n            halo.scale.set(rc * 1.5, rc * 1.5, 1); halo.position.set(px, py, rz + 0.05); group.add(halo);\\n            const disc = new THREE.Sprite(new THREE.SpriteMaterial({ map: this._glowTex(col), color: 0xffffff, transparent: true, opacity: 0.95, depthWrite: false, blending: THREE.AdditiveBlending }));\\n            disc.scale.set(rc * 0.62, rc * 0.62, 1); disc.position.set(px, py, rz + 0.1); group.add(disc);\\n          }\\n          const beamH = isCity ? 26 : 12;\\n          const beam = new THREE.Mesh(new THREE.CylinderGeometry(isCity ? 0.7 : 0.32, isCity ? 1.1 : 0.5, beamH, 12, 1, true), new THREE.MeshBasicMaterial({ color: col, transparent: true, opacity: isCity ? 0.2 : 0.13, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false }));\\n          beam.rotation.x = Math.PI / 2; beam.position.set(px, py, DEPTH + beamH / 2); group.add(beam);\\n          const badge = makeBadge(name, isCity, adcode, !isProvince, tagText);\\n          this._markers.push({ rings, expand: isCity ? 4.2 : 1.7, op: isCity ? 0.95 : 0.6 });\\n          const world = new THREE.Vector3(); anchor.updateWorldMatrix(true, false); anchor.getWorldPosition(world);\\n          this._labels.push({ el: badge, pos: world, isCity });\\n        };\\n\\n        // ---- flow arcs: every region streams toward the hub (capital) ----\\n        const CAPITAL = { \'110000\': \'东城区\', \'120000\': \'和平区\', \'310000\': \'黄浦区\', \'500000\': \'渝中区\', \'130000\': \'石家庄市\', \'140000\': \'太原市\', \'150000\': \'呼和浩特市\', \'210000\': \'沈阳市\', \'220000\': \'长春市\', \'230000\': \'哈尔滨市\', \'320000\': \'南京市\', \'330000\': \'杭州市\', \'340000\': \'合肥市\', \'350000\': \'福州市\', \'360000\': \'南昌市\', \'370000\': \'济南市\', \'410000\': \'郑州市\', \'420000\': \'武汉市\', \'430000\': \'长沙市\', \'440000\': \'广州市\', \'450000\': \'南宁市\', \'460000\': \'海口市\', \'510000\': \'成都市\', \'520000\': \'贵阳市\', \'530000\': \'昆明市\', \'540000\': \'拉萨市\', \'610000\': \'西安市\', \'620000\': \'兰州市\', \'630000\': \'西宁市\', \'640000\': \'银川市\', \'650000\': \'乌鲁木齐市\', \'710000\': \'台北市\' };\\n        let hub;\\n        if (!isProvince) { const [hx, hy] = prj(116.405, 39.915); hub = { x: hx, y: hy, adcode: \'110000\' }; }\\n        else {\\n          const capName = CAPITAL[this._curAdcode];\\n          let cap = capName ? districts.find(d => d.rawName === capName) : null;\\n          if (!cap) cap = districts.slice().sort((a, b) => b.area - a.area)[0];\\n          hub = cap ? { x: cap.px, y: cap.py, adcode: cap.adcode } : { x: 0, y: 0, adcode: null };\\n        }\\n        const arcTex = this._glowTex(P.city);\\n        const arcs = [];\\n        const arcCount = districts.filter(d => !(isProvince && hub.adcode && d.adcode === hub.adcode)).length;\\n        let arcIdx = 0;\\n        const makeArc = (sx, sy) => {\\n          // unique hue per arc, spread evenly around the color wheel (with a golden-angle jitter)\\n          const hue = ((arcIdx * 360 / Math.max(arcCount, 1)) + arcIdx * 13.7) % 360 / 360;\\n          arcIdx++;\\n          const lineCol = new THREE.Color().setHSL(hue, 0.85, 0.6);\\n          const dimCol = lineCol.clone().multiplyScalar(0.28);\\n          const start = new THREE.Vector3(sx, sy, DEPTH + 0.5);\\n          // arc ends exactly at the hub (Beijing / provincial capital)\\n          const end = new THREE.Vector3(hub.x, hub.y, DEPTH + 0.5);\\n          const dist = start.distanceTo(end);\\n          const mid = start.clone().lerp(end, 0.5);\\n          mid.z += Math.min(54, 7 + dist * 0.52);\\n          const curve = new THREE.QuadraticBezierCurve3(start, mid, end);\\n          // thick tube so the flight line reads as a solid ribbon, fading thinner toward the start\\n          const tubeGeo = new THREE.TubeGeometry(curve, 48, 0.12, 8, false);\\n          const cols = [];\\n          const pos = tubeGeo.attributes.position;\\n          const seg = 48;\\n          for (let i = 0; i < pos.count; i++) {\\n            const ring = Math.floor(i / 9); // (radialSegments+1) verts per ring\\n            const f = Math.min(1, ring / seg);\\n            const c = dimCol.clone().lerp(lineCol, f);\\n            cols.push(c.r, c.g, c.b);\\n          }\\n          tubeGeo.setAttribute(\'color\', new THREE.Float32BufferAttribute(cols, 3));\\n          group.add(new THREE.Mesh(tubeGeo, new THREE.MeshBasicMaterial({ vertexColors: true, transparent: true, opacity: 0.85, blending: THREE.AdditiveBlending, depthWrite: false })));\\n          const trail = [];\\n          for (let i = 0; i < 5; i++) {\\n            const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: arcTex, color: lineCol, transparent: true, opacity: 0.95, depthWrite: false, blending: THREE.AdditiveBlending }));\\n            sp.scale.set(0.01, 0.01, 0.01); group.add(sp); trail.push(sp);\\n          }\\n          arcs.push({ curve, trail, speed: 0.16 + Math.random() * 0.08, offset: Math.random() });\\n        };\\n        this._arcs = arcs;\\n\\n        districts.forEach(d => {\\n          const isHub = isProvince && hub.adcode && d.adcode === hub.adcode;\\n          addMarker(d.px, d.py, d.name, isHub, d.adcode, isHub ? \'省会\' : \'\');\\n          if (!isHub) makeArc(d.px, d.py);\\n        });\\n        if (!isProvince) { const [cpx, cpy] = prj(116.405, 39.915); addMarker(cpx, cpy, \'北京\', true, \'110000\', \'首都\'); }\\n\\n        // ---- picking ----\\n        const ray = new THREE.Raycaster();\\n        const ndc = new THREE.Vector2();\\n        const pickAt = (e) => {\\n          const rect = dom.getBoundingClientRect();\\n          ndc.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;\\n          ndc.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;\\n          ray.setFromCamera(ndc, camera);\\n          const hits = ray.intersectObjects(pickMeshes, false);\\n          return hits.length ? hits[0].object.userData : null;\\n        };\\n        const setHover = (adcode) => {\\n          if (hovered === adcode) return;\\n          if (hovered && featureMap[hovered]) featureMap[hovered].mats.forEach((m, i) => m.emissiveIntensity = i === 0 ? 0.22 : 0.16);\\n          hovered = adcode;\\n          if (adcode && featureMap[adcode]) featureMap[adcode].mats.forEach((m, i) => m.emissiveIntensity = i === 0 ? 0.7 : 0.55);\\n          if (this.host && !dragging) this.host.style.cursor = (adcode && this._level === \'country\') ? \'pointer\' : \'grab\';\\n        };\\n        let hoverRAF = false;\\n        hoverFn = (e) => {\\n          if (dragging || hoverRAF) return;\\n          hoverRAF = true;\\n          requestAnimationFrame(() => { hoverRAF = false; const ud = pickAt(e); setHover(ud ? ud.adcode : null); });\\n        };\\n        clickFn = (e) => { const ud = pickAt(e); if (ud && ud.adcode && this._level === \'country\') this._drill(ud.adcode, ud.name); };\\n\\n        // ---- header / back button state ----\\n        if (this.titleEl) this.titleEl.textContent = isProvince ? (regionName || \'\') + \' · 三维地图\' : \'中国 · 三维地图\';\\n        if (this.subEl) this.subEl.textContent = isProvince ? (districts.length + \' 个地区 · 行政区划可视化\') : \'34 省级行政区 · 点击区域下钻\';\\n        // 融合版：全国和省级都有上一层（地球 / 全国），所以两种 level 都要显示按钮\\n        if (this.backBtn) this.backBtn.style.display = \'inline-flex\';\\n\\n        this._three = { scene, camera, renderer, controls: ctl, composer };\\n        this._hideLoading();\\n\\n        this._onResize = () => {\\n          if (!this.host) return;\\n          const w = this.host.clientWidth, h = this.host.clientHeight;\\n          camera.aspect = w / h; camera.updateProjectionMatrix();\\n          renderer.setSize(w, h); if (composer) composer.setSize(w, h);\\n          if (this._refit) this._refit();\\n        };\\n        window.addEventListener(\'resize\', this._onResize);\\n\\n        // ---- loop ----\\n        const clock = new THREE.Clock();\\n        const v = new THREE.Vector3();\\n        const loop = () => {\\n          if (!this._alive || !this._three) return;\\n          this._raf = requestAnimationFrame(loop);\\n          const t = clock.getElapsedTime();\\n          ctl.update();\\n          this._markers.forEach(m => {\\n            m.rings.forEach(r => {\\n              const f = (t * 0.4 + r.phase) % 1;\\n              const sc = r.base * (0.35 + f * m.expand);\\n              r.mesh.scale.set(sc, sc, 1);\\n              // fade in quickly, then ease-out as it grows — bright when small, faint when large\\n              const fade = Math.min(1, f * 6) * Math.pow(1 - f, 1.5);\\n              r.mesh.material.opacity = fade * m.op;\\n            });\\n          });\\n          if (this._arcs) {\\n            for (const a of this._arcs) {\\n              for (let i = 0; i < a.trail.length; i++) {\\n                let u = (t * a.speed + a.offset - i * 0.035) % 1;\\n                if (u < 0) u += 1;\\n                const p = a.curve.getPoint(u);\\n                a.trail[i].position.copy(p);\\n                const sc = (1.7 - i * 0.26) * (i === 0 ? 1.15 : 1);\\n                a.trail[i].scale.set(sc, sc, sc);\\n                a.trail[i].material.opacity = (1 - i * 0.18) * (0.45 + 0.55 * Math.sin(u * Math.PI));\\n              }\\n            }\\n          }\\n          if (composer) composer.render(); else renderer.render(scene, camera);\\n          const w = this.host.clientWidth, h = this.host.clientHeight;\\n          for (const L of this._labels) {\\n            v.copy(L.pos).project(camera);\\n            if (v.z > 1) { L.el.style.opacity = \'0\'; continue; }\\n            const x = (v.x * 0.5 + 0.5) * w;\\n            const y = (-v.y * 0.5 + 0.5) * h - (L.isCity ? 18 : 12);\\n            L.el.style.transform = `translate(${x}px, ${y}px) translate(-50%,-100%)`;\\n            L.el.style.opacity = \'1\';\\n          }\\n        };\\n        loop();\\n      }\\n\\n      _teardown() {\\n        if (this._raf) cancelAnimationFrame(this._raf), this._raf = null;\\n        if (this._onResize) window.removeEventListener(\'resize\', this._onResize), this._onResize = null;\\n        const t = this._three;\\n        if (t) {\\n          try { t.controls.dispose(); } catch (e) { }\\n          try {\\n            t.scene.traverse(o => {\\n              if (o.geometry) o.geometry.dispose();\\n              if (o.material) (Array.isArray(o.material) ? o.material : [o.material]).forEach(m => { if (m.map) m.map.dispose(); m.dispose(); });\\n            });\\n          } catch (e) { }\\n          try { t.renderer.dispose(); if (t.renderer.domElement && t.renderer.domElement.parentNode) t.renderer.domElement.parentNode.removeChild(t.renderer.domElement); } catch (e) { }\\n          this._three = null;\\n        }\\n        if (this.labelsEl) this.labelsEl.innerHTML = \'\';\\n      }\\n    }\\n\\n    // ============================================================\\n    //  App：vanilla DOM 调度器（替代原 Component extends DCLogic）\\n    //  - 维护 state（mode / chinaLevel / provName / features / cardOpen / cardCity）\\n    //  - 用 document.getElementById + element.style/textContent 直接更新 UI\\n    //  - 启停 EarthScene / ChinaMap 实例\\n    //  - 协调 enterChina / leaveChina 的黑蒙层过渡\\n    // ============================================================\\n    class App {\\n      constructor() {\\n        // DOM 引用\\n        this.$earthRoot = document.getElementById(\'earth-root\');\\n        this.$earthHolder = document.getElementById(\'earth-holder\');\\n        this.$earthLabels = document.getElementById(\'earth-labels\');\\n        this.$chinaHolder = document.getElementById(\'china-holder\');\\n        this.$chinaLabels = document.getElementById(\'china-labels\');\\n        this.$chinaTitle = document.getElementById(\'china-title\');\\n        this.$chinaSub = document.getElementById(\'china-sub\');\\n        this.$chinaBack = document.getElementById(\'china-back\');\\n        this.$chinaBackLabel = document.getElementById(\'china-back-label\');\\n        this.$chinaLoading = document.getElementById(\'china-loading\');\\n        this.$chinaLoadingTxt = document.getElementById(\'china-loading-txt\');\\n        this.$featureToggles = document.getElementById(\'feature-toggles\');\\n        this.$infoCard = document.getElementById(\'info-card\');\\n        this.$cardCity = document.getElementById(\'card-city\');\\n        this.$cardClose = document.getElementById(\'card-close\');\\n        this.$breadcrumb = document.getElementById(\'breadcrumb\');\\n\\n        // 静态：左侧 6 个开关定义\\n        this.featureList = [\\n          { key: \'bars\', label: \'柱状图\' },\\n          { key: \'arcs\', label: \'飞线\' },\\n          { key: \'labels\', label: \'标签\' },\\n          { key: \'land\', label: \'陆运线\' },\\n          { key: \'sea\', label: \'海航线\' },\\n          { key: \'halo\', label: \'粒子光环\' },\\n        ];\\n\\n        // App 状态\\n        this.state = {\\n          mode: \'earth\',                  // \'earth\' | \'china\'\\n          chinaLevel: \'country\',                // 仅 mode=\'china\' 有意义\\n          provName: null,                     // mode=\'china\' && chinaLevel=\'prov\' 时填省名\\n          features: { bars: true, arcs: true, labels: true, land: true, sea: true, halo: true },\\n          cardOpen: false,\\n          cardLeft: \'42%\',\\n          cardTop: \'29%\',\\n          cardCity: \'标题名称内容详情\',\\n        };\\n\\n        // 黑蒙层动态挂 body 根\\n        this._createShroud();\\n\\n        // 初始渲染\\n        this._buildFeatureToggles();\\n        this._renderBreadcrumb();\\n        this._renderInfoCard();\\n        document.body.setAttribute(\'data-mode\', this.state.mode);\\n\\n        // 静态事件\\n        this.$cardClose.addEventListener(\'click\', () => this.closeCard());\\n        this.$chinaBack.addEventListener(\'click\', () => this.onChinaBackClick());\\n\\n        // 启动地球（THREE 已通过 module import 就绪）\\n        this._spawnEarth();\\n\\n        // Three.js module 已加载、EarthScene 也已构造，淡出启动 loading\\n        // 等一帧让 canvas 出现在 DOM 里，再开始 fade，避免观感上\\\"没东西就消失了\\\"\\n        this._hideAppLoading();\\n      }\\n\\n      _hideAppLoading() {\\n        const el = document.getElementById(\'app-loading\');\\n        if (!el) return;\\n        requestAnimationFrame(() => {\\n          el.classList.add(\'hidden\');\\n          // CSS transition 是 .4s\\n          setTimeout(() => { el.remove(); }, 450);\\n        });\\n      }\\n\\n      // ============ state / 渲染 ============\\n\\n      // 合并 patch 到 state，按 patch 字段触发对应 UI 重新渲染\\n      setState(patch) {\\n        Object.assign(this.state, patch);\\n        if (\'mode\' in patch) document.body.setAttribute(\'data-mode\', this.state.mode);\\n        if (\'features\' in patch) this._renderFeatureToggles();\\n        if (\'cardOpen\' in patch || \'cardCity\' in patch || \'cardLeft\' in patch || \'cardTop\' in patch) {\\n          this._renderInfoCard();\\n        }\\n        if (\'mode\' in patch || \'chinaLevel\' in patch || \'provName\' in patch) {\\n          this._renderBreadcrumb();\\n        }\\n      }\\n\\n      // 初次创建 6 个 pill，后续只 _renderFeatureToggles 改样式\\n      _buildFeatureToggles() {\\n        this.$featureToggles.innerHTML = \'\';\\n        this.featurePills = {};\\n        this.featureList.forEach(it => {\\n          const pill = document.createElement(\'div\');\\n          pill.className = \'feature-pill\';\\n          pill.textContent = it.label;\\n          pill.addEventListener(\'click\', () => this.toggleFeature(it.key));\\n          this.$featureToggles.appendChild(pill);\\n          this.featurePills[it.key] = pill;\\n        });\\n        this._renderFeatureToggles();\\n      }\\n\\n      _renderFeatureToggles() {\\n        const f = this.state.features;\\n        this.featureList.forEach(it => {\\n          const on = f[it.key];\\n          const pill = this.featurePills[it.key];\\n          pill.style.background = on ? \'rgba(28,86,120,0.55)\' : \'rgba(8,18,28,0.5)\';\\n          pill.style.border = \'1px solid \' + (on ? \'rgba(90,200,255,0.85)\' : \'rgba(90,130,160,0.3)\');\\n          pill.style.color = on ? \'#dff4ff\' : \'#7e97a8\';\\n          pill.style.boxShadow = on\\n            ? \'0 0 14px rgba(50,160,220,0.35), inset 0 0 12px rgba(60,170,230,0.18)\'\\n            : \'none\';\\n        });\\n      }\\n\\n      _renderInfoCard() {\\n        this.$infoCard.style.display = this.state.cardOpen ? \'block\' : \'none\';\\n        if (!this.state.cardOpen) return;\\n        this.$infoCard.style.left = this.state.cardLeft;\\n        this.$infoCard.style.top = this.state.cardTop;\\n        this.$cardCity.textContent = this.state.cardCity;\\n      }\\n\\n      // 面包屑：earth → [全球]；china+country → [全球, 中国]；china+prov → [全球, 中国, 省份]\\n      // 每项可点击（当前层级 cursor=default 且 no-op）\\n      _renderBreadcrumb() {\\n        const crumbs = [{\\n          label: \'全球\',\\n          sep: false,\\n          isCurrent: this.state.mode === \'earth\',\\n          onClick: () => this.navigateTo(\'earth\'),\\n        }];\\n        if (this.state.mode === \'china\') {\\n          crumbs.push({\\n            label: \'中国\',\\n            sep: true,\\n            isCurrent: this.state.chinaLevel === \'country\',\\n            onClick: () => this.navigateTo(\'country\'),\\n          });\\n          if (this.state.chinaLevel === \'prov\' && this.state.provName) {\\n            const short = this.state.provName.replace(/(省|市|自治区|特别行政区)$/g, \'\');\\n            crumbs.push({\\n              label: short,\\n              sep: true,\\n              isCurrent: true,\\n              onClick: () => { },\\n            });\\n          }\\n        }\\n\\n        this.$breadcrumb.innerHTML = \'\';\\n        crumbs.forEach(c => {\\n          if (c.sep) {\\n            const s = document.createElement(\'span\');\\n            s.className = \'crumb-sep\';\\n            s.textContent = \'›\';\\n            this.$breadcrumb.appendChild(s);\\n          }\\n          const pill = document.createElement(\'span\');\\n          pill.className = \'crumb-pill\';\\n          pill.textContent = c.label;\\n          pill.style.cursor = c.isCurrent ? \'default\' : \'pointer\';\\n          pill.addEventListener(\'click\', c.onClick);\\n          this.$breadcrumb.appendChild(pill);\\n        });\\n      }\\n\\n      _createShroud() {\\n        let shroud = document.getElementById(\'fusion-shroud\');\\n        if (!shroud) {\\n          shroud = document.createElement(\'div\');\\n          shroud.id = \'fusion-shroud\';\\n          document.body.appendChild(shroud);\\n        }\\n        this._shroud = shroud;\\n      }\\n\\n      _showShroud(visible) {\\n        return new Promise((r) => {\\n          this._shroud.classList.toggle(\'active\', visible);\\n          // CSS transition .3s，多 20ms 容差\\n          setTimeout(r, 320);\\n        });\\n      }\\n\\n      // ============ 用户事件 ============\\n\\n      toggleFeature(k) {\\n        const features = { ...this.state.features, [k]: !this.state.features[k] };\\n        this.setState({ features });\\n        if (this.earth) this.earth.setFeature(k, features[k]);\\n      }\\n\\n      closeCard() { this.setState({ cardOpen: false }); }\\n\\n      onChinaBackClick() {\\n        if (!this.chinaMap) return;\\n        if (this.chinaMap._level === \'prov\') this.chinaMap._back();   // prov → country\\n        else this.leaveChina();                                        // country → earth\\n      }\\n\\n      // 面包屑跳转：\'earth\' / \'country\'。已在目标层级时 no-op。\\n      navigateTo(target) {\\n        if (target === \'earth\') {\\n          if (this.state.mode === \'earth\') return;\\n          this.leaveChina();\\n          return;\\n        }\\n        if (target === \'country\') {\\n          if (this.state.mode !== \'china\') return;\\n          if (this.state.chinaLevel === \'country\') return;\\n          if (this.chinaMap) this.chinaMap._back();\\n        }\\n      }\\n\\n      // ============ 场景生命周期 ============\\n\\n      _spawnEarth() {\\n        this.earth = new EarthScene(\\n          this.$earthHolder,\\n          this.$earthLabels,\\n          {\\n            rotateSpeed: 0.6,\\n            features: this.state.features,\\n            onChinaClick: () => this.enterChina(),\\n            onCityClick: (name, p, rect) => {\\n              this.setState({\\n                cardOpen: true,\\n                cardCity: (name === \'浙江\' ? \'标题名称内容详情\' : name),\\n                cardLeft: Math.min(Math.max(p.clientX - rect.left, 40), rect.width - 330) + \'px\',\\n                cardTop: Math.min(Math.max(p.clientY - rect.top - 60, 20), rect.height - 280) + \'px\',\\n              });\\n            },\\n          }\\n        );\\n      }\\n\\n      _spawnChinaMap() {\\n        this.chinaMap = new ChinaMap(\\n          this.$chinaHolder,\\n          {\\n            labels: this.$chinaLabels,\\n            title: this.$chinaTitle,\\n            sub: this.$chinaSub,\\n            back: this.$chinaBack,\\n            backLabel: this.$chinaBackLabel,\\n            loading: this.$chinaLoading,\\n            loadingTxt: this.$chinaLoadingTxt,\\n          },\\n          {\\n            onLevelChange: (level, name) => {\\n              this._updateBackButton(level);\\n              this.setState({ chinaLevel: level, provName: name });\\n            },\\n          }\\n        );\\n      }\\n\\n      _updateBackButton(level) {\\n        this.$chinaBackLabel.textContent = (level === \'prov\') ? \'返回全国\' : \'返回全球地图\';\\n      }\\n\\n      // ============ 过渡 ============\\n\\n      async enterChina() {\\n        if (!this.earth || this.state.mode !== \'earth\') return;\\n        // 1) 相机推近浙江\\n        await new Promise((r) => this.earth.flyToChina(600, r));\\n        // 2) 蒙层 fade-in\\n        await this._showShroud(true);\\n        // 3) 销毁地球\\n        this.earth.destroy(); this.earth = null;\\n        // 4) 切 mode（CSS 自动切显隐）\\n        this.setState({ mode: \'china\' });\\n        // 5) 等一帧确保 chinaHolder 已布局\\n        await new Promise((r) => requestAnimationFrame(r));\\n        // 6) 构造 ChinaMap（构造时会触发 onLevelChange(\'country\') → 更新面包屑+按钮文案）\\n        this._spawnChinaMap();\\n        // 7) 蒙层 fade-out\\n        await this._showShroud(false);\\n      }\\n\\n      async leaveChina() {\\n        if (!this.chinaMap || this.state.mode !== \'china\') return;\\n        await this._showShroud(true);\\n        this.chinaMap.destroy(); this.chinaMap = null;\\n        this.setState({ mode: \'earth\', chinaLevel: \'country\', provName: null });\\n        await new Promise((r) => requestAnimationFrame(r));\\n        this._spawnEarth();\\n        await this._showShroud(false);\\n      }\\n    }\\n\\n    // 启动\\n    new App();\\n  </script>\\n\\n  <!-- ============================================================\\n       内置纹理（base64 data URI，避免每次从 threejs.org CDN 拉取）\\n       EarthScene 启动时通过 getElementById 读取\\n       ============================================================ -->\\n\\n  <!-- 来源：https://threejs.org/examples/textures/planets/earth_atmos_2048.jpg  (~683KB) -->\\n  <script id=\\\"inline-tex-earth-day\\\" type=\\\"text/plain\\\">data:image/jpeg;base64,</script>\\n\\n  <!-- 来源：https://threejs.org/examples/textures/planets/earth_clouds_1024.png  (~347KB) -->\\n  <script id=\\\"inline-tex-earth-clouds\\\" type=\\\"text/plain\\\">data:image/png;base64,</script>\\n</body>\\n\\n</html>\",\"option\":{\"title\":{\"textAlign\":\"left\",\"show\":false,\"text\":\"\"},\"card\":{\"rightHref\":\"\",\"size\":\"default\",\"extra\":\"\",\"title\":\"\"}}}', 'admin', '2026-06-29 18:34:53', NULL, NULL);
INSERT INTO `onl_drag_page_comp` (`id`, `parent_id`, `page_Id`, `comp_id`, `component`, `config`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES ('1231521823345823744', NULL, '1229579046974345216', NULL, 'JCurrentTime', '{\"borderColor\":\"#FFFFFF00\",\"dataType\":1,\"h\":50,\"url\":\"http://api.jeecg.com/mock/42/nav\",\"timeOut\":0,\"chartData\":\"\",\"size\":{\"width\":420,\"height\":50},\"background\":\"#FFFFFF00\",\"w\":420,\"turnConfig\":{\"type\":\"_blank\",\"url\":\"\"},\"linkType\":\"url\",\"linkageConfig\":[],\"chart\":{\"subclass\":\"JCurrentTime\",\"category\":\"Time\"},\"option\":{\"hourlySystem\":\"24\",\"format\":\"YYYY-MM-DD HH:mm:ss\",\"body\":{\"color\":\"#CFE6FF\",\"text\":\"\",\"fontWeight\":\"normal\"},\"showWeek\":\"show\",\"card\":{\"rightHref\":\"\",\"size\":\"default\",\"extra\":\"\",\"title\":\"\"}}}', 'admin', '2026-06-29 18:34:53', NULL, NULL);
