INSERT INTO `onl_graphreport_head` (`id`, `name`, `code`, `cgr_sql`, `xaxis_field`, `yaxis_field`, `yaxis_text`, `content`, `extend_js`, `graph_type`, `is_combination`, `display_template`, `data_type`, `db_source`, `tenant_id`, `low_app_id`, `create_time`, `create_by`, `update_time`, `update_by`) VALUES ('0dbeb0dfc3ec18f0ce8d1d0caeeb6095', '统计近十日的登陆次数', 'login_count_charts', 'SELECT\n	count(*) num,\n	DATE_FORMAT(create_time, \'%Y-%m-%d\') AS `day`\nFROM\n	sys_log\nWHERE\n	log_type = 1\nAND create_time > DATE_SUB(NOW(), INTERVAL 10 DAY)\nGROUP BY\n	DATE_FORMAT(create_time, \'%Y-%m-%d\')', 'day', 'num', '登陆次数', '统计登陆', '', 'line,pie,bar,table', 'combination', 'tab', 'sql', '', 0, NULL, '2019-04-11 14:36:30', 'admin', '2020-06-10 19:08:45', 'admin');
INSERT INTO `onl_graphreport_head` (`id`, `name`, `code`, `cgr_sql`, `xaxis_field`, `yaxis_field`, `yaxis_text`, `content`, `extend_js`, `graph_type`, `is_combination`, `display_template`, `data_type`, `db_source`, `tenant_id`, `low_app_id`, `create_time`, `create_by`, `update_time`, `update_by`) VALUES ('1290934362649460737', '统计男女比例', 'tj_user_bysex', 'select count(*) cout, sex from sys_user group by sex', 'sex', 'cout', 'yaxis_text', NULL, NULL, 'line,bar', 'combination', 'tab', 'sql', '', 0, NULL, '2020-08-05 16:55:11', 'admin', '2020-08-05 17:03:06', 'admin');
