INSERT INTO `onl_graphreport_head` (`id`, `name`, `code`, `cgr_sql`, `xaxis_field`, `yaxis_field`, `yaxis_text`, `content`, `extend_js`, `graph_type`, `is_combination`, `display_template`, `data_type`, `db_source`, `tenant_id`, `low_app_id`, `create_time`, `create_by`, `update_time`, `update_by`) VALUES ('3a84e175265289e1abff36be3c9f0e4a', '统计一周内步数(JS增强示例)', 'week_count_step', '[\n    {\"day\": \"星期一\", \"step\": 1234, \"assess\": \"良\"},\n    {\"day\": \"星期二\", \"step\": 1884, \"assess\": \"优\"},\n    {\"day\": \"星期三\", \"step\": 1671, \"assess\": \"良+\"},\n    {\"day\": \"星期四\", \"step\": 2197, \"assess\": \"优+\"},\n    {\"day\": \"星期五\", \"step\": 1342, \"assess\": \"中\"},\n    {\"day\": \"星期六\", \"step\": 545, \"assess\": \"差\"},\n    {\"day\": \"星期日\", \"step\": 244, \"assess\": \"极差\"}\n]', 'day', 'step', '步数', NULL, 'onClick.bar = function (event) {\n\n  var x = event.xField\n  var y = event.yField\n  var value = event.value\n\n  // 带值跳转\n  // this.$router.push(\"/isystem/user?value=\" + value)\n  \n  this.$info({\n  	title: \"点击了柱状图\",\n	content: \"X轴：\" + x + \"；Y轴：\" + y + \"；值：\" + value\n  })\n}', 'bar,line,pie,table', 'combination', 'single', 'json', NULL, 0, NULL, '2019-04-24 15:32:24', 'admin', '2020-03-24 18:43:42', 'admin');
